window.trendingPapers = {
    "today": [{"paper": {"id": "2610.13990", "authors": [{"_id": "6acee4d3abe004a210f258ff", "name": "Fanxu Meng", "hidden": false}, {"_id": "6acee4d3abe004a210f25900", "name": "Taosong Fang", "hidden": false}], "publishedAt": "2026-09-26T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "DoSA: Dots Sparse Attention", "submittedOnDailyBy": {"_id": "643f55d4ec817b766686438a", "avatarUrl": "/avatars/0feb460432c92ab9ada0d417a7a38f6a.svg", "isPro": false, "fullname": "mengfanxu", "user": "fxmeng", "type": "user", "name": "fxmeng"}, "summary": "Sparse attention visits few keys, yet finding them can still require scoring every key with every indexer head. We introduce DoSA (Dots Sparse Attention), a lossless method for making this computation conditional while preserving exact token selection. Its central observation is that Top-K selection requires sufficient evidence to reject a candidate, not necessarily its full score. A seed set supplies a lower bound on the winning threshold. Nonnegative head projections and joint residual bounds upper-bound positive contributions, while activation-informed aggregation bounds the magnitude subtracted by negative heads. The certificate directs full scoring toward candidates that remain eligible; exact-score filtering further reduces writeback and selection work. We establish the certificate and its exact-selection conditions, and analyze how geometry and selection margins govern its effectiveness. Our GPU implementation accelerates the complete Indexer by up to 2.74 times over SGLang and 1.69 times over LiteTopK across English, Chinese, and code workloads. End-to-end evaluation on GLM-5.2 and DeepSeek-V3.2 achieves up to 1.94 times and 1.50 times time-to-first-token speedups over the two baselines, respectively.", "upvotes": 26, "discussionId": "6acee4d4abe004a210f25901", "githubRepo": "https://github.com/llm-sys/flash-indexer", "githubRepoAddedBy": "user", "githubStars": 5, "organization": {"_id": "68246a0a98117c02df67a547", "name": "dots-studio", "fullname": "dots studio", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/683f0a13218449ec8f707047/K8V6vNs42cvpaTq_s6snK.png"}, "summary_zh": "<ul>\n    <li>DoSA\uff08\u70b9\u7a00\u758f\u6ce8\u610f\u529b\uff09\u662f\u4e00\u79cd\u65e0\u635f\u7684\u65b9\u6cd5\uff0c\u53ef\u4ee5\u5728\u8ba1\u7b97\u65f6\u4fdd\u6301\u6761\u4ef6\uff0c\u540c\u65f6\u786e\u4fdd\u7cbe\u786e\u7684\u4ee4\u724c\u9009\u62e9\u3002</li>\n    <li>\u901a\u8fc7\u5efa\u7acb\u79cd\u5b50\u96c6\uff0c\u63d0\u4f9b\u4e86\u4e00\u4e2a\u80dc\u51fa\u9608\u503c\u7684\u4e0b\u9650\uff0c\u4ece\u800c\u51cf\u5c11\u4e86\u5bf9\u6bcf\u4e2a\u5019\u9009\u9879\u7684\u5168\u9762\u8bc4\u5206\u7684\u9700\u6c42\u3002</li>\n    <li>\u975e\u8d1f\u5934\u6295\u5f71\u548c\u8054\u5408\u6b8b\u5dee\u754c\u5b9a\u4e86\u6b63\u8d21\u732e\u7684\u4e0a\u9650\uff0c\u800c\u6fc0\u6d3b\u4fe1\u606f\u805a\u5408\u5219\u9650\u5236\u4e86\u8d1f\u5934\u5e26\u6765\u7684\u5f71\u54cd\u3002</li>\n    <li>\u6211\u4eec\u7684\u65b9\u6cd5\u5728GPU\u4e0a\u5b9e\u73b0\u4e86\u6bd4SGLang\u5feb2.74\u500d\uff0c\u6bd4LiteTopK\u5feb1.69\u500d\u7684\u52a0\u901f\uff0c\u9002\u7528\u4e8e\u82f1\u8bed\u3001\u4e2d\u6587\u548c\u4ee3\u7801\u4efb\u52a1\u3002</li>\n    <li>\u5728GLM-5.2\u548cDeepSeek-V3.2\u7684\u7aef\u5230\u7aef\u8bc4\u4f30\u4e2d\uff0c\u5206\u522b\u5b9e\u73b0\u4e861.94\u500d\u548c1.50\u500d\u7684\u9996\u6b21\u4ee4\u724c\u901f\u5ea6\u63d0\u5347\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>DoSA (Dots Sparse Attention) is a new method that improves how we compute attention in a way that maintains the correct selection of tokens.</li>\n    <li>The method focuses on only needing to check a few candidates, rather than scoring every single one.</li>\n    <li>It uses a seed set to help determine which candidates are likely to be the best, reducing unnecessary calculations.</li>\n    <li>DoSA's implementation on GPUs makes it significantly faster, achieving up to 2.74 times speed improvement over previous methods in various tasks.</li>\n    <li>Overall, it shows major improvements in processing time for tasks like text generation compared to existing methods.</li>\n</ul>"}, "publishedAt": "2026-09-25T20:00:00.000Z", "title": "DoSA: Dots Sparse Attention", "summary": "Sparse attention visits few keys, yet finding them can still require scoring every key with every indexer head. We introduce DoSA (Dots Sparse Attention), a lossless method for making this computation conditional while preserving exact token selection. Its central observation is that Top-K selection requires sufficient evidence to reject a candidate, not necessarily its full score. A seed set supplies a lower bound on the winning threshold. Nonnegative head projections and joint residual bounds upper-bound positive contributions, while activation-informed aggregation bounds the magnitude subtracted by negative heads. The certificate directs full scoring toward candidates that remain eligible; exact-score filtering further reduces writeback and selection work. We establish the certificate and its exact-selection conditions, and analyze how geometry and selection margins govern its effectiveness. Our GPU implementation accelerates the complete Indexer by up to 2.74 times over SGLang and 1.69 times over LiteTopK across English, Chinese, and code workloads. End-to-end evaluation on GLM-5.2 and DeepSeek-V3.2 achieves up to 1.94 times and 1.50 times time-to-first-token speedups over the two baselines, respectively.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13990.png", "numComments": 1, "submittedBy": {"_id": "643f55d4ec817b766686438a", "avatarUrl": "/avatars/0feb460432c92ab9ada0d417a7a38f6a.svg", "fullname": "mengfanxu", "name": "fxmeng", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 22, "isUserFollowing": false}, "organization": {"_id": "68246a0a98117c02df67a547", "name": "dots-studio", "fullname": "dots studio", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/683f0a13218449ec8f707047/K8V6vNs42cvpaTq_s6snK.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12818", "authors": [{"_id": "6acd6cfeead72e0d3c44fbc7", "user": {"_id": "6678585635c15b509c850261", "avatarUrl": "/avatars/78d851885ff7f2d744e5b553c6c5ac06.svg", "isPro": true, "fullname": "Minghao Fu", "user": "MinghaoFu", "type": "user", "name": "MinghaoFu"}, "name": "Minghao Fu", "status": "claimed_verified", "statusLastChangedAt": "2026-10-13T00:45:05.116Z", "hidden": false}, {"_id": "6acd6cfeead72e0d3c44fbc8", "user": {"_id": "65e3f232f70c00af963b2179", "avatarUrl": "/avatars/84d97de3aeb32154b587f40cf46a5125.svg", "isPro": false, "fullname": "Tavis Siebert", "user": "tavi-sie", "type": "user", "name": "tavi-sie"}, "name": "Tavis Siebert", "status": "claimed_verified", "statusLastChangedAt": "2026-10-13T00:45:05.106Z", "hidden": false}, {"_id": "6acd6cfeead72e0d3c44fbc9", "user": {"_id": "68f7c5cfc48410ed17e25ec7", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/md_CN6FSaBpCfGuYU1sJX.jpeg", "isPro": false, "fullname": "Eryk Halicki", "user": "ehalicki", "type": "user", "name": "ehalicki"}, "name": "Eryk Halicki", "status": "claimed_verified", "statusLastChangedAt": "2026-10-14T00:45:04.864Z", "hidden": false}, {"_id": "6acd6cfeead72e0d3c44fbca", "name": "Randall Balestriero", "hidden": false}], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "LeWAM: End-to-End World and Action Modeling with JEPAs", "submittedOnDailyBy": {"_id": "6678585635c15b509c850261", "avatarUrl": "/avatars/78d851885ff7f2d744e5b553c6c5ac06.svg", "isPro": true, "fullname": "Minghao Fu", "user": "MinghaoFu", "type": "user", "name": "MinghaoFu"}, "summary": "Joint-embedding predictive architectures (JEPAs) learn compact latent world models without pixel reconstruction. Existing JEPA pipelines typically train visual representations and action-conditioned dynamics before adding a control policy or solver. We introduce LeWAM, an end-to-end JEPA for control with: (1) a joint training objective over next latent state prediction and action flow matching, and (2) an isotropic Gaussian constraint on the latent state, enabling a single model to support direct policy execution and efficient planning by evaluating sampled actions with its learned latent dynamics. Compared with prior JEPAs in visual planning, LeWAM improves success rate from 28.6% to 89.7% on contact-rich tasks and from 10.9% to 46.2% on long-horizon tasks, and plans 32.3 times faster. On behavior cloning tasks in simulation and physical robots, LeWAM is also competitive with established methods. Interpretability analyses show that LeWAM learns control-relevant representations and action distributions effectively guiding test-time planning and control.", "upvotes": 22, "discussionId": "6acd6cffead72e0d3c44fbcb", "projectPage": "https://le-wam.github.io/", "githubRepo": "https://github.com/MinghaoFu/lewam", "githubRepoAddedBy": "user", "githubStars": 228, "organization": {"_id": "6ac2f6069f39a66f240523a6", "name": "LeWAM", "fullname": "LeWAM", "avatar": "https://www.gravatar.com/avatar/13a0ac54a3ef634d52eeebaed58ebaeb?d=retro&size=100"}, "summary_zh": "<ul>\n    <li>LeWAM\u662f\u4e00\u79cd\u65b0\u578b\u7684\u8054\u5408\u5d4c\u5165\u9884\u6d4b\u67b6\u6784\uff08JEPA\uff09\uff0c\u53ef\u4ee5\u5b66\u4e60\u7d27\u51d1\u7684\u6f5c\u5728\u4e16\u754c\u6a21\u578b\uff0c\u800c\u65e0\u9700\u50cf\u7d20\u91cd\u5efa\u3002</li>\n    <li>\u5b83\u901a\u8fc7\u5171\u540c\u8bad\u7ec3\u4e0b\u4e00\u4e2a\u6f5c\u5728\u72b6\u6001\u9884\u6d4b\u548c\u52a8\u4f5c\u6d41\u5339\u914d\u6765\u4f18\u5316\u63a7\u5236\u7b56\u7565\u3002</li>\n    <li>LeWAM\u5f15\u5165\u4e86\u5bf9\u6f5c\u5728\u72b6\u6001\u7684\u7b49\u65b9\u5dee\u9ad8\u65af\u7ea6\u675f\uff0c\u4f7f\u5f97\u6a21\u578b\u80fd\u591f\u76f4\u63a5\u6267\u884c\u7b56\u7565\u548c\u9ad8\u6548\u89c4\u5212\u3002</li>\n    <li>\u5728\u590d\u6742\u4efb\u52a1\u4e2d\uff0cLeWAM\u7684\u6210\u529f\u7387\u663e\u8457\u63d0\u9ad8\uff0c\u4ece28.6%\u63d0\u5347\u523089.7%\uff0c\u5e76\u4e14\u89c4\u5212\u901f\u5ea6\u5feb\u4e8632.3\u500d\u3002</li>\n    <li>LeWAM\u5728\u6a21\u62df\u548c\u7269\u7406\u673a\u5668\u4eba\u884c\u4e3a\u514b\u9686\u4efb\u52a1\u4e2d\u8868\u73b0\u51fa\u8272\uff0c\u5e76\u4e14\u80fd\u591f\u6709\u6548\u6307\u5bfc\u6d4b\u8bd5\u65f6\u7684\u89c4\u5212\u548c\u63a7\u5236\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>LeWAM is a new model that helps control systems learn without needing to recreate images.</li>\n    <li>It trains to predict future states and matches actions, allowing better control in tasks.</li>\n    <li>LeWAM significantly improves success rates in complex tasks and plans actions much faster than previous models.</li>\n    <li>It performs well in both simulations and real robots, competing with established methods.</li>\n    <li>LeWAM effectively learns useful representations that help with planning and controlling actions during tests.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "LeWAM: End-to-End World and Action Modeling with JEPAs", "summary": "Joint-embedding predictive architectures (JEPAs) learn compact latent world models without pixel reconstruction. Existing JEPA pipelines typically train visual representations and action-conditioned dynamics before adding a control policy or solver. We introduce LeWAM, an end-to-end JEPA for control with: (1) a joint training objective over next latent state prediction and action flow matching, and (2) an isotropic Gaussian constraint on the latent state, enabling a single model to support direct policy execution and efficient planning by evaluating sampled actions with its learned latent dynamics. Compared with prior JEPAs in visual planning, LeWAM improves success rate from 28.6% to 89.7% on contact-rich tasks and from 10.9% to 46.2% on long-horizon tasks, and plans 32.3 times faster. On behavior cloning tasks in simulation and physical robots, LeWAM is also competitive with established methods. Interpretability analyses show that LeWAM learns control-relevant representations and action distributions effectively guiding test-time planning and control.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12818.png", "numComments": 1, "submittedBy": {"_id": "6678585635c15b509c850261", "avatarUrl": "/avatars/78d851885ff7f2d744e5b553c6c5ac06.svg", "fullname": "Minghao Fu", "name": "MinghaoFu", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6ac2f6069f39a66f240523a6", "name": "LeWAM", "fullname": "LeWAM", "avatar": "https://www.gravatar.com/avatar/13a0ac54a3ef634d52eeebaed58ebaeb?d=retro&size=100"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.14709", "authors": [{"_id": "6aced6c1abe004a210f2589b", "name": "Yang Xiao", "hidden": false}, {"_id": "6aced6c1abe004a210f2589c", "name": "Yusong Sun", "hidden": false}, {"_id": "6aced6c1abe004a210f2589d", "name": "Haoyi Wu", "hidden": false}, {"_id": "6aced6c1abe004a210f2589e", "name": "Wenyang Hui", "hidden": false}, {"_id": "6aced6c1abe004a210f2589f", "name": "Weiqiang Hang", "hidden": false}, {"_id": "6aced6c1abe004a210f258a0", "name": "Luqing Wang", "hidden": false}, {"_id": "6aced6c1abe004a210f258a1", "name": "Zejian Wang", "hidden": false}, {"_id": "6aced6c1abe004a210f258a2", "name": "Zirui Tu", "hidden": false}, {"_id": "6aced6c1abe004a210f258a3", "name": "Jingsheng Mao", "hidden": false}, {"_id": "6aced6c1abe004a210f258a4", "name": "Shaobo Hu", "hidden": false}, {"_id": "6aced6c1abe004a210f258a5", "name": "Yang Luo", "hidden": false}, {"_id": "6aced6c1abe004a210f258a6", "name": "Jiale Guo", "hidden": false}, {"_id": "6aced6c1abe004a210f258a7", "name": "Jin Zhang", "hidden": false}, {"_id": "6aced6c1abe004a210f258a8", "name": "Yudan Liu", "hidden": false}, {"_id": "6aced6c1abe004a210f258a9", "name": "Zhaokai Luo", "hidden": false}, {"_id": "6aced6c1abe004a210f258aa", "name": "Ren Huan", "hidden": false}, {"_id": "6aced6c1abe004a210f258ab", "name": "Yao Hu", "hidden": false}, {"_id": "6aced6c1abe004a210f258ac", "name": "Chengyue Jiang", "hidden": false}, {"_id": "6aced6c1abe004a210f258ad", "name": "Wenjie Li", "hidden": false}, {"_id": "6aced6c1abe004a210f258ae", "name": "Chuan Mu", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6002c316698168af3bb9f4a6/vvbatqTGg2YCQrLXZdM40.png", "https://cdn-uploads.huggingface.co/production/uploads/6002c316698168af3bb9f4a6/no9d6h6vHxvtomEJZPJs7.png", "https://cdn-uploads.huggingface.co/production/uploads/6002c316698168af3bb9f4a6/a2tgJ_9GVEh0m5p2pwenK.png"], "publishedAt": "2026-10-10T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "Vela: User Behavior as Supervision Sparks LLM Intelligence", "submittedOnDailyBy": {"_id": "6002c316698168af3bb9f4a6", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6002c316698168af3bb9f4a6/M2J2QFCRc5RhYRoz7OuZN.png", "isPro": false, "fullname": "yangxiao", "user": "YangXiao-nlp", "type": "user", "name": "YangXiao-nlp"}, "summary": "Large language models are increasingly deployed in applications that act on users' long-term behavior histories, from personal assistants to recommendation and advertising systems. These applications demand the user dimension of LLM intelligence: inferring a person's preferences, intent, and likely future actions from weeks to years of behavior data. Yet current models are trained on static text or synthetic data, neither of which captures how user behavior evolves over time. Real-world behavior records, already available at scale on content platforms and in personal-assistant agents, offer a natural supervisory signal. We propose user behavior as supervision and introduce Vela, a framework that converts real user behavior data into trainable tasks and trajectories. From the anonymized behavior records of 100,000 users, Vela generates 100,000 tasks across 91 real-world task templates; difficulty-based filtering and trajectory acceptance criteria retain approximately 75,000 tasks with selected training trajectories. Fine-tuning Qwen3.6-35B-A3B on these trajectories improves performance over the base model by up to 11.5 points on user-related tasks and by an average of 4 points on general benchmarks. Training on more user behavior data further improves user-related performance, and reinforcement learning after fine-tuning outperforms reinforcement learning from the base model by up to 7.7 points. These gains suggest that real-world user behavior is a scalable source of supervision for both user-centered capabilities and the broader intelligence of LLMs.", "upvotes": 16, "discussionId": "6aced6c1abe004a210f258af", "projectPage": "https://allspark-research.github.io/Vela/", "githubRepo": "https://github.com/AllSpark-Research/Vela", "githubRepoAddedBy": "user", "githubStars": 9, "organization": {"_id": "6a96bf5bae44840b913e27b8", "name": "AllSpark-Research", "fullname": "AllSpark Research", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6a96be78642bb1433bbbf002/e9W8yeoVttMzcdc_Z_VrR.png"}, "summary_zh": "<ul>\n    <li>\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u88ab\u5e7f\u6cdb\u5e94\u7528\u4e8e\u57fa\u4e8e\u7528\u6237\u957f\u671f\u884c\u4e3a\u5386\u53f2\u7684\u7cfb\u7edf\uff0c\u5982\u4e2a\u4eba\u52a9\u624b\u548c\u63a8\u8350\u5e7f\u544a\u7cfb\u7edf\u3002</li>\n    <li>\u73b0\u6709\u6a21\u578b\u4e3b\u8981\u8bad\u7ec3\u4e8e\u9759\u6001\u6587\u672c\u6216\u5408\u6210\u6570\u636e\uff0c\u65e0\u6cd5\u6355\u6349\u7528\u6237\u884c\u4e3a\u968f\u65f6\u95f4\u7684\u53d8\u5316\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u201c\u7528\u6237\u884c\u4e3a\u4f5c\u4e3a\u76d1\u7763\u201d\u7684\u65b9\u6cd5\uff0c\u5e76\u5f15\u5165\u4e86Vela\u6846\u67b6\uff0c\u5c06\u771f\u5b9e\u7528\u6237\u884c\u4e3a\u6570\u636e\u8f6c\u5316\u4e3a\u53ef\u8bad\u7ec3\u7684\u4efb\u52a1\u548c\u8f68\u8ff9\u3002</li>\n    <li>\u901a\u8fc7\u5206\u679010\u4e07\u7528\u6237\u7684\u533f\u540d\u884c\u4e3a\u8bb0\u5f55\uff0cVela\u751f\u6210\u4e8610\u4e07\u4e2a\u4efb\u52a1\uff0c\u7b5b\u9009\u51fa\u7ea67.5\u4e07\u4e2a\u9ad8\u8d28\u91cf\u4efb\u52a1\u8fdb\u884c\u8bad\u7ec3\u3002</li>\n    <li>\u5bf9\u6a21\u578b\u8fdb\u884c\u5fae\u8c03\u540e\uff0c\u5728\u7528\u6237\u76f8\u5173\u4efb\u52a1\u4e0a\u7684\u8868\u73b0\u63d0\u9ad8\u4e86\u6700\u591a11.5\u5206\uff0c\u4e14\u4f7f\u7528\u66f4\u591a\u7528\u6237\u884c\u4e3a\u6570\u636e\u53ef\u8fdb\u4e00\u6b65\u63d0\u5347\u6027\u80fd\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Large language models (LLMs) are used in applications that analyze users' long-term behavior, like personal assistants and recommendation systems.</li>\n    <li>Current models don't effectively use real user behavior data, as they are trained on static text or synthetic data.</li>\n    <li>The Vela framework uses real user behavior data to create trainable tasks and improve LLM performance.</li>\n    <li>By analyzing data from 100,000 users, Vela generated 100,000 tasks, improving model performance on user-related tasks significantly.</li>\n    <li>This approach shows that real-world user behavior can be an effective way to enhance LLM capabilities and overall intelligence.</li>\n</ul>"}, "publishedAt": "2026-10-09T20:00:00.000Z", "title": "Vela: User Behavior as Supervision Sparks LLM Intelligence", "summary": "Large language models are increasingly deployed in applications that act on users' long-term behavior histories, from personal assistants to recommendation and advertising systems. These applications demand the user dimension of LLM intelligence: inferring a person's preferences, intent, and likely future actions from weeks to years of behavior data. Yet current models are trained on static text or synthetic data, neither of which captures how user behavior evolves over time. Real-world behavior records, already available at scale on content platforms and in personal-assistant agents, offer a natural supervisory signal. We propose user behavior as supervision and introduce Vela, a framework that converts real user behavior data into trainable tasks and trajectories. From the anonymized behavior records of 100,000 users, Vela generates 100,000 tasks across 91 real-world task templates; difficulty-based filtering and trajectory acceptance criteria retain approximately 75,000 tasks with selected training trajectories. Fine-tuning Qwen3.6-35B-A3B on these trajectories improves performance over the base model by up to 11.5 points on user-related tasks and by an average of 4 points on general benchmarks. Training on more user behavior data further improves user-related performance, and reinforcement learning after fine-tuning outperforms reinforcement learning from the base model by up to 7.7 points. These gains suggest that real-world user behavior is a scalable source of supervision for both user-centered capabilities and the broader intelligence of LLMs.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6002c316698168af3bb9f4a6/vvbatqTGg2YCQrLXZdM40.png", "https://cdn-uploads.huggingface.co/production/uploads/6002c316698168af3bb9f4a6/no9d6h6vHxvtomEJZPJs7.png", "https://cdn-uploads.huggingface.co/production/uploads/6002c316698168af3bb9f4a6/a2tgJ_9GVEh0m5p2pwenK.png"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.14709.png", "numComments": 5, "submittedBy": {"_id": "6002c316698168af3bb9f4a6", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6002c316698168af3bb9f4a6/M2J2QFCRc5RhYRoz7OuZN.png", "fullname": "yangxiao", "name": "YangXiao-nlp", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 13, "isUserFollowing": false}, "organization": {"_id": "6a96bf5bae44840b913e27b8", "name": "AllSpark-Research", "fullname": "AllSpark Research", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6a96be78642bb1433bbbf002/e9W8yeoVttMzcdc_Z_VrR.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.14224", "authors": [{"_id": "6acee61fabe004a210f25904", "name": "Ruiyao Xu", "hidden": false}, {"_id": "6acee61fabe004a210f25905", "name": "Yanfei Chen", "hidden": false}, {"_id": "6acee61fabe004a210f25906", "name": "Zhongying CuiZhu", "hidden": false}, {"_id": "6acee61fabe004a210f25907", "name": "Bhavana Dalvi Mishra", "hidden": false}, {"_id": "6acee61fabe004a210f25908", "name": "Yifei Ming", "hidden": false}, {"_id": "6acee61fabe004a210f25909", "name": "Han Yu", "hidden": false}, {"_id": "6acee61fabe004a210f2590a", "name": "Rujun Han", "hidden": false}, {"_id": "6acee61fabe004a210f2590b", "name": "Chen-Yu Lee", "hidden": false}, {"_id": "6acee61fabe004a210f2590c", "name": "Tomas Pfister", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "Harness^2: Recursive Agent Harnessing for an Open World", "submittedOnDailyBy": {"_id": "66e477a352356419c4712065", "avatarUrl": "/avatars/cd2969ce88e44735c3fe70312c0e64b3.svg", "isPro": true, "fullname": "Ruiyao Xu", "user": "ruiyaox", "type": "user", "name": "ruiyaox"}, "summary": "LLM agents' capabilities depend not only on their underlying models but also on their execution harnesses. Recursive self-improvement (RSI) offers a promising approach to automatically evolve these harnesses. However, deploying RSI in open-world settings still faces two critical challenges. First, open-world tasks are typically unseen during the harness design phase and novel at test time, leaving no ground-truth verifiers to reliably guide online harness edits. Second, the RSI process remains highly task-specific and fails to generalize to novel scenarios. We introduce Harness^2, a plug-and-play, recursive agent harnessing framework that addresses these challenges through two connected levels of recursion. Task-level recursion refines the current task's harness using a contrastive Propose-Probe-Compose step that reliably guides edits without ground-truth verifiers, and can be scaled further via parallel or sequential recursion. Harnessing-level recursion then extracts experience from these edits to update a continual improvement harness, enabling the agent to better adapt to future tasks. Across three professional benchmarks and four model-harness configurations, a single step consistently improves GLM-5 and Gemini 3.5 Flash over their base harnesses, yielding gains of up to 11.5 points on WorkBuddy-Bench, 4.5 points on JobBench, and 11.8 percentage points on LAB, with further gains as the task-level recursion budget increases.", "upvotes": 14, "discussionId": "6acee61fabe004a210f2590d", "projectPage": "https://harness2.github.io/", "githubRepo": "https://github.com/google-research/harness2", "githubRepoAddedBy": "user", "githubStars": 6, "organization": {"_id": "5e6aca39878b8b2bf9806447", "name": "google", "fullname": "Google", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/WtA3YYitedOr9n02eHfJe.png"}, "summary_zh": "<ul>\n    <li>LLM\uff08\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff09\u4ee3\u7406\u7684\u80fd\u529b\u4f9d\u8d56\u4e8e\u6a21\u578b\u548c\u6267\u884c\u6846\u67b6\u3002</li>\n    <li>\u9012\u5f52\u81ea\u6211\u6539\u8fdb\uff08RSI\uff09\u662f\u4e00\u79cd\u80fd\u591f\u81ea\u52a8\u6f14\u5316\u6267\u884c\u6846\u67b6\u7684\u65b9\u6cd5\uff0c\u4f46\u5728\u5f00\u653e\u4e16\u754c\u4e2d\u5e94\u7528\u9762\u4e34\u6311\u6218\u3002</li>\n    <li>\u7b2c\u4e00\u4e2a\u6311\u6218\u662f\u5f00\u653e\u4e16\u754c\u4efb\u52a1\u5728\u8bbe\u8ba1\u9636\u6bb5\u65e0\u6cd5\u9884\u6d4b\uff0c\u7f3a\u4e4f\u53ef\u9760\u7684\u9a8c\u8bc1\u6807\u51c6\u3002</li>\n    <li>\u7b2c\u4e8c\u4e2a\u6311\u6218\u662fRSI\u8fc7\u7a0b\u8fc7\u4e8e\u7279\u5b9a\uff0c\u96be\u4ee5\u63a8\u5e7f\u5230\u65b0\u573a\u666f\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86Harness\u00b2\u6846\u67b6\uff0c\u901a\u8fc7\u4efb\u52a1\u7ea7\u548c\u6267\u884c\u7ea7\u7684\u9012\u5f52\u6765\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\uff0c\u663e\u8457\u63d0\u5347\u4e86\u6a21\u578b\u7684\u8868\u73b0\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>LLM agents work better with good execution frameworks and can improve themselves using a method called Recursive Self-Improvement (RSI).</li>\n    <li>Two main challenges with RSI in real-world settings are: tasks are often new and untested, and RSI struggles to adapt to different types of tasks.</li>\n    <li>The new framework, Harness^2, helps by using two levels of recursion to refine the agent's performance on tasks and learn from those improvements.</li>\n    <li>Task-level recursion makes edits to the harness without needing known correct answers, while harnessing-level recursion uses the lessons learned to prepare for future tasks.</li>\n    <li>Testing showed that using Harness^2 improved the performance of models like GLM-5 and Gemini 3.5 Flash on various benchmarks by significant margins.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Harness^2: Recursive Agent Harnessing for an Open World", "summary": "LLM agents' capabilities depend not only on their underlying models but also on their execution harnesses. Recursive self-improvement (RSI) offers a promising approach to automatically evolve these harnesses. However, deploying RSI in open-world settings still faces two critical challenges. First, open-world tasks are typically unseen during the harness design phase and novel at test time, leaving no ground-truth verifiers to reliably guide online harness edits. Second, the RSI process remains highly task-specific and fails to generalize to novel scenarios. We introduce Harness^2, a plug-and-play, recursive agent harnessing framework that addresses these challenges through two connected levels of recursion. Task-level recursion refines the current task's harness using a contrastive Propose-Probe-Compose step that reliably guides edits without ground-truth verifiers, and can be scaled further via parallel or sequential recursion. Harnessing-level recursion then extracts experience from these edits to update a continual improvement harness, enabling the agent to better adapt to future tasks. Across three professional benchmarks and four model-harness configurations, a single step consistently improves GLM-5 and Gemini 3.5 Flash over their base harnesses, yielding gains of up to 11.5 points on WorkBuddy-Bench, 4.5 points on JobBench, and 11.8 percentage points on LAB, with further gains as the task-level recursion budget increases.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.14224.png", "numComments": 1, "submittedBy": {"_id": "66e477a352356419c4712065", "avatarUrl": "/avatars/cd2969ce88e44735c3fe70312c0e64b3.svg", "fullname": "Ruiyao Xu", "name": "ruiyaox", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "5e6aca39878b8b2bf9806447", "name": "google", "fullname": "Google", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/WtA3YYitedOr9n02eHfJe.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.15028", "authors": [{"_id": "6acef135abe004a210f2598a", "name": "Jungwoo Park", "hidden": false}, {"_id": "6acef135abe004a210f2598b", "name": "Taewhoo Lee", "hidden": false}, {"_id": "6acef135abe004a210f2598c", "name": "Jaewoo Kang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/60f8435644e75317cc02ed51/UUkif09gxAE0TXgIJgd8C.jpeg"], "publishedAt": "2026-10-10T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "UltraBERT: Beyond the Limit of BERT Pre-Training", "submittedOnDailyBy": {"_id": "60f8435644e75317cc02ed51", "avatarUrl": "/avatars/68b7fc077fe2bda6607b1c470add8140.svg", "isPro": false, "fullname": "Jungwoo Park", "user": "affjljoo3581", "type": "user", "name": "affjljoo3581"}, "summary": "Recent bidirectional encoders have been modernized with innovations from causal large language models (LLMs). However, the pretraining recipe itself remains inherited from small-scale conventions, leaving encoders underoptimized, with no single model performing competitively across both classification and retrieval tasks. In this work, we investigate how far encoder performance can be pushed by revisiting core design choices in training, revealing three key findings: (1) Encoders saturate on downstream tasks beyond a few trillion tokens, indicating that additional compute past this point does not help. (2) Across model sizes, lower masking ratios benefit classification while higher ones benefit retrieval, contradicting prior work suggesting larger ratios for larger models. (3) Distillation with pruning improves classification at low masking ratios but degrades retrieval at high ones. Guided by these findings, we present UltraBERT, a single encoder that assigns separate LM heads to low and high masking ratios within a batch and restricts the distillation objective to the low ratio. To our knowledge, UltraBERT is the first encoder to achieve state of the art on both classification and retrieval tasks, reaching 91.0 on GLUE and 47.7 on BEIR. Together, these results show how far encoder performance can be pushed and provide a principled basis for compute allocation, masking ratio design, and knowledge transfer in bidirectional models.", "upvotes": 13, "discussionId": "6acef135abe004a210f2598d", "summary_zh": "<ul>\n    <li>\u6700\u8fd1\u7684\u53cc\u5411\u7f16\u7801\u5668\u501f\u9274\u4e86\u56e0\u679c\u5927\u578b\u8bed\u8a00\u6a21\u578b\u7684\u521b\u65b0\uff0c\u4f46\u9884\u8bad\u7ec3\u65b9\u6cd5\u4ecd\u7136\u6cbf\u7528\u5c0f\u89c4\u6a21\u60ef\u4f8b\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\uff0c\u7f16\u7801\u5668\u5728\u4e0b\u6e38\u4efb\u52a1\u4e0a\u8d85\u8fc7\u51e0\u4e07\u4ebf\u4e2a\u6807\u8bb0\u540e\u6027\u80fd\u9971\u548c\uff0c\u989d\u5916\u7684\u8ba1\u7b97\u6ca1\u6709\u5e2e\u52a9\u3002</li>\n    <li>\u8f83\u4f4e\u7684\u63a9\u7801\u6bd4\u4f8b\u6709\u52a9\u4e8e\u5206\u7c7b\uff0c\u800c\u8f83\u9ad8\u7684\u6bd4\u4f8b\u5219\u6709\u52a9\u4e8e\u68c0\u7d22\uff0c\u8fd9\u4e0e\u4e4b\u524d\u7684\u7814\u7a76\u76f8\u77db\u76fe\u3002</li>\n    <li>\u901a\u8fc7\u526a\u679d\u7684\u84b8\u998f\u53ef\u4ee5\u6539\u5584\u4f4e\u63a9\u7801\u6bd4\u4f8b\u4e0b\u7684\u5206\u7c7b\uff0c\u4f46\u5728\u9ad8\u63a9\u7801\u6bd4\u4f8b\u4e0b\u4f1a\u964d\u4f4e\u68c0\u7d22\u6027\u80fd\u3002</li>\n    <li>UltraBERT\u662f\u9996\u4e2a\u5728\u5206\u7c7b\u548c\u68c0\u7d22\u4efb\u52a1\u4e2d\u8fbe\u5230\u6700\u4f73\u6027\u80fd\u7684\u7f16\u7801\u5668\uff0c\u5206\u522b\u5728GLUE\u548cBEIR\u4e0a\u83b7\u5f9791.0\u548c47.7\u7684\u5206\u6570\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Recent improvements in bidirectional encoders are influenced by advancements in large language models, but they are still not fully optimized for both classification and retrieval tasks.</li>\n    <li>The study found that encoders reach their maximum performance after processing a few trillion tokens, and additional training does not help beyond that.</li>\n    <li>Lower masking ratios are better for classification tasks, while higher ratios are beneficial for retrieval tasks, which goes against previous beliefs.</li>\n    <li>Using distillation with pruning enhances classification performance at low masking ratios but negatively affects retrieval performance at high ratios.</li>\n    <li>The new model, UltraBERT, is the first to excel in both classification and retrieval tasks, achieving top scores on popular benchmarks like GLUE and BEIR.</li>\n</ul>"}, "publishedAt": "2026-10-09T20:00:00.000Z", "title": "UltraBERT: Beyond the Limit of BERT Pre-Training", "summary": "Recent bidirectional encoders have been modernized with innovations from causal large language models (LLMs). However, the pretraining recipe itself remains inherited from small-scale conventions, leaving encoders underoptimized, with no single model performing competitively across both classification and retrieval tasks. In this work, we investigate how far encoder performance can be pushed by revisiting core design choices in training, revealing three key findings: (1) Encoders saturate on downstream tasks beyond a few trillion tokens, indicating that additional compute past this point does not help. (2) Across model sizes, lower masking ratios benefit classification while higher ones benefit retrieval, contradicting prior work suggesting larger ratios for larger models. (3) Distillation with pruning improves classification at low masking ratios but degrades retrieval at high ones. Guided by these findings, we present UltraBERT, a single encoder that assigns separate LM heads to low and high masking ratios within a batch and restricts the distillation objective to the low ratio. To our knowledge, UltraBERT is the first encoder to achieve state of the art on both classification and retrieval tasks, reaching 91.0 on GLUE and 47.7 on BEIR. Together, these results show how far encoder performance can be pushed and provide a principled basis for compute allocation, masking ratio design, and knowledge transfer in bidirectional models.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/60f8435644e75317cc02ed51/UUkif09gxAE0TXgIJgd8C.jpeg"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.15028.png", "numComments": 1, "submittedBy": {"_id": "60f8435644e75317cc02ed51", "avatarUrl": "/avatars/68b7fc077fe2bda6607b1c470add8140.svg", "fullname": "Jungwoo Park", "name": "affjljoo3581", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "isAuthorParticipating": false}, {"paper": {"id": "2610.14118", "authors": [{"_id": "6acef609abe004a210f259f1", "name": "Hansi Yang", "hidden": false}, {"_id": "6acef609abe004a210f259f2", "name": "Linji Hao", "hidden": false}, {"_id": "6acef609abe004a210f259f3", "name": "Hongyan Hao", "hidden": false}, {"_id": "6acef609abe004a210f259f4", "name": "An Wang", "hidden": false}, {"_id": "6acef609abe004a210f259f5", "name": "Han Wu", "hidden": false}, {"_id": "6acef609abe004a210f259f6", "name": "Qi Gu", "hidden": false}, {"_id": "6acef609abe004a210f259f7", "name": "Xunliang Cai", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "ClawLoop: Self-Improving Agents via Harness-Native Training Loop", "submittedOnDailyBy": {"_id": "65ced159d82f8d722c78e0cf", "avatarUrl": "/avatars/a7121348e4fe77055533f14cda7f90b8.svg", "isPro": false, "fullname": "Hansi Yang", "user": "animawang", "type": "user", "name": "animawang"}, "summary": "The rapid advancement of Large Language Models (LLMs) has driven their deployment toward general-purpose harness environments, where LLM-based agents operate in sandbox workspaces and interact directly with file systems and shells. While numerous post-training pipelines exist for tool-use agents, their counterparts for harness-based agents remain scarce and are predominantly one-shot and teacher-dependent: a stronger external model synthesizes tasks and collects trajectories, the target agent is trained once, and evaluation results are consumed by human researchers rather than fed back into the loop. Such pipelines are inherently bounded by the capability of the external model and the scope of human prior, leaving no room for self-improvement. To address these limitations, we propose ClawLoop, a framework that enables self-improving without any external teacher model and with minimal prior dependencies. ClawLoop composes three phases into a self-sustaining cycle: Task Synthesis, which generates a diverse pool of training tasks via two complementary construction routines, applies diagnosis-conditioned difficulty growth followed by both agent-free and agent-based task validation; Training, which updates the agent via SFT and/or RL; and Diagnosis and Feedback, which analyzes the agent's rollout behaviors to produce a capability analysis report that will be used as feedback for task synthesis in the next iteration. Using Qwen3.6-27B as the loop model, ClawLoop yields consistent improvements on SkillsBench, Claw-Eval-Live, and ClawGym-Bench. The iteratively refined tasks are further transferred to smaller-scale Qwen3.5-4B and 9B models with gains across all benchmarks, validating data quality independently of the loop model.", "upvotes": 8, "discussionId": "6acef609abe004a210f259f8", "organization": {"_id": "68b28d79a176a9beb30d2049", "name": "meituan-longcat", "fullname": "LongCat", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68a2a29ab9d4c5698e02c747/CDCAx7X7rXDt7xjI-DoxG.png"}, "summary_zh": "<ul>\n    <li>\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLMs\uff09\u7684\u5feb\u901f\u53d1\u5c55\u4fc3\u4f7f\u5b83\u4eec\u5728\u901a\u7528\u73af\u5883\u4e2d\u88ab\u5e7f\u6cdb\u4f7f\u7528\u3002</li>\n    <li>\u76ee\u524d\u9488\u5bf9\u5de5\u5177\u4f7f\u7528\u4ee3\u7406\u7684\u540e\u8bad\u7ec3\u6d41\u7a0b\u8f83\u591a\uff0c\u4f46\u9488\u5bf9\u57fa\u4e8e\u73af\u5883\u7684\u4ee3\u7406\u7684\u6d41\u7a0b\u5219\u8f83\u5c11\uff0c\u4e14\u5e38\u5e38\u4f9d\u8d56\u5916\u90e8\u6559\u5e08\u6a21\u578b\u3002</li>\n    <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\uff0c\u63d0\u51fa\u4e86ClawLoop\u6846\u67b6\uff0c\u4f7f\u4ee3\u7406\u80fd\u591f\u81ea\u6211\u6539\u8fdb\uff0c\u65e0\u9700\u5916\u90e8\u6559\u5e08\u6a21\u578b\u3002</li>\n    <li>ClawLoop\u5305\u62ec\u4e09\u4e2a\u9636\u6bb5\uff1a\u4efb\u52a1\u5408\u6210\u3001\u8bad\u7ec3\u548c\u8bca\u65ad\u53cd\u9988\uff0c\u5f62\u6210\u4e00\u4e2a\u81ea\u6211\u7ef4\u6301\u7684\u5faa\u73af\u3002</li>\n    <li>\u4f7f\u7528Qwen3.6-27B\u6a21\u578b\u8fdb\u884c\u6d4b\u8bd5\uff0cClawLoop\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u663e\u793a\u51fa\u6301\u7eed\u6539\u8fdb\uff0c\u4e14\u5c0f\u89c4\u6a21\u6a21\u578b\u4e5f\u80fd\u4ece\u4e2d\u83b7\u76ca\u3002</li>\n</ul>", "summary_simple": "<ul>\n  <li>Large Language Models (LLMs) are being used in environments where they can interact with files and systems directly.</li>\n  <li>Existing methods for training these models are limited and rely heavily on external guidance and human evaluation.</li>\n  <li>The proposed framework, ClawLoop, allows models to improve themselves without needing an external teacher or much prior information.</li>\n  <li>ClawLoop consists of three phases: generating training tasks, updating the model, and analyzing results for future improvements.</li>\n  <li>Using ClawLoop has shown consistent improvements in performance across various benchmarks, even when applied to smaller models.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "ClawLoop: Self-Improving Agents via Harness-Native Training Loop", "summary": "The rapid advancement of Large Language Models (LLMs) has driven their deployment toward general-purpose harness environments, where LLM-based agents operate in sandbox workspaces and interact directly with file systems and shells. While numerous post-training pipelines exist for tool-use agents, their counterparts for harness-based agents remain scarce and are predominantly one-shot and teacher-dependent: a stronger external model synthesizes tasks and collects trajectories, the target agent is trained once, and evaluation results are consumed by human researchers rather than fed back into the loop. Such pipelines are inherently bounded by the capability of the external model and the scope of human prior, leaving no room for self-improvement. To address these limitations, we propose ClawLoop, a framework that enables self-improving without any external teacher model and with minimal prior dependencies. ClawLoop composes three phases into a self-sustaining cycle: Task Synthesis, which generates a diverse pool of training tasks via two complementary construction routines, applies diagnosis-conditioned difficulty growth followed by both agent-free and agent-based task validation; Training, which updates the agent via SFT and/or RL; and Diagnosis and Feedback, which analyzes the agent's rollout behaviors to produce a capability analysis report that will be used as feedback for task synthesis in the next iteration. Using Qwen3.6-27B as the loop model, ClawLoop yields consistent improvements on SkillsBench, Claw-Eval-Live, and ClawGym-Bench. The iteratively refined tasks are further transferred to smaller-scale Qwen3.5-4B and 9B models with gains across all benchmarks, validating data quality independently of the loop model.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.14118.png", "numComments": 1, "submittedBy": {"_id": "65ced159d82f8d722c78e0cf", "avatarUrl": "/avatars/a7121348e4fe77055533f14cda7f90b8.svg", "fullname": "Hansi Yang", "name": "animawang", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "68b28d79a176a9beb30d2049", "name": "meituan-longcat", "fullname": "LongCat", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68a2a29ab9d4c5698e02c747/CDCAx7X7rXDt7xjI-DoxG.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.15208", "authors": [{"_id": "6acee085abe004a210f258f6", "name": "M. Yigit Turali", "hidden": false}, {"_id": "6acee085abe004a210f258f7", "name": "Shreyas Rajesh", "hidden": false}, {"_id": "6acee085abe004a210f258f8", "name": "M. Efe Lorasdagi", "hidden": false}, {"_id": "6acee085abe004a210f258f9", "name": "Chenda Duan", "hidden": false}, {"_id": "6acee085abe004a210f258fa", "name": "Kartik Sharma", "hidden": false}, {"_id": "6acee085abe004a210f258fb", "name": "Vwani Roychowdhury", "hidden": false}], "publishedAt": "2026-10-10T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "PANINI-DR: Controlled Deep Research through Generative Semantic Workspaces", "submittedOnDailyBy": {"_id": "6686f852a03abfbb1b5ac5b6", "avatarUrl": "/avatars/8d4289a71da6b90064be6aa84dc5debc.svg", "isPro": false, "fullname": "Mehmet Yigit Turali", "user": "yigitturali", "type": "user", "name": "yigitturali"}, "summary": "Deep research requires connecting multiple steps of search, reasoning, and computation, with intermediate findings guiding what to investigate next. As investigations grow, agents must maintain research state across model calls and check findings before errors propagate into subsequent work. We introduce PANINI-DR, a multi-agent harness that separates coordination of the overall investigation from the research and verification of individual subquestions. A shared workspace, built on the Generative Semantic Workspace representation, records subquestions, their dependencies, findings, and supporting evidence. Researchers investigate individual subquestions, while a separate verification agent checks proposed answers against those subquestions and their evidence. Verification feedback guides further investigation, and recorded findings inform subsequent assignments. We evaluate PANINI-DR on BrowseComp-Plus, FRAMES, and MoNaCo against seven state-of-the-art deep-research harnesses, all using a shared language-model backbone and frozen corpora. PANINI-DR achieves the strongest average performance across the three benchmarks. On BrowseComp-Plus, it achieves 73.3% accuracy, outperforming the next-best harness by 16.0 points. Its advantage is strongest on hard questions, where it answers nearly twice as many as the next-best harness. Ablations further show that structured planning and persistent state improve performance, as does checking each finding against its cited evidence before it is reused. Because a model can answer correctly from memory alone, we also analyze the evidence retained by each harness. PANINI-DR achieves the highest answer recoverability from saved evidence on all three benchmarks, while complementary claim-support audits show stronger evidence-backed answers. Accounting for this evidence changes how harnesses compare and further strengthens PANINI-DR's advantage.", "upvotes": 6, "discussionId": "6acee085abe004a210f258fc", "summary_zh": "<ul>\n    <li>PANINI-DR \u662f\u4e00\u4e2a\u591a\u667a\u80fd\u4f53\u7cfb\u7edf\uff0c\u7528\u4e8e\u6df1\u5ea6\u7814\u7a76\uff0c\u80fd\u591f\u66f4\u597d\u5730\u534f\u8c03\u7814\u7a76\u8fc7\u7a0b\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u4f7f\u7528\u5171\u4eab\u5de5\u4f5c\u533a\u8bb0\u5f55\u5b50\u95ee\u9898\u53ca\u5176\u53d1\u73b0\uff0c\u786e\u4fdd\u7814\u7a76\u72b6\u6001\u5728\u4e0d\u540c\u6a21\u578b\u8c03\u7528\u4e2d\u4fdd\u6301\u4e00\u81f4\u3002</li>\n    <li>\u72ec\u7acb\u7684\u9a8c\u8bc1\u4ee3\u7406\u4f1a\u68c0\u67e5\u7b54\u6848\u4e0e\u8bc1\u636e\u7684\u7b26\u5408\u6027\uff0c\u63d0\u4f9b\u53cd\u9988\u4ee5\u6307\u5bfc\u540e\u7eed\u7814\u7a76\u3002</li>\n    <li>PANINI-DR \u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u4f18\u8d8a\uff0c\u7279\u522b\u662f\u5728\u96be\u9898\u4e0a\u8868\u73b0\u66f4\u4e3a\u7a81\u51fa\u3002</li>\n    <li>\u7cfb\u7edf\u7684\u7ed3\u6784\u5316\u89c4\u5212\u548c\u6301\u7eed\u72b6\u6001\u7ba1\u7406\u663e\u8457\u63d0\u5347\u4e86\u6027\u80fd\uff0c\u5e76\u4e14\u4f7f\u7528\u4fdd\u5b58\u7684\u8bc1\u636e\u8fdb\u884c\u9a8c\u8bc1\u4e5f\u589e\u5f3a\u4e86\u7b54\u6848\u7684\u53ef\u9760\u6027\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>PANINI-DR is a system designed to help researchers connect different steps in deep research by managing subquestions and their findings effectively.</li>\n    <li>It features a shared workspace that keeps track of subquestions, their dependencies, findings, and evidence, enabling better organization and verification.</li>\n    <li>A verification agent checks answers to subquestions against the evidence, providing feedback that helps guide further investigation.</li>\n    <li>PANINI-DR outperforms other research systems in accuracy and the ability to answer hard questions, achieving significant improvements in various benchmarks.</li>\n    <li>The system also demonstrates strong performance in retaining evidence, which enhances the reliability of its answers compared to other methods.</li>\n</ul>"}, "publishedAt": "2026-10-09T20:00:00.000Z", "title": "PANINI-DR: Controlled Deep Research through Generative Semantic Workspaces", "summary": "Deep research requires connecting multiple steps of search, reasoning, and computation, with intermediate findings guiding what to investigate next. As investigations grow, agents must maintain research state across model calls and check findings before errors propagate into subsequent work. We introduce PANINI-DR, a multi-agent harness that separates coordination of the overall investigation from the research and verification of individual subquestions. A shared workspace, built on the Generative Semantic Workspace representation, records subquestions, their dependencies, findings, and supporting evidence. Researchers investigate individual subquestions, while a separate verification agent checks proposed answers against those subquestions and their evidence. Verification feedback guides further investigation, and recorded findings inform subsequent assignments. We evaluate PANINI-DR on BrowseComp-Plus, FRAMES, and MoNaCo against seven state-of-the-art deep-research harnesses, all using a shared language-model backbone and frozen corpora. PANINI-DR achieves the strongest average performance across the three benchmarks. On BrowseComp-Plus, it achieves 73.3% accuracy, outperforming the next-best harness by 16.0 points. Its advantage is strongest on hard questions, where it answers nearly twice as many as the next-best harness. Ablations further show that structured planning and persistent state improve performance, as does checking each finding against its cited evidence before it is reused. Because a model can answer correctly from memory alone, we also analyze the evidence retained by each harness. PANINI-DR achieves the highest answer recoverability from saved evidence on all three benchmarks, while complementary claim-support audits show stronger evidence-backed answers. Accounting for this evidence changes how harnesses compare and further strengthens PANINI-DR's advantage.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.15208.png", "numComments": 1, "submittedBy": {"_id": "6686f852a03abfbb1b5ac5b6", "avatarUrl": "/avatars/8d4289a71da6b90064be6aa84dc5debc.svg", "fullname": "Mehmet Yigit Turali", "name": "yigitturali", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "isAuthorParticipating": false}, {"paper": {"id": "2609.38377", "authors": [{"_id": "6acc13220ee6ff34004fdc4b", "user": {"_id": "631d760344503b7227837242", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/631d760344503b7227837242/3b6JRusFX6GKJpsN9ZdeJ.png", "isPro": false, "fullname": "Max Ku", "user": "vinesmsuic", "type": "user", "name": "vinesmsuic"}, "name": "Max Ku", "status": "claimed_verified", "statusLastChangedAt": "2026-10-13T00:45:05.048Z", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc4c", "name": "Jiaojiao Fan", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc4d", "name": "Zekun Hao", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc4e", "name": "Francesco Ferroni", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc4f", "name": "Heng Wang", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc50", "name": "Wenhu Chen", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc51", "name": "Ming-Yu Liu", "hidden": false}, {"_id": "6acc13220ee6ff34004fdc52", "name": "Prithvijit Chattopadhyay", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/631d760344503b7227837242/SDhey8UG2rbJfvxeYTOl7.mp4"], "publishedAt": "2026-09-29T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "PhyProbe: Rethinking Physical Consistency Evaluation in Generated Videos", "submittedOnDailyBy": {"_id": "631d760344503b7227837242", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/631d760344503b7227837242/3b6JRusFX6GKJpsN9ZdeJ.png", "isPro": false, "fullname": "Max Ku", "user": "vinesmsuic", "type": "user", "name": "vinesmsuic"}, "summary": "Evaluating the physical consistency of generated videos remains a fundamental challenge. Existing approaches rely on off-the-shelf vision-language models, which can often be myopic to physical dynamics, or fine-tuned evaluators trained on human annotations, which overfit to dataset-specific cues and fail to generalize. A key challenge is that existing supervision sources provide either relative ordering or absolute scores, but not both reliably and consistently across varied settings. To this end, we introduce PhyProbe, an evaluator that extracts features from a frozen pretrained spatio-temporal encoder and maps them to a scalar physical consistency violation score via a lightweight scoring head. PhyProbe is trained through a unified objective combining pairwise ranking, regression on noisy scalar annotations, and anchor-based calibration over a curated set of heterogeneous supervision sources. Experiments show that PhyProbe outperforms prior methods on most pairwise benchmarks spanning real-generated and generated-generated pairs under varying correspondence, with the largest gains in no-correspondence and generated-generated settings where existing fine-tuned evaluators degrade sharply. PhyProbe achieves strong correlation with human judgments, with close agreement between rank-based and linear metrics, indicating that scores are both well ordered and anchored to a stable [0, 1] scale. Further, despite being trained on supervision indicative of physical consistency, without explicit general-preference labels, PhyProbe also performs competitively on human preference benchmarks: consistent with the observation that physics violations are entangled with broader quality degradations.", "upvotes": 6, "discussionId": "6acc13220ee6ff34004fdc53", "projectPage": "https://research.nvidia.com/labs/cosmos-lab/phyprobe/", "githubRepo": "https://github.com/vinesmsuic/PhyProbe", "githubRepoAddedBy": "user", "githubStars": 0, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "summary_zh": "<ul>\n    <li>\u8bc4\u4f30\u751f\u6210\u89c6\u9891\u7684\u7269\u7406\u4e00\u81f4\u6027\u662f\u4e00\u4e2a\u91cd\u8981\u7684\u6311\u6218\u3002</li>\n    <li>\u73b0\u6709\u65b9\u6cd5\u4f9d\u8d56\u4e8e\u73b0\u6210\u7684\u89c6\u89c9\u8bed\u8a00\u6a21\u578b\uff0c\u6216\u8005\u57fa\u4e8e\u4eba\u7c7b\u6ce8\u91ca\u7684\u5fae\u8c03\u8bc4\u4f30\u5668\uff0c\u8fd9\u4e9b\u65b9\u6cd5\u5b58\u5728\u5c40\u9650\u6027\u3002</li>\n    <li>PhyProbe\u662f\u4e00\u4e2a\u65b0\u7684\u8bc4\u4f30\u5668\uff0c\u5b83\u901a\u8fc7\u63d0\u53d6\u7279\u5f81\u548c\u6620\u5c04\u5230\u7269\u7406\u4e00\u81f4\u6027\u8bc4\u5206\u6765\u89e3\u51b3\u8fd9\u4e2a\u95ee\u9898\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cPhyProbe\u5728\u591a\u79cd\u5bf9\u6bd4\u6d4b\u8bd5\u4e2d\u8868\u73b0\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\uff0c\u7279\u522b\u662f\u5728\u65e0\u5bf9\u5e94\u548c\u751f\u6210\u751f\u6210\u5bf9\u7684\u8bbe\u7f6e\u4e2d\u3002</li>\n    <li>PhyProbe\u4e0e\u4eba\u7c7b\u5224\u65ad\u7684\u76f8\u5173\u6027\u5f3a\uff0c\u5f97\u5206\u65e2\u6709\u5e8f\u53c8\u7a33\u5b9a\uff0c\u4e14\u5728\u6ca1\u6709\u660e\u786e\u7684\u504f\u597d\u6807\u7b7e\u4e0b\u4e5f\u80fd\u5728\u504f\u597d\u57fa\u51c6\u4e0a\u8868\u73b0\u826f\u597d\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Evaluating the physical realism of generated videos is difficult due to limitations in current methods.</li>\n    <li>Existing models either lack understanding of physical dynamics or are too specialized, making them less effective in general situations.</li>\n    <li>PhyProbe is a new tool that evaluates video consistency by using a pre-trained model to score physical violations.</li>\n    <li>It combines different training methods to improve accuracy across various types of video comparisons.</li>\n    <li>PhyProbe shows better performance than previous methods and aligns well with human judgments on video quality.</li>\n</ul>"}, "publishedAt": "2026-09-28T20:00:00.000Z", "title": "PhyProbe: Rethinking Physical Consistency Evaluation in Generated Videos", "summary": "Evaluating the physical consistency of generated videos remains a fundamental challenge. Existing approaches rely on off-the-shelf vision-language models, which can often be myopic to physical dynamics, or fine-tuned evaluators trained on human annotations, which overfit to dataset-specific cues and fail to generalize. A key challenge is that existing supervision sources provide either relative ordering or absolute scores, but not both reliably and consistently across varied settings. To this end, we introduce PhyProbe, an evaluator that extracts features from a frozen pretrained spatio-temporal encoder and maps them to a scalar physical consistency violation score via a lightweight scoring head. PhyProbe is trained through a unified objective combining pairwise ranking, regression on noisy scalar annotations, and anchor-based calibration over a curated set of heterogeneous supervision sources. Experiments show that PhyProbe outperforms prior methods on most pairwise benchmarks spanning real-generated and generated-generated pairs under varying correspondence, with the largest gains in no-correspondence and generated-generated settings where existing fine-tuned evaluators degrade sharply. PhyProbe achieves strong correlation with human judgments, with close agreement between rank-based and linear metrics, indicating that scores are both well ordered and anchored to a stable [0, 1] scale. Further, despite being trained on supervision indicative of physical consistency, without explicit general-preference labels, PhyProbe also performs competitively on human preference benchmarks: consistent with the observation that physics violations are entangled with broader quality degradations.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/631d760344503b7227837242/SDhey8UG2rbJfvxeYTOl7.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.38377.png", "numComments": 1, "submittedBy": {"_id": "631d760344503b7227837242", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/631d760344503b7227837242/3b6JRusFX6GKJpsN9ZdeJ.png", "fullname": "Max Ku", "name": "vinesmsuic", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 19, "isUserFollowing": false}, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.38847", "authors": [{"_id": "6acef5acabe004a210f259e6", "name": "Maoqi Liu", "hidden": false}, {"_id": "6acef5acabe004a210f259e7", "name": "Junwei He", "hidden": false}, {"_id": "6acef5acabe004a210f259e8", "name": "Bowen Zhang", "hidden": false}, {"_id": "6acef5acabe004a210f259e9", "name": "Feiran Li", "hidden": false}, {"_id": "6acef5acabe004a210f259ea", "name": "Wentao Ma", "hidden": false}, {"_id": "6acef5acabe004a210f259eb", "name": "Rongyi Lin", "hidden": false}, {"_id": "6acef5acabe004a210f259ec", "name": "Shuhan Zhong", "hidden": false}, {"_id": "6acef5acabe004a210f259ed", "name": "Quan Fang", "hidden": false}], "publishedAt": "2026-09-30T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "Scoring Higher, Answering Worse: Mitigating Reward Hacking in Rubric-Based RL via Protocol-Level Rubrics", "submittedOnDailyBy": {"_id": "636d2965a756aeb5c4af05e5", "avatarUrl": "/avatars/439650942cb1298aaec98460753dbb9d.svg", "isPro": false, "fullname": "quinn", "user": "jwhe", "type": "user", "name": "jwhe"}, "summary": "Rubric-based reinforcement learning (Rubric-RL) trains language models where no verifier exists. A judge checks each criterion of a rubric, and the verdicts are aggregated into a reward, most often by a weighted sum. We show that this additive aggregation is the weak point. Under a sum, criteria compensate for one another: a policy that misses the one decision that matters can buy the points back with advice nobody asked for. On clinical consultation, such a policy scores higher and answers worse. Rubric coverage rises while appropriateness on held-out physician criteria falls below the untrained model. The medical criteria are not to blame. Grouped so that they must hold together, the same criteria, unchanged to the word, recover a third of the loss; shorter answers recover almost none. We therefore propose Protocol-level Rubrics (ProRubric), which keeps what the criteria ask for and changes how they are aggregated. It groups a checklist into a few protocol-level dimensions. A dimension counts only when all of its criteria hold and its failure clause does not fire. The grouping is done once, offline, and leaves the optimizer unchanged. ProRubric raises appropriateness by 10.8 points without losing coverage and has the best seven-benchmark average at both scales. Reward validity is set not only by what a rubric verifies, but by how it aggregates. Code is available at https://github.com/Estrellajer/ProRubric", "upvotes": 5, "discussionId": "6acef5adabe004a210f259ee", "organization": {"_id": "653b817d32c97d0655575872", "name": "ByteDance", "fullname": "ByteDance", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6535c9e88bde2fae19b6fb25/0clr54wj5Ly-RkYU9OXPp.png"}, "summary_zh": "<ul>\n    <li>\u57fa\u4e8e\u8bc4\u5206\u6807\u51c6\u7684\u5f3a\u5316\u5b66\u4e60\uff08Rubric-RL\uff09\u7528\u4e8e\u8bad\u7ec3\u6ca1\u6709\u9a8c\u8bc1\u8005\u7684\u8bed\u8a00\u6a21\u578b\u3002</li>\n    <li>\u8bc4\u5206\u6807\u51c6\u7684\u5404\u4e2a\u6807\u51c6\u901a\u8fc7\u52a0\u6743\u6c42\u548c\u7684\u65b9\u5f0f\u6c47\u603b\u6210\u5956\u52b1\uff0c\u4f46\u8fd9\u79cd\u65b9\u6cd5\u5b58\u5728\u7f3a\u9677\u3002</li>\n    <li>\u5728\u4e34\u5e8a\u54a8\u8be2\u4e2d\uff0c\u67d0\u4e9b\u7b56\u7565\u5f97\u5206\u8f83\u9ad8\uff0c\u4f46\u56de\u7b54\u8d28\u91cf\u5374\u8f83\u5dee\u3002</li>\n    <li>\u63d0\u51fa\u4e86\u201c\u534f\u8bae\u7ea7\u8bc4\u5206\u6807\u51c6\u201d\uff08ProRubric\uff09\uff0c\u6539\u5584\u4e86\u8bc4\u5206\u6807\u51c6\u7684\u805a\u5408\u65b9\u5f0f\uff0c\u63d0\u9ad8\u4e86\u56de\u7b54\u7684\u9002\u5f53\u6027\u3002</li>\n    <li>ProRubric\u63d0\u9ad8\u4e86\u9002\u5f53\u602710.8\u5206\uff0c\u540c\u65f6\u4fdd\u6301\u4e86\u8986\u76d6\u7387\uff0c\u4e14\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u6700\u4f73\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Rubric-based reinforcement learning (Rubric-RL) uses judges to evaluate language models based on a set of criteria.</li>\n    <li>The way these criteria are combined into a score can lead to issues, allowing models to score well without providing valuable answers.</li>\n    <li>In clinical consultations, models can perform poorly on key decisions while still achieving high scores due to this scoring method.</li>\n    <li>To improve this, a new method called Protocol-level Rubrics (ProRubric) is proposed, which changes how criteria are grouped and scored.</li>\n    <li>ProRubric improves the quality of responses without losing coverage and achieves better overall performance across benchmarks.</li>\n</ul>"}, "publishedAt": "2026-09-29T20:00:00.000Z", "title": "Scoring Higher, Answering Worse: Mitigating Reward Hacking in Rubric-Based RL via Protocol-Level Rubrics", "summary": "Rubric-based reinforcement learning (Rubric-RL) trains language models where no verifier exists. A judge checks each criterion of a rubric, and the verdicts are aggregated into a reward, most often by a weighted sum. We show that this additive aggregation is the weak point. Under a sum, criteria compensate for one another: a policy that misses the one decision that matters can buy the points back with advice nobody asked for. On clinical consultation, such a policy scores higher and answers worse. Rubric coverage rises while appropriateness on held-out physician criteria falls below the untrained model. The medical criteria are not to blame. Grouped so that they must hold together, the same criteria, unchanged to the word, recover a third of the loss; shorter answers recover almost none. We therefore propose Protocol-level Rubrics (ProRubric), which keeps what the criteria ask for and changes how they are aggregated. It groups a checklist into a few protocol-level dimensions. A dimension counts only when all of its criteria hold and its failure clause does not fire. The grouping is done once, offline, and leaves the optimizer unchanged. ProRubric raises appropriateness by 10.8 points without losing coverage and has the best seven-benchmark average at both scales. Reward validity is set not only by what a rubric verifies, but by how it aggregates. Code is available at https://github.com/Estrellajer/ProRubric", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.38847.png", "numComments": 1, "submittedBy": {"_id": "636d2965a756aeb5c4af05e5", "avatarUrl": "/avatars/439650942cb1298aaec98460753dbb9d.svg", "fullname": "quinn", "name": "jwhe", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "653b817d32c97d0655575872", "name": "ByteDance", "fullname": "ByteDance", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6535c9e88bde2fae19b6fb25/0clr54wj5Ly-RkYU9OXPp.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.16794", "authors": [{"_id": "6acef276abe004a210f2599c", "name": "Futing Wang", "hidden": false}, {"_id": "6acef276abe004a210f2599d", "name": "Chenxi Li", "hidden": false}, {"_id": "6acef276abe004a210f2599e", "name": "Jianhao Yan", "hidden": false}, {"_id": "6acef276abe004a210f2599f", "name": "Yun Luo", "hidden": false}, {"_id": "6acef276abe004a210f259a0", "name": "Zhi Wang", "hidden": false}, {"_id": "6acef276abe004a210f259a1", "name": "Yizhuo Li", "hidden": false}, {"_id": "6acef276abe004a210f259a2", "name": "Runzhe Zhan", "hidden": false}, {"_id": "6acef276abe004a210f259a3", "name": "Yu Cheng", "hidden": false}, {"_id": "6acef276abe004a210f259a4", "name": "Tao Lin", "hidden": false}], "publishedAt": "2026-10-12T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "TPPO: Tracking-Value PPO For Language Model Reasoning", "submittedOnDailyBy": {"_id": "6418228b83957c4eaaad4d01", "avatarUrl": "/avatars/b6af01d09bba5d5ba7bf4a62914ca468.svg", "isPro": false, "fullname": "wang", "user": "astrid01052", "type": "user", "name": "astrid01052"}, "summary": "Proximal Policy Optimization (PPO) is widely used in reinforcement learning with verifiable rewards for language-model reasoning. While value evolution along trajectory characterizes relative token-level credit, yet standard critics often fail to track it under sparse terminal rewards. To model this evolution, we analyze the relation between successive prefix values and show that they admit a Bayesian decomposition with additive updates in log-odds space. We use this additive structure to construct Tracking-Value PPO (\\method), a cumulative value parameterization that sums position-wise scalar outputs into value logits. These outputs are learned through terminal-outcome supervision on the reconstructed values. \\method improves aggregate mathematical reasoning scores over PPO by 7.0 and 8.4 points on Qwen3-4B-Base and Qwen3-8B-Base, respectively, while improving out-of-distribution generalization. Gains extend to Qwen3-4B, Qwen2.5-Math-1.5B, Qwen3.5-9B and to countdown, and scientific coding tasks. Further analysis shows more accurate tracking of value evolution and more reliable advantage estimates. Our code is publicly available in https://github.com/LINs-lab/TPPO.", "upvotes": 4, "discussionId": "6acef276abe004a210f259a5", "githubRepo": "https://github.com/LINs-lab/TPPO", "githubRepoAddedBy": "user", "summary_zh": "<ul>\n    <li>Proximal Policy Optimization (PPO) \u662f\u4e00\u79cd\u5e38\u7528\u7684\u5f3a\u5316\u5b66\u4e60\u65b9\u6cd5\uff0c\u9002\u7528\u4e8e\u8bed\u8a00\u6a21\u578b\u63a8\u7406\u3002</li>\n    <li>\u6807\u51c6\u7684\u8bc4\u4f30\u65b9\u6cd5\u5728\u7a00\u758f\u7ec8\u7aef\u5956\u52b1\u4e0b\uff0c\u65e0\u6cd5\u6709\u6548\u8ffd\u8e2a\u76f8\u5bf9\u7684\u4ee4\u724c\u7ea7\u522b\u4fe1\u7528\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u7b97\u6cd5\uff0c\u79f0\u4e3a Tracking-Value PPO\uff0c\u901a\u8fc7\u5728\u65e5\u5fd7\u51e0\u7387\u7a7a\u95f4\u4e2d\u8fdb\u884c\u7d2f\u79ef\u503c\u53c2\u6570\u5316\u6765\u6539\u8fdb\u4ef7\u503c\u8ffd\u8e2a\u3002</li>\n    <li>\u8fd9\u79cd\u65b0\u65b9\u6cd5\u5728\u6570\u5b66\u63a8\u7406\u5f97\u5206\u4e0a\u6bd4 PPO \u63d0\u9ad8\u4e86 7.0 \u548c 8.4 \u5206\uff0c\u5e76\u4e14\u589e\u5f3a\u4e86\u5bf9\u672a\u89c1\u6570\u636e\u7684\u6cdb\u5316\u80fd\u529b\u3002</li>\n    <li>\u6211\u4eec\u7684\u4ee3\u7801\u5df2\u516c\u5f00\uff0c\u63d0\u4f9b\u5728 https://github.com/LINs-lab/TPPO\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Proximal Policy Optimization (PPO) is a common method in reinforcement learning, especially for language-model reasoning.</li>\n    <li>Standard PPO struggles with tracking value evolution when rewards are sparse, which is important for understanding token-level credit.</li>\n    <li>The new method, Tracking-Value PPO, improves how value is tracked by using a cumulative value approach with additive updates.</li>\n    <li>Tracking-Value PPO shows significant improvements in reasoning scores and generalization across various models and tasks.</li>\n    <li>The implementation of this method is publicly available on GitHub for further use and exploration.</li>\n</ul>"}, "publishedAt": "2026-10-11T20:00:00.000Z", "title": "TPPO: Tracking-Value PPO For Language Model Reasoning", "summary": "Proximal Policy Optimization (PPO) is widely used in reinforcement learning with verifiable rewards for language-model reasoning. While value evolution along trajectory characterizes relative token-level credit, yet standard critics often fail to track it under sparse terminal rewards. To model this evolution, we analyze the relation between successive prefix values and show that they admit a Bayesian decomposition with additive updates in log-odds space. We use this additive structure to construct Tracking-Value PPO (\\method), a cumulative value parameterization that sums position-wise scalar outputs into value logits. These outputs are learned through terminal-outcome supervision on the reconstructed values. \\method improves aggregate mathematical reasoning scores over PPO by 7.0 and 8.4 points on Qwen3-4B-Base and Qwen3-8B-Base, respectively, while improving out-of-distribution generalization. Gains extend to Qwen3-4B, Qwen2.5-Math-1.5B, Qwen3.5-9B and to countdown, and scientific coding tasks. Further analysis shows more accurate tracking of value evolution and more reliable advantage estimates. Our code is publicly available in https://github.com/LINs-lab/TPPO.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.16794.png", "numComments": 1, "submittedBy": {"_id": "6418228b83957c4eaaad4d01", "avatarUrl": "/avatars/b6af01d09bba5d5ba7bf4a62914ca468.svg", "fullname": "wang", "name": "astrid01052", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "isAuthorParticipating": false}],
    "week": [{"paper": {"id": "2610.12126", "authors": [{"_id": "6ac84bfc4364a3d18a5cc6c5", "name": "Jinkai Zhang", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c6", "name": "Jingyi Xu", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c7", "name": "Yuanhong Yu", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c8", "name": "Jiarui Guo", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6c9", "name": "Ruizhen Hu", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6ca", "name": "Hujun Bao", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6cb", "name": "Xiaowei Zhou", "hidden": false}, {"_id": "6ac84bfc4364a3d18a5cc6cc", "name": "Sida Peng", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/LF5AsDNLDR1hcNX1oHoET.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/pUg84zM-QSVTHiLoMYbTI.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/6tod5HobhOHHMT7F6J8cK.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/4OTs3Bes8yxzVycKUH-qw.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/e5Zfn-bMFcxQ_ZQgftb-S.mp4"], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "SuperNav: An Agentic Navigation System for Any Task in Any Scene", "submittedOnDailyBy": {"_id": "653b560b025e5d01725dd1b0", "avatarUrl": "/avatars/280b612c817caccc8086e2713398a705.svg", "isPro": false, "fullname": "yyh", "user": "yyh929", "type": "user", "name": "yyh929"}, "summary": "General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical interaction, and task-progress and context management. A unified visual-point interface connects decision-making to motion by allowing the model to specify destinations directly in images and revise its decisions from execution feedback. Together, these components support sustained navigation across different task requirements and environments. SuperNav outperforms four evaluated baselines on instance-level, multi-object, and demand-driven tasks. Category-level evaluation on HM3D and deployment on a real quadruped robot further demonstrate its applicability across environments. Project Page: https://zju3dv.github.io/SuperNav/", "upvotes": 46, "discussionId": "6ac84bfc4364a3d18a5cc6cd", "projectPage": "https://zju3dv.github.io/SuperNav/", "githubRepo": "https://github.com/zju3dv/SuperNav", "githubRepoAddedBy": "user", "githubStars": 10, "organization": {"_id": "642673e52a423daad52d5b86", "name": "zju3dv", "fullname": "zju3dv", "avatar": "https://www.gravatar.com/avatar/38d28859223ed13a997edb0e9911614a?d=retro&size=100"}, "summary_zh": "<ul>\n    <li>\u901a\u7528\u670d\u52a1\u673a\u5668\u4eba\u9700\u8981\u80fd\u591f\u5728\u4e0d\u719f\u6089\u7684\u73af\u5883\u4e2d\u5904\u7406\u591a\u6837\u5316\u4eba\u7c7b\u8bf7\u6c42\u7684\u5bfc\u822a\u7cfb\u7edf\u3002</li>\n    <li>\u73b0\u6709\u65b9\u6cd5\u901a\u8fc7\u5fae\u8c03\u591a\u6a21\u6001\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08MLLM\uff09\u6765\u9884\u6d4b\u5bfc\u822a\u52a8\u4f5c\uff0c\u4f46\u53ef\u80fd\u9650\u5236\u5728\u65b0\u8bf7\u6c42\u548c\u73af\u5883\u4e2d\u7684\u6cdb\u5316\u80fd\u529b\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51faSuperNav\uff0c\u8ba9MLLM\u4e13\u6ce8\u4e8e\u7406\u89e3\u8bf7\u6c42\u548c\u573a\u666f\uff0c\u540c\u65f6\u5c06\u8fd0\u52a8\u6267\u884c\u59d4\u6258\u7ed9\u5bfc\u822a\u5de5\u5177\u3002</li>\n    <li>SuperNav\u4f7f\u7528\u9884\u8bad\u7ec3\u7684MLLM\u548c\u4e13\u95e8\u7684\u4ee3\u7406\u5de5\u5177\uff0c\u652f\u6301\u5bfc\u822a\u51b3\u7b56\u548c\u4efb\u52a1\u7ba1\u7406\u3002</li>\n    <li>SuperNav\u5728\u591a\u9879\u4efb\u52a1\u8bc4\u4f30\u4e2d\u8868\u73b0\u4f18\u4e8e\u56db\u4e2a\u57fa\u7ebf\uff0c\u5e76\u5728\u771f\u5b9e\u56db\u8db3\u673a\u5668\u4eba\u4e0a\u90e8\u7f72\uff0c\u663e\u793a\u5176\u5e7f\u6cdb\u9002\u7528\u6027\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>General-purpose service robots need navigation systems that can adapt to various human requests in new environments.</li>\n    <li>Current methods often rely on training data, which can limit how well robots generalize to new situations.</li>\n    <li>SuperNav allows a large language model to focus on understanding requests and scenes without needing specific navigation training.</li>\n    <li>It uses a special harness that includes tools for navigation, physical interaction, and managing tasks.</li>\n    <li>SuperNav shows better performance than other methods in different tasks and works well on real robots in various environments.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "SuperNav: An Agentic Navigation System for Any Task in Any Scene", "summary": "General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical interaction, and task-progress and context management. A unified visual-point interface connects decision-making to motion by allowing the model to specify destinations directly in images and revise its decisions from execution feedback. Together, these components support sustained navigation across different task requirements and environments. SuperNav outperforms four evaluated baselines on instance-level, multi-object, and demand-driven tasks. Category-level evaluation on HM3D and deployment on a real quadruped robot further demonstrate its applicability across environments. Project Page: https://zju3dv.github.io/SuperNav/", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/LF5AsDNLDR1hcNX1oHoET.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/pUg84zM-QSVTHiLoMYbTI.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/6tod5HobhOHHMT7F6J8cK.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/4OTs3Bes8yxzVycKUH-qw.mp4", "https://cdn-uploads.huggingface.co/production/uploads/653b560b025e5d01725dd1b0/e5Zfn-bMFcxQ_ZQgftb-S.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12126.png", "numComments": 1, "submittedBy": {"_id": "653b560b025e5d01725dd1b0", "avatarUrl": "/avatars/280b612c817caccc8086e2713398a705.svg", "fullname": "yyh", "name": "yyh929", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 5, "isUserFollowing": false}, "organization": {"_id": "642673e52a423daad52d5b86", "name": "zju3dv", "fullname": "zju3dv", "avatar": "https://www.gravatar.com/avatar/38d28859223ed13a997edb0e9911614a?d=retro&size=100"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12242", "authors": [{"_id": "6ac8556c4364a3d18a5cc773", "name": "Tianyu Fu", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc774", "name": "Tengxuan Liu", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc775", "name": "Ruoxi Wang", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc776", "name": "Yixin Dong", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc777", "name": "Yi Ge", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc778", "name": "Yichen You", "hidden": false}, {"_id": "6ac8556c4364a3d18a5cc779", "name": "Yu Wang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6445fd9ba56444c355dcbcba/0OrTOp3ievhuQL9HFSKmJ.png"], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "TokenRouter: Efficient Serving System for Token-Level LLM Routing", "submittedOnDailyBy": {"_id": "6445fd9ba56444c355dcbcba", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6445fd9ba56444c355dcbcba/NCyRCD-MK-yA0_qY6I2y0.png", "isPro": false, "fullname": "Tianyu Fu", "user": "fuvty", "type": "user", "name": "fuvty"}, "summary": "Large language model (LLM) routing distributes inference work across different models, advancing the cost-quality Pareto frontier of LLM serving. While coarse-grained routing at the session or query level has been widely adopted in production systems, recent algorithmic work shows that fine-grained token-level routing can yield substantial efficiency and quality gains. However, efficiently serving token-level routed inference poses significant challenges to existing systems. Built on single-LLM assumptions, current systems suffer from severe step desynchronization and frequent batch admission delays under token-level routing, and they also impose high implementation complexity on developers. To address these challenges, we design TokenRouter, an efficient and developer-friendly serving system for token-level routed LLM inference. TokenRouter follows the principle of request-centric programming, model-centric execution: developers describe routing logic from the perspective of a single request, while the runtime launches a subserver for each LLM and dispatches requests asynchronously. Each subserver employs a delayed-batching scheduler, whose optimal hyperparameters are derived from a mathematical throughput model of the system. Across diverse routing algorithms, workloads, and model pairs, TokenRouter achieves 2.01-64.15x higher decoding throughput than existing systems, substantially advancing the serving efficiency of token-level LLM routing. Our code is available at https://github.com/thu-nics/TokenRouter.", "upvotes": 38, "discussionId": "6ac8556c4364a3d18a5cc77a", "projectPage": "https://fuvty.github.io/thinking_yard_project_page/projects/tokenrouter/", "githubRepo": "https://github.com/thu-nics/TokenRouter", "githubRepoAddedBy": "user", "githubStars": 4, "organization": {"_id": "64b74b5fb727f8771ab887f9", "name": "nics-efc", "fullname": "Tsinghua-NICS-EFC", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/641031b1a78453b8d96b8420/vmgxct2WsyHcKT2x2NAYT.jpeg"}, "summary_zh": "<ul>\n    <li>\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u8def\u7531\u53ef\u4ee5\u63d0\u9ad8\u6a21\u578b\u7684\u6548\u7387\u548c\u8d28\u91cf\u3002</li>\n    <li>\u73b0\u6709\u7cfb\u7edf\u5728\u8fdb\u884c\u7ec6\u7c92\u5ea6\u7684\u4ee4\u724c\u7ea7\u8def\u7531\u65f6\u9762\u4e34\u8bb8\u591a\u6311\u6218\uff0c\u5982\u6b65\u8c03\u4e0d\u540c\u6b65\u548c\u6279\u5904\u7406\u5ef6\u8fdf\u3002</li>\n    <li>TokenRouter\u662f\u4e00\u4e2a\u9ad8\u6548\u4e14\u6613\u4e8e\u5f00\u53d1\u8005\u4f7f\u7528\u7684\u7cfb\u7edf\uff0c\u4e13\u4e3a\u4ee4\u724c\u7ea7\u8def\u7531\u7684LLM\u63a8\u7406\u8bbe\u8ba1\u3002</li>\n    <li>TokenRouter\u91c7\u7528\u8bf7\u6c42\u4e2d\u5fc3\u7f16\u7a0b\u548c\u6a21\u578b\u4e2d\u5fc3\u6267\u884c\u7684\u539f\u5219\uff0c\u80fd\u591f\u66f4\u597d\u5730\u5904\u7406\u8bf7\u6c42\u3002</li>\n    <li>\u4e0e\u73b0\u6709\u7cfb\u7edf\u76f8\u6bd4\uff0cTokenRouter\u7684\u89e3\u7801\u541e\u5410\u91cf\u63d0\u9ad8\u4e862.01\u523064.15\u500d\uff0c\u663e\u8457\u63d0\u5347\u4e86\u670d\u52a1\u6548\u7387\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>TokenRouter improves how large language models (LLMs) handle requests by using token-level routing, which is more efficient than the usual session or query-level routing.</li>\n    <li>Current systems face problems with timing and delays when using token-level routing, making it hard for developers to implement.</li>\n    <li>TokenRouter allows developers to define routing rules easily and runs requests in a way that makes the system work faster.</li>\n    <li>It uses a special scheduling method that optimizes performance based on a mathematical model, leading to significant increases in processing speed.</li>\n    <li>TokenRouter can process requests 2.01 to 64.15 times faster than existing systems, making it a big improvement for serving token-level LLMs.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "TokenRouter: Efficient Serving System for Token-Level LLM Routing", "summary": "Large language model (LLM) routing distributes inference work across different models, advancing the cost-quality Pareto frontier of LLM serving. While coarse-grained routing at the session or query level has been widely adopted in production systems, recent algorithmic work shows that fine-grained token-level routing can yield substantial efficiency and quality gains. However, efficiently serving token-level routed inference poses significant challenges to existing systems. Built on single-LLM assumptions, current systems suffer from severe step desynchronization and frequent batch admission delays under token-level routing, and they also impose high implementation complexity on developers. To address these challenges, we design TokenRouter, an efficient and developer-friendly serving system for token-level routed LLM inference. TokenRouter follows the principle of request-centric programming, model-centric execution: developers describe routing logic from the perspective of a single request, while the runtime launches a subserver for each LLM and dispatches requests asynchronously. Each subserver employs a delayed-batching scheduler, whose optimal hyperparameters are derived from a mathematical throughput model of the system. Across diverse routing algorithms, workloads, and model pairs, TokenRouter achieves 2.01-64.15x higher decoding throughput than existing systems, substantially advancing the serving efficiency of token-level LLM routing. Our code is available at https://github.com/thu-nics/TokenRouter.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6445fd9ba56444c355dcbcba/0OrTOp3ievhuQL9HFSKmJ.png"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12242.png", "numComments": 1, "submittedBy": {"_id": "6445fd9ba56444c355dcbcba", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6445fd9ba56444c355dcbcba/NCyRCD-MK-yA0_qY6I2y0.png", "fullname": "Tianyu Fu", "name": "fuvty", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 18, "isUserFollowing": false}, "organization": {"_id": "64b74b5fb727f8771ab887f9", "name": "nics-efc", "fullname": "Tsinghua-NICS-EFC", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/641031b1a78453b8d96b8420/vmgxct2WsyHcKT2x2NAYT.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.08215", "authors": [{"_id": "6ac855944364a3d18a5cc77d", "name": "Yibo Li", "hidden": false}, {"_id": "6ac855944364a3d18a5cc77e", "name": "Jinhang Qiu", "hidden": false}, {"_id": "6ac855944364a3d18a5cc77f", "name": "Zhi Zheng", "hidden": false}, {"_id": "6ac855944364a3d18a5cc780", "name": "Qianyun Guo", "hidden": false}, {"_id": "6ac855944364a3d18a5cc781", "name": "Jiaying Wu", "hidden": false}, {"_id": "6ac855944364a3d18a5cc782", "name": "Shuo Ji", "hidden": false}, {"_id": "6ac855944364a3d18a5cc783", "name": "Bryan Hooi", "hidden": false}], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "Learn2Play Bench: How Well Do LLM Agents Learn from Experience in Unfamiliar Environments?", "submittedOnDailyBy": {"_id": "67a1d21e33e92b4a1183f3bb", "avatarUrl": "/avatars/43f9dd3fcb7d58ddc69562fd1fc12957.svg", "isPro": false, "fullname": "Zhi Zheng", "user": "zz1358m", "type": "user", "name": "zz1358m"}, "summary": "Learning from experience is essential for LLM agents to adapt to unfamiliar and dynmaic environments. Evaluating this ability is therefore important for understanding how effectively agents acquire and use new knowledge. Existing benchmarks have sought to evaluate this ability, but they primarily evaluate tasks whose rules are provided in the instructions or already familiar to pretrained models, making it difficult to distinguish learning from interactions from reasoning with existing knowledge. To address this, we introduce Learn2Play Bench, a benchmark of newly designed text-based games, whose rules are novel or counterintuitive, requiring agents to acquire knowledge through interaction rather than rely solely on pretrained knowledge. These games provide reproducible feedback and automatic scoring, enabling controlled evaluation of learning across repeated attempts. We also vary game instances to test whether agents can apply what they have learned to new situations. Therefore, we evaluate how backbone models, self-evolving methods, and agent harnesses affect agents' learning ability, revealing three findings: (1) Experience retention: Retaining complete records of actions and feedback can support more effective learning than summarizing these experiences into rules or strategies. (2) Human agent gap: Top-performing human players achieve higher peak scores than the evaluated agents. Human explore more varied strategies, and repeat actions less. (3) Harness matters: With the backbone fixed, changing the harness can improve performance while reducing estimated inference cost. Together, these findings provide insights into how LLM agents learn from experience and suggest directions for future work to improve their learning ability. Project website: https://liushiliushi.github.io/learn2play-bench-website/", "upvotes": 32, "discussionId": "6ac855944364a3d18a5cc784", "projectPage": "https://liushiliushi.github.io/learn2play-bench-website/", "githubRepo": "https://github.com/liushiliushi/Learn2Play-Bench", "githubRepoAddedBy": "user", "githubStars": 0, "organization": {"_id": "6508ab2b349930913196378b", "name": "NationalUniversityofSingapore", "fullname": "National University of Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/630ca0817dacb93b33506ce7/ZYUmpSMsa5Whihw3me2Bw.png"}, "summary_zh": "<ul>\n    <li>\u5b66\u4e60\u7ecf\u9a8c\u5bf9\u5927\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u4ee3\u7406\u5728\u4e0d\u719f\u6089\u548c\u52a8\u6001\u73af\u5883\u4e2d\u7684\u9002\u5e94\u80fd\u529b\u81f3\u5173\u91cd\u8981\u3002</li>\n    <li>\u73b0\u6709\u7684\u8bc4\u4f30\u6807\u51c6\u4e3b\u8981\u5173\u6ce8\u5df2\u77e5\u89c4\u5219\u7684\u4efb\u52a1\uff0c\u96be\u4ee5\u533a\u5206\u5b66\u4e60\u4e0e\u63a8\u7406\u3002</li>\n    <li>\u6211\u4eec\u63a8\u51fa\u4e86Learn2Play Bench\uff0c\u4e00\u4e2a\u5305\u542b\u65b0\u8bbe\u8ba1\u6587\u672c\u6e38\u620f\u7684\u57fa\u51c6\uff0c\u8981\u6c42\u4ee3\u7406\u901a\u8fc7\u4e92\u52a8\u83b7\u53d6\u77e5\u8bc6\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\uff0c\u5b8c\u6574\u8bb0\u5f55\u7ecf\u9a8c\u6bd4\u603b\u7ed3\u6210\u89c4\u5219\u66f4\u80fd\u652f\u6301\u6709\u6548\u5b66\u4e60\uff1b\u4eba\u7c7b\u73a9\u5bb6\u8868\u73b0\u66f4\u4f18\u79c0\uff0c\u63a2\u7d22\u7b56\u7565\u66f4\u591a\uff1b\u66f4\u6362\u4ee3\u7406\u7684\u914d\u7f6e\u53ef\u63d0\u9ad8\u6027\u80fd\u5e76\u964d\u4f4e\u63a8\u7406\u6210\u672c\u3002</li>\n    <li>\u8fd9\u4e9b\u53d1\u73b0\u4e3a\u7406\u89e3LLM\u4ee3\u7406\u5982\u4f55\u4ece\u7ecf\u9a8c\u4e2d\u5b66\u4e60\u63d0\u4f9b\u4e86\u65b0\u89c6\u89d2\uff0c\u5e76\u6307\u660e\u4e86\u672a\u6765\u6539\u8fdb\u5b66\u4e60\u80fd\u529b\u7684\u65b9\u5411\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Learning from experience is crucial for LLM agents to adapt to new environments.</li>\n    <li>The Learn2Play Bench is a new set of text-based games designed to test agents' learning through interaction.</li>\n    <li>The benchmark allows for controlled evaluation and gives feedback to help measure how well agents learn.</li>\n    <li>Key findings include: (1) Keeping detailed records helps learning more than summarizing experiences; (2) Human players generally outperform agents by using more varied strategies; (3) Changing the tool (harness) can enhance performance while being cost-effective.</li>\n    <li>The study provides insights into improving how LLM agents learn from their experiences.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "Learn2Play Bench: How Well Do LLM Agents Learn from Experience in Unfamiliar Environments?", "summary": "Learning from experience is essential for LLM agents to adapt to unfamiliar and dynmaic environments. Evaluating this ability is therefore important for understanding how effectively agents acquire and use new knowledge. Existing benchmarks have sought to evaluate this ability, but they primarily evaluate tasks whose rules are provided in the instructions or already familiar to pretrained models, making it difficult to distinguish learning from interactions from reasoning with existing knowledge. To address this, we introduce Learn2Play Bench, a benchmark of newly designed text-based games, whose rules are novel or counterintuitive, requiring agents to acquire knowledge through interaction rather than rely solely on pretrained knowledge. These games provide reproducible feedback and automatic scoring, enabling controlled evaluation of learning across repeated attempts. We also vary game instances to test whether agents can apply what they have learned to new situations. Therefore, we evaluate how backbone models, self-evolving methods, and agent harnesses affect agents' learning ability, revealing three findings: (1) Experience retention: Retaining complete records of actions and feedback can support more effective learning than summarizing these experiences into rules or strategies. (2) Human agent gap: Top-performing human players achieve higher peak scores than the evaluated agents. Human explore more varied strategies, and repeat actions less. (3) Harness matters: With the backbone fixed, changing the harness can improve performance while reducing estimated inference cost. Together, these findings provide insights into how LLM agents learn from experience and suggest directions for future work to improve their learning ability. Project website: https://liushiliushi.github.io/learn2play-bench-website/", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.08215.png", "numComments": 1, "submittedBy": {"_id": "67a1d21e33e92b4a1183f3bb", "avatarUrl": "/avatars/43f9dd3fcb7d58ddc69562fd1fc12957.svg", "fullname": "Zhi Zheng", "name": "zz1358m", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 7, "isUserFollowing": false}, "organization": {"_id": "6508ab2b349930913196378b", "name": "NationalUniversityofSingapore", "fullname": "National University of Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/630ca0817dacb93b33506ce7/ZYUmpSMsa5Whihw3me2Bw.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13166", "authors": [{"_id": "6acc50ce0ee6ff34004fde8d", "user": {"_id": "6901b520f8f20b9d7015a38d", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6901b520f8f20b9d7015a38d/HIlNYBWGOI_XhI9aUJoAl.jpeg", "isPro": false, "fullname": "Shun Zou", "user": "shunzou05", "type": "user", "name": "shunzou05"}, "name": "Shun Zou", "status": "claimed_verified", "statusLastChangedAt": "2026-10-12T08:45:06.115Z", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde8e", "name": "Ziyu Ma", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde8f", "name": "Yi Zou", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde90", "name": "Yong Wang", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde91", "name": "Lin Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde92", "name": "Zehui Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde93", "name": "Guanhua Chen", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde94", "name": "Xiangxiang Chu", "hidden": false}, {"_id": "6acc50ce0ee6ff34004fde95", "name": "Feng Zhao", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Scaling Agentic Data for Long-Horizon Terminal Intelligence", "submittedOnDailyBy": {"_id": "64d1dc5273174cecdffc97d3", "avatarUrl": "/avatars/6564e6b68fee9673f75b6366adf39a3b.svg", "isPro": false, "fullname": "Wang Yong", "user": "seashell11", "type": "user", "name": "seashell11"}, "summary": "Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon terminal agents. Starting from real-world professional work, it uses independent execution to identify key work omitted during construction and uses the resulting evidence to guide environment reconstruction. To extend these patterns across stages, it progressively expands tasks under the same goal, introducing new requirements that build on prior results and call for further exploration and improvement. Using this engine, we construct 1.5K task environments and perform supervised fine-tuning of Qwen3.5-27B on the resulting dataset to obtain TerminalHorizon-27B. We achieve substantial performance gains on all 12 benchmarks spanning coding-agent tasks, agentic tasks in real-world production settings, and general reasoning. Multiple RSI case studies, each with a 12-hour research budget, further demonstrate the model's ability to continue experimenting beyond an initial solution, improve its methods based on feedback, and retain effective improvements in its final deliverables.", "upvotes": 31, "discussionId": "6acc50ce0ee6ff34004fde96", "projectPage": "https://zs1314.github.io/TerminalHorizon", "organization": {"_id": "68be41370a3fcebdcad6516a", "name": "alibabagroup", "fullname": "alibaba", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68be3ab7e52df040b2cf80dc/li4G29u_EGswyTN1Sm_Kq.png"}, "summary_zh": "<ul>\n    <li>\u7ec8\u7aef\u667a\u80fd\u4f53\u6b63\u5728\u4ece\u5c40\u90e8\u64cd\u4f5c\u6269\u5c55\u5230\u5b8c\u6210\u73b0\u5b9e\u4e16\u754c\u7684\u4e13\u4e1a\u4efb\u52a1\u3002</li>\n    <li>\u77ed\u8def\u5f84\u5c55\u793a\u4e86\u547d\u4ee4\u548c\u5de5\u5177\u8c03\u7528\uff0c\u4f46\u4e0d\u80fd\u5b8c\u5168\u5c55\u73b0\u667a\u80fd\u4f53\u5982\u4f55\u901a\u8fc7\u63a2\u7d22\u79ef\u7d2f\u8bc1\u636e\u3002</li>\n    <li>TerminalHorizon\u662f\u4e00\u4e2a\u81ea\u52a8\u5316\u6570\u636e\u5408\u6210\u5f15\u64ce\uff0c\u7528\u4e8e\u957f\u65f6\u95f4\u8f68\u8ff9\u7684\u7ec8\u7aef\u667a\u80fd\u4f53\uff0c\u80fd\u591f\u8bc6\u522b\u5e76\u8865\u5145\u5173\u952e\u5de5\u4f5c\u3002</li>\n    <li>\u8be5\u5f15\u64ce\u901a\u8fc7\u9010\u6b65\u6269\u5c55\u4efb\u52a1\uff0c\u63a8\u52a8\u667a\u80fd\u4f53\u5728\u540c\u4e00\u76ee\u6807\u4e0b\u8fdb\u884c\u8fdb\u4e00\u6b65\u63a2\u7d22\u548c\u6539\u8fdb\u3002</li>\n    <li>\u4f7f\u7528\u8fd9\u4e2a\u5f15\u64ce\uff0c\u6211\u4eec\u6784\u5efa\u4e861500\u4e2a\u4efb\u52a1\u73af\u5883\uff0c\u5e76\u5728\u591a\u9879\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u53d6\u5f97\u4e86\u663e\u8457\u6027\u80fd\u63d0\u5347\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Terminal agents are evolving from simple local tasks to completing complex professional jobs.</li>\n    <li>Short task examples show basic actions, but don't demonstrate how agents learn and adjust over time.</li>\n    <li>TerminalHorizon is a new tool that creates long-term task environments for agents to explore and improve their work.</li>\n    <li>It builds on real-world tasks, guiding agents through new requirements to enhance their problem-solving process.</li>\n    <li>Testing shows that the updated model, TerminalHorizon-27B, performs significantly better in various coding and reasoning tasks.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Scaling Agentic Data for Long-Horizon Terminal Intelligence", "summary": "Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon terminal agents. Starting from real-world professional work, it uses independent execution to identify key work omitted during construction and uses the resulting evidence to guide environment reconstruction. To extend these patterns across stages, it progressively expands tasks under the same goal, introducing new requirements that build on prior results and call for further exploration and improvement. Using this engine, we construct 1.5K task environments and perform supervised fine-tuning of Qwen3.5-27B on the resulting dataset to obtain TerminalHorizon-27B. We achieve substantial performance gains on all 12 benchmarks spanning coding-agent tasks, agentic tasks in real-world production settings, and general reasoning. Multiple RSI case studies, each with a 12-hour research budget, further demonstrate the model's ability to continue experimenting beyond an initial solution, improve its methods based on feedback, and retain effective improvements in its final deliverables.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13166.png", "numComments": 1, "submittedBy": {"_id": "64d1dc5273174cecdffc97d3", "avatarUrl": "/avatars/6564e6b68fee9673f75b6366adf39a3b.svg", "fullname": "Wang Yong", "name": "seashell11", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "68be41370a3fcebdcad6516a", "name": "alibabagroup", "fullname": "alibaba", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68be3ab7e52df040b2cf80dc/li4G29u_EGswyTN1Sm_Kq.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13630", "authors": [{"_id": "6acd8959ead72e0d3c44fd25", "name": "Xiaohan Qin", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd26", "name": "Xiangdong Zhang", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd27", "name": "Tuo Dai", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd28", "name": "Sunan Zou", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd29", "name": "Huaijin Wu", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2a", "name": "Yebin Yang", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2b", "name": "Zhuo Xia", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2c", "name": "Lin Yao", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2d", "name": "Yuliang Liu", "hidden": false}, {"_id": "6acd8959ead72e0d3c44fd2e", "name": "Junchi Yan", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "Multi-Stream Attention Residuals", "submittedOnDailyBy": {"_id": "64452110e1fd8d65b2790bfc", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64452110e1fd8d65b2790bfc/3NIsQFV9X44X88aLXR6eE.jpeg", "isPro": false, "fullname": "Xiaohan Qin (SJTU) & (SII)", "user": "galaxy-1", "type": "user", "name": "galaxy-1"}, "summary": "Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representations through distinct contextual views while preserving the integrity of the hidden representation. The retrieved streams are combined through lightweight adaptive mixing to generate the single-stream layer input. By retaining single-stream sources and expanding them on demand, MSAR supports multi-stream computation without requiring persistent multi-stream storage or communication. Across all 12 downstream benchmarks at the 18B and 28B MoE scales, MSAR consistently outperforms prior residual variants, including standard residual connections, manifold-constrained Hyper-Connections (mHC), and AttnRes. Scaling-law experiments yield an iso-loss compute speedup of 1.58times over the standard residual baseline, compared with 1.35times for AttnRes and 1.30times for mHC. These results make MSAR a promising residual architecture for large-scale pre-training.", "upvotes": 30, "discussionId": "6acd8959ead72e0d3c44fd2f", "githubRepo": "https://github.com/jianke0604/MSAR", "githubRepoAddedBy": "user", "githubStars": 2, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "summary_zh": "<ul>\n    <li>Attention Residuals (AttnRes) \u5141\u8bb8\u57fa\u4e8e\u5185\u5bb9\u7684\u7f51\u7edc\u6df1\u5ea6\u68c0\u7d22\uff0c\u7c7b\u4f3c\u4e8e\u6cbf\u6df1\u5ea6\u8f74\u7684\u5355\u6d41\u8f6f\u6700\u5927\u6ce8\u610f\u529b\u3002</li>\n    <li>Multi-Stream Attention Residuals (MSAR) \u662f AttnRes \u7684\u6269\u5c55\uff0c\u652f\u6301\u591a\u5934\u6df1\u5ea6\u6ce8\u610f\u529b\uff0c\u6027\u80fd\u63d0\u5347\u663e\u8457\u4e14\u5f00\u9500\u8f83\u5c0f\u3002</li>\n    <li>MSAR \u901a\u8fc7\u591a\u5c3a\u5ea6\u56e0\u679c\u5377\u79ef\u4ece\u5e8f\u5217\u4e0a\u4e0b\u6587\u4e2d\u83b7\u53d6\u4e0d\u540c\u7684\u6d41\uff0c\u4f7f\u4e0d\u540c\u7684\u5934\u80fd\u591f\u901a\u8fc7\u4e0d\u540c\u7684\u4e0a\u4e0b\u6587\u89c6\u89d2\u68c0\u7d22\u5386\u53f2\u8868\u793a\u3002</li>\n    <li>\u68c0\u7d22\u7684\u6d41\u901a\u8fc7\u8f7b\u91cf\u7ea7\u81ea\u9002\u5e94\u6df7\u5408\u7ec4\u5408\uff0c\u751f\u6210\u5355\u6d41\u5c42\u8f93\u5165\uff0c\u652f\u6301\u6309\u9700\u6269\u5927\u591a\u6d41\u8ba1\u7b97\u3002</li>\n    <li>\u5728\u6240\u6709 12 \u4e2a\u4e0b\u6e38\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cMSAR \u59cb\u7ec8\u4f18\u4e8e\u4e4b\u524d\u7684\u6b8b\u5dee\u53d8\u4f53\uff0c\u4e14\u8ba1\u7b97\u901f\u5ea6\u63d0\u5347\u663e\u8457\uff0c\u9002\u5408\u5927\u89c4\u6a21\u9884\u8bad\u7ec3\u3002 </li>\n</ul>", "summary_simple": "<ul>\n    <li>MSAR (Multi-Stream Attention Residuals) improves how models retrieve information by using multiple attention streams along the depth of a network.</li>\n    <li>It enhances the single-stream attention method (AttnRes) by allowing different heads to access diverse historical data without losing important information.</li>\n    <li>MSAR combines these different streams using a simple mixing method to create an effective input for the model.</li>\n    <li>In tests across various benchmarks, MSAR consistently performs better than previous models and methods, showing significant speed improvements in processing.</li>\n    <li>This architecture is seen as a strong option for training large-scale models effectively.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "Multi-Stream Attention Residuals", "summary": "Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representations through distinct contextual views while preserving the integrity of the hidden representation. The retrieved streams are combined through lightweight adaptive mixing to generate the single-stream layer input. By retaining single-stream sources and expanding them on demand, MSAR supports multi-stream computation without requiring persistent multi-stream storage or communication. Across all 12 downstream benchmarks at the 18B and 28B MoE scales, MSAR consistently outperforms prior residual variants, including standard residual connections, manifold-constrained Hyper-Connections (mHC), and AttnRes. Scaling-law experiments yield an iso-loss compute speedup of 1.58times over the standard residual baseline, compared with 1.35times for AttnRes and 1.30times for mHC. These results make MSAR a promising residual architecture for large-scale pre-training.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13630.png", "numComments": 1, "submittedBy": {"_id": "64452110e1fd8d65b2790bfc", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64452110e1fd8d65b2790bfc/3NIsQFV9X44X88aLXR6eE.jpeg", "fullname": "Xiaohan Qin (SJTU) & (SII)", "name": "galaxy-1", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "63e5ef7bf2e9a8f22c515654", "name": "SJTU", "fullname": "Shanghai Jiao Tong University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1676013394657-63e5ee22b6a40bf941da0928.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13395", "authors": [{"_id": "6acc3a880ee6ff34004fdd6c", "name": "Chengyi Yang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd6d", "name": "Renxu Bao", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd6e", "name": "Jue Hou", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd6f", "name": "Zongpei Teng", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd70", "name": "Ziheng Wang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd71", "name": "Yujie Lin", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd72", "name": "Chengsong Huang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd73", "name": "Junnan Zhu", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd74", "name": "Delai Qiu", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd75", "name": "Yining Wang", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd76", "name": "Shengping Liu", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd77", "name": "Fei Long", "hidden": false}, {"_id": "6acc3a880ee6ff34004fdd78", "name": "Jinsong Su", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-12T00:00:00.000Z", "title": "ProgramGym: Scaling Training Environments for Long-Horizon Program Reproduction Agents", "submittedOnDailyBy": {"_id": "681ab9d3d7dbd87287875667", "avatarUrl": "/avatars/1a2785d7a250c4988b1c1c5cc78e53fc.svg", "isPro": false, "fullname": "ChengyiYang", "user": "ChengyiYang", "type": "user", "name": "ChengyiYang"}, "summary": "Coding agents are increasingly used to build programs from scratch as software engineers do rather than to resolve issues within a repository or to generate a repository from a given requirements document. However, scalable verifiable training environments that force agents to discover what is required and to decide how the system should be designed remain scarce. Moreover, existing agent workflows also cannot sustain long-horizon development in which the agent explores the reference program before implementation. To address these challenges, we introduce ProgramGym, a framework consisting of Program-Env and Program-Agent for scalable training environments of long-horizon program reproduction agents. Specifically, Program-Env constructs verifiable training environments from repositories through a feedback-driven loop that repairs runtime sandbox builds and the quality of black-box tests. Using this novel pipeline, we obtain 1,648 training environments spanning C, C++, Go, and Rust. Program-Agent combines a role-isolated workflow of analysis, implementation, and review with revision management for compilation checks and failure recovery. Experiments on ProgramBench show that both Program-Env and Program-Agent improve performance on program reproduction. Fine-tuning on trajectories with these constructed environments raises the performance of Qwen3.8-27B from 34.87% to 42.84%. Program-Agent further raises the base and SFT models to 55.71% and 56.25%, both exceeding some flagship models. We will release the ProgramGym to support further research on coding agents that build programs from scratch.", "upvotes": 27, "discussionId": "6acc3a890ee6ff34004fdd79", "projectPage": "https://programgym.github.io/", "githubRepo": "https://github.com/Acm1011/ProgramGym", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "6a71a45f584d1d33007a4f56", "name": "ProgramGym", "fullname": "ProgramGym", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68676f9642df3fdd87e5d368/PZQwVyqoKPrpaVSqYk1E7.png"}, "summary_zh": "<ul>\n    <li>\u7f16\u7801\u4ee3\u7406\u8d8a\u6765\u8d8a\u591a\u5730\u7528\u4e8e\u4ece\u5934\u6784\u5efa\u7a0b\u5e8f\uff0c\u4f46\u7f3a\u4e4f\u53ef\u6269\u5c55\u7684\u8bad\u7ec3\u73af\u5883\u3002</li>\n    <li>ProgramGym\u662f\u4e00\u4e2a\u65b0\u6846\u67b6\uff0c\u5305\u542bProgram-Env\u548cProgram-Agent\uff0c\u7528\u4e8e\u957f\u65f6\u95f4\u7a0b\u5e8f\u91cd\u73b0\u7684\u8bad\u7ec3\u3002</li>\n    <li>Program-Env\u901a\u8fc7\u53cd\u9988\u5faa\u73af\u6784\u5efa\u53ef\u9a8c\u8bc1\u7684\u8bad\u7ec3\u73af\u5883\uff0c\u5e76\u4fee\u590d\u8fd0\u884c\u65f6\u9519\u8bef\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cProgram-Env\u548cProgram-Agent\u63d0\u9ad8\u4e86\u7a0b\u5e8f\u91cd\u73b0\u7684\u6027\u80fd\uff0cQwen3.8-27B\u7684\u51c6\u786e\u7387\u4ece34.87%\u63d0\u5347\u523042.84%\u3002</li>\n    <li>\u6211\u4eec\u5c06\u53d1\u5e03ProgramGym\uff0c\u4ee5\u652f\u6301\u8fdb\u4e00\u6b65\u7814\u7a76\u4ece\u5934\u6784\u5efa\u7a0b\u5e8f\u7684\u7f16\u7801\u4ee3\u7406\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Coding agents are now being used to create software from the ground up, similar to how human engineers work.</li>\n    <li>There is a lack of scalable training environments that help these agents learn what is needed and how to design systems.</li>\n    <li>The new framework, ProgramGym, includes Program-Env and Program-Agent to improve long-term program development.</li>\n    <li>Program-Env creates training environments from existing code repositories, while Program-Agent manages the coding process and error recovery.</li>\n    <li>Testing showed that using ProgramGym significantly improved the performance of coding agents, with some models exceeding top benchmarks.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "ProgramGym: Scaling Training Environments for Long-Horizon Program Reproduction Agents", "summary": "Coding agents are increasingly used to build programs from scratch as software engineers do rather than to resolve issues within a repository or to generate a repository from a given requirements document. However, scalable verifiable training environments that force agents to discover what is required and to decide how the system should be designed remain scarce. Moreover, existing agent workflows also cannot sustain long-horizon development in which the agent explores the reference program before implementation. To address these challenges, we introduce ProgramGym, a framework consisting of Program-Env and Program-Agent for scalable training environments of long-horizon program reproduction agents. Specifically, Program-Env constructs verifiable training environments from repositories through a feedback-driven loop that repairs runtime sandbox builds and the quality of black-box tests. Using this novel pipeline, we obtain 1,648 training environments spanning C, C++, Go, and Rust. Program-Agent combines a role-isolated workflow of analysis, implementation, and review with revision management for compilation checks and failure recovery. Experiments on ProgramBench show that both Program-Env and Program-Agent improve performance on program reproduction. Fine-tuning on trajectories with these constructed environments raises the performance of Qwen3.8-27B from 34.87% to 42.84%. Program-Agent further raises the base and SFT models to 55.71% and 56.25%, both exceeding some flagship models. We will release the ProgramGym to support further research on coding agents that build programs from scratch.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13395.png", "numComments": 1, "submittedBy": {"_id": "681ab9d3d7dbd87287875667", "avatarUrl": "/avatars/1a2785d7a250c4988b1c1c5cc78e53fc.svg", "fullname": "ChengyiYang", "name": "ChengyiYang", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6a71a45f584d1d33007a4f56", "name": "ProgramGym", "fullname": "ProgramGym", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68676f9642df3fdd87e5d368/PZQwVyqoKPrpaVSqYk1E7.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12299", "authors": [{"_id": "6ac8603a4364a3d18a5cc821", "name": "Dahyun Chung", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc822", "name": "Siyoon Jin", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc823", "name": "Hyunwook Choi", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc824", "name": "Honggyu An", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc825", "name": "Junyoung Seo", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc826", "name": "Hyunsung Kim", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc827", "name": "Seung Wook Kim", "hidden": false}, {"_id": "6ac8603a4364a3d18a5cc828", "name": "Seungryong Kim", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66f7a013380c9f89971c078d/ytSOECv7KP7z0f6FWQ4HL.mp4"], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction", "submittedOnDailyBy": {"_id": "66f7a013380c9f89971c078d", "avatarUrl": "/avatars/a01d393575aacd7f74a12c22fe43a30d.svg", "isPro": true, "fullname": "HyunWook Choi", "user": "enrue1893", "type": "user", "name": "enrue1893"}, "summary": "Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, and grounds generation with shared environment memory. We train and evaluate on real and synthetic multi-agent data and introduce shared-world consistency metrics for environment, update, and identity consistency. Experiments show ME-World improves shared-world consistency, action control, identity preservation, and video quality over existing methods.", "upvotes": 27, "discussionId": "6ac8603a4364a3d18a5cc829", "projectPage": "https://cvlab-kaist.github.io/ME-World/", "githubRepo": "https://github.com/cvlab-kaist/ME-World", "githubRepoAddedBy": "user", "githubStars": 14, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u672c\u6587\u63d0\u51fa\u4e86\u4e00\u79cd\u591a\u667a\u80fd\u4f53\u81ea\u6211\u4e2d\u5fc3\u4e16\u754c\u6a21\u578b\uff0c\u5173\u6ce8\u591a\u4e2a\u667a\u80fd\u4f53\u5728\u5171\u4eab\u73af\u5883\u4e2d\u7684\u7ec6\u7c92\u5ea6\u4e92\u52a8\u3002</li>\n    <li>\u73b0\u6709\u7684\u591a\u667a\u80fd\u4f53\u6a21\u578b\u4e3b\u8981\u4f9d\u8d56\u4e8e\u7c97\u7cd9\u7684\u52a8\u4f5c\uff0c\u5982\u79fb\u52a8\u6216\u76f8\u673a\u63a7\u5236\uff0c\u7f3a\u4e4f\u5bf9\u590d\u6742\u4e92\u52a8\u7684\u63a2\u7d22\u3002</li>\n    <li>\u65b0\u6a21\u578b\uff08ME-World\uff09\u901a\u8fc7\u540c\u6b65\u751f\u6210\u591a\u4e2a\u667a\u80fd\u4f53\u7684\u81ea\u6211\u6d41\uff0c\u786e\u4fdd\u52a8\u4f5c\u4e00\u81f4\u6027\u548c\u73af\u5883\u4e00\u81f4\u6027\u3002</li>\n    <li>ME-World\u5728\u771f\u5b9e\u548c\u5408\u6210\u7684\u591a\u667a\u80fd\u4f53\u6570\u636e\u4e0a\u8fdb\u884c\u8bad\u7ec3\u548c\u8bc4\u4f30\uff0c\u63d0\u51fa\u4e86\u65b0\u7684\u5171\u4eab\u4e16\u754c\u4e00\u81f4\u6027\u6307\u6807\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u663e\u793a\uff0cME-World\u5728\u5171\u4eab\u4e16\u754c\u4e00\u81f4\u6027\u3001\u52a8\u4f5c\u63a7\u5236\u3001\u8eab\u4efd\u4fdd\u6301\u548c\u89c6\u9891\u8d28\u91cf\u4e0a\u5747\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>The study focuses on creating a model that predicts how multiple agents interact in a shared environment, moving beyond single-agent models.</li>\n    <li>Current models mainly use basic actions, so this research looks at more detailed interactions between agents.</li>\n    <li>A new model called Multi-agent Egocentric World Model (ME-World) is introduced, which synchronizes actions and observations of multiple agents.</li>\n    <li>ME-World improves the consistency of interactions, actions, and identity of agents in the environment.</li>\n    <li>Tests show that ME-World performs better in video quality and maintaining consistent environments compared to older models.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction", "summary": "Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, and grounds generation with shared environment memory. We train and evaluate on real and synthetic multi-agent data and introduce shared-world consistency metrics for environment, update, and identity consistency. Experiments show ME-World improves shared-world consistency, action control, identity preservation, and video quality over existing methods.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66f7a013380c9f89971c078d/ytSOECv7KP7z0f6FWQ4HL.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12299.png", "numComments": 1, "submittedBy": {"_id": "66f7a013380c9f89971c078d", "avatarUrl": "/avatars/a01d393575aacd7f74a12c22fe43a30d.svg", "fullname": "HyunWook Choi", "name": "enrue1893", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.12818", "authors": [{"_id": "6acd6cfeead72e0d3c44fbc7", "user": {"_id": "6678585635c15b509c850261", "avatarUrl": "/avatars/78d851885ff7f2d744e5b553c6c5ac06.svg", "isPro": true, "fullname": "Minghao Fu", "user": "MinghaoFu", "type": "user", "name": "MinghaoFu"}, "name": "Minghao Fu", "status": "claimed_verified", "statusLastChangedAt": "2026-10-13T00:45:05.116Z", "hidden": false}, {"_id": "6acd6cfeead72e0d3c44fbc8", "user": {"_id": "65e3f232f70c00af963b2179", "avatarUrl": "/avatars/84d97de3aeb32154b587f40cf46a5125.svg", "isPro": false, "fullname": "Tavis Siebert", "user": "tavi-sie", "type": "user", "name": "tavi-sie"}, "name": "Tavis Siebert", "status": "claimed_verified", "statusLastChangedAt": "2026-10-13T00:45:05.106Z", "hidden": false}, {"_id": "6acd6cfeead72e0d3c44fbc9", "user": {"_id": "68f7c5cfc48410ed17e25ec7", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/md_CN6FSaBpCfGuYU1sJX.jpeg", "isPro": false, "fullname": "Eryk Halicki", "user": "ehalicki", "type": "user", "name": "ehalicki"}, "name": "Eryk Halicki", "status": "claimed_verified", "statusLastChangedAt": "2026-10-14T00:45:04.864Z", "hidden": false}, {"_id": "6acd6cfeead72e0d3c44fbca", "name": "Randall Balestriero", "hidden": false}], "publishedAt": "2026-10-08T00:00:00.000Z", "submittedOnDailyAt": "2026-10-14T00:00:00.000Z", "title": "LeWAM: End-to-End World and Action Modeling with JEPAs", "submittedOnDailyBy": {"_id": "6678585635c15b509c850261", "avatarUrl": "/avatars/78d851885ff7f2d744e5b553c6c5ac06.svg", "isPro": true, "fullname": "Minghao Fu", "user": "MinghaoFu", "type": "user", "name": "MinghaoFu"}, "summary": "Joint-embedding predictive architectures (JEPAs) learn compact latent world models without pixel reconstruction. Existing JEPA pipelines typically train visual representations and action-conditioned dynamics before adding a control policy or solver. We introduce LeWAM, an end-to-end JEPA for control with: (1) a joint training objective over next latent state prediction and action flow matching, and (2) an isotropic Gaussian constraint on the latent state, enabling a single model to support direct policy execution and efficient planning by evaluating sampled actions with its learned latent dynamics. Compared with prior JEPAs in visual planning, LeWAM improves success rate from 28.6% to 89.7% on contact-rich tasks and from 10.9% to 46.2% on long-horizon tasks, and plans 32.3 times faster. On behavior cloning tasks in simulation and physical robots, LeWAM is also competitive with established methods. Interpretability analyses show that LeWAM learns control-relevant representations and action distributions effectively guiding test-time planning and control.", "upvotes": 22, "discussionId": "6acd6cffead72e0d3c44fbcb", "projectPage": "https://le-wam.github.io/", "githubRepo": "https://github.com/MinghaoFu/lewam", "githubRepoAddedBy": "user", "githubStars": 228, "organization": {"_id": "6ac2f6069f39a66f240523a6", "name": "LeWAM", "fullname": "LeWAM", "avatar": "https://www.gravatar.com/avatar/13a0ac54a3ef634d52eeebaed58ebaeb?d=retro&size=100"}, "summary_zh": "<ul>\n    <li>LeWAM\u662f\u4e00\u79cd\u65b0\u578b\u7684\u8054\u5408\u5d4c\u5165\u9884\u6d4b\u67b6\u6784\uff08JEPA\uff09\uff0c\u53ef\u4ee5\u5b66\u4e60\u7d27\u51d1\u7684\u6f5c\u5728\u4e16\u754c\u6a21\u578b\uff0c\u800c\u65e0\u9700\u50cf\u7d20\u91cd\u5efa\u3002</li>\n    <li>\u5b83\u901a\u8fc7\u5171\u540c\u8bad\u7ec3\u4e0b\u4e00\u4e2a\u6f5c\u5728\u72b6\u6001\u9884\u6d4b\u548c\u52a8\u4f5c\u6d41\u5339\u914d\u6765\u4f18\u5316\u63a7\u5236\u7b56\u7565\u3002</li>\n    <li>LeWAM\u5f15\u5165\u4e86\u5bf9\u6f5c\u5728\u72b6\u6001\u7684\u7b49\u65b9\u5dee\u9ad8\u65af\u7ea6\u675f\uff0c\u4f7f\u5f97\u6a21\u578b\u80fd\u591f\u76f4\u63a5\u6267\u884c\u7b56\u7565\u548c\u9ad8\u6548\u89c4\u5212\u3002</li>\n    <li>\u5728\u590d\u6742\u4efb\u52a1\u4e2d\uff0cLeWAM\u7684\u6210\u529f\u7387\u663e\u8457\u63d0\u9ad8\uff0c\u4ece28.6%\u63d0\u5347\u523089.7%\uff0c\u5e76\u4e14\u89c4\u5212\u901f\u5ea6\u5feb\u4e8632.3\u500d\u3002</li>\n    <li>LeWAM\u5728\u6a21\u62df\u548c\u7269\u7406\u673a\u5668\u4eba\u884c\u4e3a\u514b\u9686\u4efb\u52a1\u4e2d\u8868\u73b0\u51fa\u8272\uff0c\u5e76\u4e14\u80fd\u591f\u6709\u6548\u6307\u5bfc\u6d4b\u8bd5\u65f6\u7684\u89c4\u5212\u548c\u63a7\u5236\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>LeWAM is a new model that helps control systems learn without needing to recreate images.</li>\n    <li>It trains to predict future states and matches actions, allowing better control in tasks.</li>\n    <li>LeWAM significantly improves success rates in complex tasks and plans actions much faster than previous models.</li>\n    <li>It performs well in both simulations and real robots, competing with established methods.</li>\n    <li>LeWAM effectively learns useful representations that help with planning and controlling actions during tests.</li>\n</ul>"}, "publishedAt": "2026-10-07T20:00:00.000Z", "title": "LeWAM: End-to-End World and Action Modeling with JEPAs", "summary": "Joint-embedding predictive architectures (JEPAs) learn compact latent world models without pixel reconstruction. Existing JEPA pipelines typically train visual representations and action-conditioned dynamics before adding a control policy or solver. We introduce LeWAM, an end-to-end JEPA for control with: (1) a joint training objective over next latent state prediction and action flow matching, and (2) an isotropic Gaussian constraint on the latent state, enabling a single model to support direct policy execution and efficient planning by evaluating sampled actions with its learned latent dynamics. Compared with prior JEPAs in visual planning, LeWAM improves success rate from 28.6% to 89.7% on contact-rich tasks and from 10.9% to 46.2% on long-horizon tasks, and plans 32.3 times faster. On behavior cloning tasks in simulation and physical robots, LeWAM is also competitive with established methods. Interpretability analyses show that LeWAM learns control-relevant representations and action distributions effectively guiding test-time planning and control.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.12818.png", "numComments": 1, "submittedBy": {"_id": "6678585635c15b509c850261", "avatarUrl": "/avatars/78d851885ff7f2d744e5b553c6c5ac06.svg", "fullname": "Minghao Fu", "name": "MinghaoFu", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6ac2f6069f39a66f240523a6", "name": "LeWAM", "fullname": "LeWAM", "avatar": "https://www.gravatar.com/avatar/13a0ac54a3ef634d52eeebaed58ebaeb?d=retro&size=100"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.13021", "authors": [{"_id": "6acc35b90ee6ff34004fdd2d", "name": "Jie Huang", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd2e", "name": "Yanan Chen", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd2f", "name": "Ruixun Liu", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd30", "name": "Kaichen He", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd31", "name": "Xinyi He", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd32", "name": "Rui Huang", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd33", "name": "Zilong Zheng", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd34", "name": "Zhenliang Zhang", "hidden": false}, {"_id": "6acc35b90ee6ff34004fdd35", "name": "Yiwu Zhong", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-12T00:00:00.000Z", "title": "EmbodiedCLBench: Evaluating Continual Learning for Self-Evolving Embodied Agents", "submittedOnDailyBy": {"_id": "65bda9874b5f8c270de11440", "avatarUrl": "/avatars/353f33c198752a634b8e6a422aa8008d.svg", "isPro": false, "fullname": "Huang Jie", "user": "JadeHuang", "type": "user", "name": "JadeHuang"}, "summary": "Continual learning requires models to accumulate past experience and transfer it to new tasks. Despite substantial research on continual learning, existing work remains largely confined to non-embodied settings, without extending to embodied environments. To address this gap, we introduce EmbodiedCLBench, the first benchmark in embodied simulation for evaluating the continual learning capability of self-evolving agents. With compositional generalization as the core evaluation principle, our benchmark evaluates whether agents can first learn from basic tasks and then recombine the acquired skills to solve complex, unseen advanced tasks. Based on EmbodiedCLBench, we conduct extensive experiments across multiple agent harnesses and learning methods, revealing consistent limitations and distinctive behaviors. Our results show that while advanced tasks can be hardly solved under zero-shot setting, the experience from basic tasks enables consistent improvement. Such benefit from the experience remains stable even if the task complexity increases. However, this improvement does not scale accordingly with the number of learning samples, and current agents cannot extract meaningful information from additional experience. Collectively, our findings highlight continual learning as a fundamental yet underexplored capability, and our benchmark offers valuable resources for designing effective self-evolving agents in embodied environments. Our code and dataset are available at https://pku-value-lab.github.io/EmbodiedCLBench-homepage.", "upvotes": 21, "discussionId": "6acc35ba0ee6ff34004fdd36", "projectPage": "https://pku-value-lab.github.io/EmbodiedCLBench-homepage/", "githubRepo": "https://github.com/PKU-VaLuE-Lab/EmbodiedCLBench", "githubRepoAddedBy": "user", "githubStars": 3, "organization": {"_id": "6a07ff936781d8b803c28343", "name": "PKU-VaLuE-Lab", "fullname": "PKU-VaLuE-Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/62b4fe7ab25cb80fcf2ffd66/velgm3kH_oJ2b0aoapBBM.png"}, "summary_zh": "<ul>\n    <li>\u6301\u7eed\u5b66\u4e60\u9700\u8981\u6a21\u578b\u79ef\u7d2f\u8fc7\u53bb\u7684\u7ecf\u9a8c\u5e76\u5c06\u5176\u8f6c\u79fb\u5230\u65b0\u4efb\u52a1\u4e2d\u3002</li>\n    <li>\u6211\u4eec\u63a8\u51fa\u4e86EmbodiedCLBench\uff0c\u8fd9\u662f\u7b2c\u4e00\u4e2a\u7528\u4e8e\u8bc4\u4f30\u81ea\u6211\u8fdb\u5316\u4ee3\u7406\u5728\u5177\u8eab\u73af\u5883\u4e2d\u6301\u7eed\u5b66\u4e60\u80fd\u529b\u7684\u57fa\u51c6\u3002</li>\n    <li>\u57fa\u4e8e\u57fa\u672c\u4efb\u52a1\u7684\u5b66\u4e60\uff0c\u4ee3\u7406\u53ef\u4ee5\u91cd\u65b0\u7ec4\u5408\u6280\u80fd\u89e3\u51b3\u590d\u6742\u7684\u65b0\u4efb\u52a1\u3002</li>\n    <li>\u5c3d\u7ba1\u5728\u96f6\u6837\u672c\u8bbe\u7f6e\u4e0b\u5f88\u96be\u89e3\u51b3\u9ad8\u7ea7\u4efb\u52a1\uff0c\u4f46\u57fa\u7840\u4efb\u52a1\u7684\u7ecf\u9a8c\u80fd\u5e26\u6765\u6301\u7eed\u6539\u5584\u3002</li>\n    <li>\u6211\u4eec\u7684\u7814\u7a76\u8868\u660e\uff0c\u6301\u7eed\u5b66\u4e60\u662f\u4e00\u4e2a\u91cd\u8981\u4f46\u5c1a\u672a\u5145\u5206\u63a2\u7d22\u7684\u80fd\u529b\uff0c\u63d0\u4f9b\u4e86\u8bbe\u8ba1\u6709\u6548\u81ea\u6211\u8fdb\u5316\u4ee3\u7406\u7684\u5b9d\u8d35\u8d44\u6e90\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Continual learning helps models use past experiences to tackle new tasks, but much research hasn't focused on real-world settings.</li>\n    <li>We introduce EmbodiedCLBench, a new benchmark for testing continual learning in agents that operate in physical environments.</li>\n    <li>The benchmark measures if agents can learn basic tasks and combine those skills to solve more complex, unseen tasks.</li>\n    <li>Our experiments show that while agents struggle with new tasks without prior experience, learning basic tasks helps them improve consistently.</li>\n    <li>However, agents don't learn better with more data, indicating a need for better methods in continual learning for real-world applications.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "EmbodiedCLBench: Evaluating Continual Learning for Self-Evolving Embodied Agents", "summary": "Continual learning requires models to accumulate past experience and transfer it to new tasks. Despite substantial research on continual learning, existing work remains largely confined to non-embodied settings, without extending to embodied environments. To address this gap, we introduce EmbodiedCLBench, the first benchmark in embodied simulation for evaluating the continual learning capability of self-evolving agents. With compositional generalization as the core evaluation principle, our benchmark evaluates whether agents can first learn from basic tasks and then recombine the acquired skills to solve complex, unseen advanced tasks. Based on EmbodiedCLBench, we conduct extensive experiments across multiple agent harnesses and learning methods, revealing consistent limitations and distinctive behaviors. Our results show that while advanced tasks can be hardly solved under zero-shot setting, the experience from basic tasks enables consistent improvement. Such benefit from the experience remains stable even if the task complexity increases. However, this improvement does not scale accordingly with the number of learning samples, and current agents cannot extract meaningful information from additional experience. Collectively, our findings highlight continual learning as a fundamental yet underexplored capability, and our benchmark offers valuable resources for designing effective self-evolving agents in embodied environments. Our code and dataset are available at https://pku-value-lab.github.io/EmbodiedCLBench-homepage.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13021.png", "numComments": 1, "submittedBy": {"_id": "65bda9874b5f8c270de11440", "avatarUrl": "/avatars/353f33c198752a634b8e6a422aa8008d.svg", "fullname": "Huang Jie", "name": "JadeHuang", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "6a07ff936781d8b803c28343", "name": "PKU-VaLuE-Lab", "fullname": "PKU-VaLuE-Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/62b4fe7ab25cb80fcf2ffd66/velgm3kH_oJ2b0aoapBBM.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.13361", "authors": [{"_id": "6accd8fa0ee6ff34004fe25c", "name": "Jiahao Wang", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe25d", "name": "Hongjin Qian", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe25e", "name": "Yuyang Hu", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe25f", "name": "Jiajun Zhang", "hidden": false}, {"_id": "6accd8fa0ee6ff34004fe260", "name": "Zheng Liu", "hidden": false}], "publishedAt": "2026-10-09T00:00:00.000Z", "submittedOnDailyAt": "2026-10-13T00:00:00.000Z", "title": "AgentSWE: Can Coding Agents Build the Agent You Actually Want?", "submittedOnDailyBy": {"_id": "64a627232944e255ef574dda", "avatarUrl": "/avatars/4c2fd5bf922013fe691c6a3e3fa138a2.svg", "isPro": false, "fullname": "Hongjin Qian", "user": "TommyChien", "type": "user", "name": "TommyChien"}, "summary": "As the production of software passes into the hands of software itself, coding agents are increasingly commissioned to build agents fitted to their users' own workflows. This delegation carries a quiet assumption, that the delivered agent will faithfully serve the requirement it was built for, rather than merely appear to. No existing benchmark tests that assumption. We introduce AgentSWE, a benchmark for agent software engineering spanning three stages of the agent development lifecycle: Creation of a complete agent from a natural-language requirement, Editing of production agent codebases, and Optimization toward a measurable target. Each of its 25 tasks is framed as a commission rather than an exam: the builder iterates against a handful of illustrative cases, while acceptance exercises the frozen submission on held-out cases designed to span the full requirement, grading behavior against requirement-derived rubrics under hard pass/fail gates or, for Optimization, against the source benchmark's own objective. Evaluating a range of coding agents across models and harnesses, we find that none comes close to delivering what a requirement asks for: the gap between what a builder demonstrates and what it delivers is the norm, not the corner case. An accompanying empirical analysis of the failure trajectories identifies recurring failure modes, among them overfitting to the visible cases, hollow runtimes behind code that looks complete, and unsupported claims of completion, each a signal by which coding agents can learn to build the agents they are asked for.", "upvotes": 20, "discussionId": "6accd8fb0ee6ff34004fe261", "summary_zh": "<ul>\n    <li>\u968f\u7740\u8f6f\u4ef6\u751f\u4ea7\u8d8a\u6765\u8d8a\u4f9d\u8d56\u4e8e\u8f6f\u4ef6\u672c\u8eab\uff0c\u4ee3\u7801\u4ee3\u7406\u88ab\u59d4\u6258\u521b\u5efa\u9002\u5e94\u7528\u6237\u5de5\u4f5c\u6d41\u7a0b\u7684\u4ee3\u7406\u3002</li>\n    <li>\u8fd9\u79cd\u59d4\u6258\u5047\u8bbe\u6240\u4ea4\u4ed8\u7684\u4ee3\u7406\u80fd\u5fe0\u5b9e\u6ee1\u8db3\u9700\u6c42\uff0c\u800c\u4e0d\u662f\u4ec5\u4ec5\u770b\u8d77\u6765\u6ee1\u8db3\u3002</li>\n    <li>AgentSWE\u662f\u4e00\u4e2a\u65b0\u7684\u57fa\u51c6\u6d4b\u8bd5\uff0c\u6db5\u76d6\u4ee3\u7406\u5f00\u53d1\u751f\u547d\u5468\u671f\u7684\u4e09\u4e2a\u9636\u6bb5\uff1a\u4ece\u81ea\u7136\u8bed\u8a00\u9700\u6c42\u521b\u5efa\u5b8c\u6574\u4ee3\u7406\u3001\u7f16\u8f91\u751f\u4ea7\u4ee3\u7406\u4ee3\u7801\u3001\u4ee5\u53ca\u671d\u5411\u53ef\u6d4b\u76ee\u6807\u7684\u4f18\u5316\u3002</li>\n    <li>\u8be5\u57fa\u51c6\u5305\u542b25\u4e2a\u4efb\u52a1\uff0c\u91c7\u7528\u59d4\u6258\u7684\u65b9\u5f0f\u800c\u975e\u8003\u8bd5\uff0c\u8bc4\u4f30\u6784\u5efa\u8005\u7684\u80fd\u529b\u3002</li>\n    <li>\u8bc4\u4f30\u7ed3\u679c\u663e\u793a\uff0c\u6ca1\u6709\u4efb\u4f55\u4ee3\u7801\u4ee3\u7406\u80fd\u5b8c\u5168\u6ee1\u8db3\u9700\u6c42\uff0c\u5b58\u5728\u660e\u663e\u7684\u5dee\u8ddd\u548c\u91cd\u590d\u7684\u5931\u8d25\u6a21\u5f0f\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Software development is increasingly done by automated coding agents that create new agents based on user needs.</li>\n    <li>There is a lack of tests to ensure these agents truly meet user requirements.</li>\n    <li>AgentSWE is introduced as a benchmark that evaluates agents through three main stages: creation, editing, and optimization.</li>\n    <li>The benchmark features 25 tasks framed as commissions and includes rigorous acceptance testing to evaluate performance against requirements.</li>\n    <li>Results show that current coding agents often fail to meet requirements, highlighting common issues like overfitting and incomplete code.</li>\n</ul>"}, "publishedAt": "2026-10-08T20:00:00.000Z", "title": "AgentSWE: Can Coding Agents Build the Agent You Actually Want?", "summary": "As the production of software passes into the hands of software itself, coding agents are increasingly commissioned to build agents fitted to their users' own workflows. This delegation carries a quiet assumption, that the delivered agent will faithfully serve the requirement it was built for, rather than merely appear to. No existing benchmark tests that assumption. We introduce AgentSWE, a benchmark for agent software engineering spanning three stages of the agent development lifecycle: Creation of a complete agent from a natural-language requirement, Editing of production agent codebases, and Optimization toward a measurable target. Each of its 25 tasks is framed as a commission rather than an exam: the builder iterates against a handful of illustrative cases, while acceptance exercises the frozen submission on held-out cases designed to span the full requirement, grading behavior against requirement-derived rubrics under hard pass/fail gates or, for Optimization, against the source benchmark's own objective. Evaluating a range of coding agents across models and harnesses, we find that none comes close to delivering what a requirement asks for: the gap between what a builder demonstrates and what it delivers is the norm, not the corner case. An accompanying empirical analysis of the failure trajectories identifies recurring failure modes, among them overfitting to the visible cases, hollow runtimes behind code that looks complete, and unsupported claims of completion, each a signal by which coding agents can learn to build the agents they are asked for.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.13361.png", "numComments": 1, "submittedBy": {"_id": "64a627232944e255ef574dda", "avatarUrl": "/avatars/4c2fd5bf922013fe691c6a3e3fa138a2.svg", "fullname": "Hongjin Qian", "name": "TommyChien", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 12, "isUserFollowing": false}, "isAuthorParticipating": false}],
    "month": [{"paper": {"id": "2609.17488", "authors": [{"_id": "6aaa0287f6668522fbb08046", "user": {"_id": "63440a1be01a38440ef25daa", "avatarUrl": "/avatars/622e8ca69f1867be7932d03b91eaf6e7.svg", "isPro": false, "fullname": "Xingxuan Zhang", "user": "xuange", "type": "user", "name": "xuange"}, "name": "Xingxuan Zhang", "status": "claimed_verified", "statusLastChangedAt": "2026-09-16T16:45:04.225Z", "hidden": false}, {"_id": "6aaa0287f6668522fbb08047", "name": "Gang Ren", "hidden": false}, {"_id": "6aaa0287f6668522fbb08048", "name": "Hao Yuan", "hidden": false}, {"_id": "6aaa0287f6668522fbb08049", "name": "Hao Zou", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804a", "name": "Hongze Tan", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804b", "name": "Hui Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804c", "name": "Jianhao Song", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804d", "name": "Jiansheng Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804e", "name": "Jiayao Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0804f", "name": "Jinghan Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08050", "name": "Kaifang Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08051", "name": "Lang Mo", "hidden": false}, {"_id": "6aaa0287f6668522fbb08052", "name": "Li Mao", "hidden": false}, {"_id": "6aaa0287f6668522fbb08053", "name": "Mingchao Hao", "hidden": false}, {"_id": "6aaa0287f6668522fbb08054", "name": "Nuo Xu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08055", "name": "Rui Ding", "hidden": false}, {"_id": "6aaa0287f6668522fbb08056", "name": "Ruiji Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08057", "name": "Shuyang Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08058", "name": "Siyu Mei", "hidden": false}, {"_id": "6aaa0287f6668522fbb08059", "name": "Tianyang Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805a", "name": "Weiyang Mu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805b", "name": "Yancheng Dong", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805c", "name": "Yongxian Wei", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805d", "name": "Yuan Xue", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805e", "name": "Yuanrui Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0805f", "name": "Yue He", "hidden": false}, {"_id": "6aaa0287f6668522fbb08060", "name": "Zijia Yang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08061", "name": "Ziyun Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08062", "name": "Dongzhe Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08063", "name": "Fuqiang Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08064", "name": "Jiandong Liu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08065", "name": "Jiawei Chen", "hidden": false}, {"_id": "6aaa0287f6668522fbb08066", "name": "Jiaxin Du", "hidden": false}, {"_id": "6aaa0287f6668522fbb08067", "name": "Kaijie Cheng", "hidden": false}, {"_id": "6aaa0287f6668522fbb08068", "name": "Kehan Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08069", "name": "Lei Sun", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806a", "name": "Linjun Zhou", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806b", "name": "Ningbo Dai", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806c", "name": "Qi Wang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806d", "name": "Renzhe Xu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806e", "name": "Shaoxing Du", "hidden": false}, {"_id": "6aaa0287f6668522fbb0806f", "name": "Shumeng Yang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08070", "name": "Wang Lu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08071", "name": "Wenjing Chu", "hidden": false}, {"_id": "6aaa0287f6668522fbb08072", "name": "Xiannan Huang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08073", "name": "Xiaoyu Lin", "hidden": false}, {"_id": "6aaa0287f6668522fbb08074", "name": "Xing Ai", "hidden": false}, {"_id": "6aaa0287f6668522fbb08075", "name": "Xinyan Han", "hidden": false}, {"_id": "6aaa0287f6668522fbb08076", "name": "Xuanyue Li", "hidden": false}, {"_id": "6aaa0287f6668522fbb08077", "name": "Xuanyue Su", "hidden": false}, {"_id": "6aaa0287f6668522fbb08078", "name": "Xukun Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08079", "name": "Yan Lu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807a", "name": "Yaxin Zhang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807b", "name": "Yi Qin", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807c", "name": "Yifei Huang", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807d", "name": "Yihan Xu", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807e", "name": "Yongle Lv", "hidden": false}, {"_id": "6aaa0287f6668522fbb0807f", "name": "Yuanyuan Jiang", "hidden": false}, {"_id": "6aaa0287f6668522fbb08080", "name": "Yushan Han", "hidden": false}, {"_id": "6aaa0287f6668522fbb08081", "name": "Peng Cui", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63440a1be01a38440ef25daa/82Td574Ji7ShkZWIF58uf.mp4"], "publishedAt": "2026-09-15T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "LimiX-2: A Contextual Mechanism Network Towards General Structured-Data Intelligence", "submittedOnDailyBy": {"_id": "63440a1be01a38440ef25daa", "avatarUrl": "/avatars/622e8ca69f1867be7932d03b91eaf6e7.svg", "isPro": false, "fullname": "Xingxuan Zhang", "user": "xuange", "type": "user", "name": "xuange"}, "summary": "We introduce LimiX-2, a new model in the LimiX family, developed through model and data scaling guided by our previously established scaling laws. LimiX-2 adopts the Contextual Mechanism Networks (CMNs) paradigm and is pretrained with Context-Conditional Masked Modeling (CCMM). CMNs shifts the organizing principle of in-context learning from target-centric prediction to mechanism-oriented joint modeling. Rather than centering the network on the p(y mid x, D_{context}) objective of conventional tabular PFNs, it is designed around learning p(x, y mid D_{context}), a context-dependent representation of the joint structure underlying data generation. Pretraining uses synthetic datasets generated by structural causal models (SCMs) spanning diverse graph structures, functional mechanisms, and observation processes. Evaluations on TabArena, TALENT, and BCCO show that LimiX-2 outperforms current dataset-specific models and tabular foundation models. Beyond predictive performance, the CMN paradigm also promotes causal awareness in LimiX-2: its feature attention encodes direct causal relationships, enabling accurate causal skeleton recovery.", "upvotes": 126, "discussionId": "6aaa0288f6668522fbb08082", "projectPage": "https://www.limix.ai/", "githubRepo": "https://github.com/limix-ldm-ai/LimiX", "githubRepoAddedBy": "user", "githubStars": 4195, "organization": {"_id": "6911d3dc57d393d3cfe628bf", "name": "stable-ai", "fullname": "Stable AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68aa772042ec888900da6a6b/ykANVIVEnhVZ1fdsEz7BQ.png"}, "summary_zh": "<ul>\n    <li>\u63a8\u51fa\u4e86\u65b0\u7684\u6a21\u578bLimiX-2\uff0c\u5c5e\u4e8eLimiX\u7cfb\u5217\uff0c\u901a\u8fc7\u6a21\u578b\u548c\u6570\u636e\u6269\u5c55\u7684\u6307\u5bfc\u800c\u5f00\u53d1\u3002</li>\n    <li>LimiX-2\u91c7\u7528\u4e86\u4e0a\u4e0b\u6587\u673a\u5236\u7f51\u7edc\uff08CMNs\uff09\u8303\u5f0f\uff0c\u5e76\u4f7f\u7528\u4e0a\u4e0b\u6587\u6761\u4ef6\u63a9\u853d\u5efa\u6a21\uff08CCMM\uff09\u8fdb\u884c\u9884\u8bad\u7ec3\u3002</li>\n    <li>CMNs\u6539\u53d8\u4e86\u4e0a\u4e0b\u6587\u5b66\u4e60\u7684\u7ec4\u7ec7\u539f\u5219\uff0c\u4e13\u6ce8\u4e8e\u673a\u5236\u5bfc\u5411\u7684\u8054\u5408\u5efa\u6a21\u3002</li>\n    <li>\u9884\u8bad\u7ec3\u4f7f\u7528\u4e86\u7531\u7ed3\u6784\u56e0\u679c\u6a21\u578b\uff08SCMs\uff09\u751f\u6210\u7684\u5408\u6210\u6570\u636e\u96c6\uff0c\u6db5\u76d6\u591a\u79cd\u56fe\u7ed3\u6784\u548c\u529f\u80fd\u673a\u5236\u3002</li>\n    <li>\u5728\u591a\u4e2a\u8bc4\u4f30\u5e73\u53f0\u4e0a\uff0cLimiX-2\u7684\u8868\u73b0\u8d85\u8fc7\u4e86\u5f53\u524d\u7684\u6570\u636e\u96c6\u7279\u5b9a\u6a21\u578b\u548c\u8868\u683c\u57fa\u7840\u6a21\u578b\uff0c\u5e76\u589e\u5f3a\u4e86\u56e0\u679c\u610f\u8bc6\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>LimiX-2 is a new model that builds on previous research and uses a unique approach called Contextual Mechanism Networks (CMNs).</li>\n    <li>The model is designed to focus on understanding data relationships rather than just making predictions.</li>\n    <li>It is pretrained using synthetic datasets created from structural causal models to cover various data structures and processes.</li>\n    <li>LimiX-2 outperforms existing models in specific tasks and is better at understanding causal relationships in data.</li>\n    <li>The model's design allows it to effectively encode and recover direct causal connections in the data.</li>\n</ul>"}, "publishedAt": "2026-09-14T20:00:00.000Z", "title": "LimiX-2: A Contextual Mechanism Network Towards General Structured-Data Intelligence", "summary": "We introduce LimiX-2, a new model in the LimiX family, developed through model and data scaling guided by our previously established scaling laws. LimiX-2 adopts the Contextual Mechanism Networks (CMNs) paradigm and is pretrained with Context-Conditional Masked Modeling (CCMM). CMNs shifts the organizing principle of in-context learning from target-centric prediction to mechanism-oriented joint modeling. Rather than centering the network on the p(y mid x, D_{context}) objective of conventional tabular PFNs, it is designed around learning p(x, y mid D_{context}), a context-dependent representation of the joint structure underlying data generation. Pretraining uses synthetic datasets generated by structural causal models (SCMs) spanning diverse graph structures, functional mechanisms, and observation processes. Evaluations on TabArena, TALENT, and BCCO show that LimiX-2 outperforms current dataset-specific models and tabular foundation models. Beyond predictive performance, the CMN paradigm also promotes causal awareness in LimiX-2: its feature attention encodes direct causal relationships, enabling accurate causal skeleton recovery.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63440a1be01a38440ef25daa/82Td574Ji7ShkZWIF58uf.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.17488.png", "numComments": 4, "submittedBy": {"_id": "63440a1be01a38440ef25daa", "avatarUrl": "/avatars/622e8ca69f1867be7932d03b91eaf6e7.svg", "fullname": "Xingxuan Zhang", "name": "xuange", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "6911d3dc57d393d3cfe628bf", "name": "stable-ai", "fullname": "Stable AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68aa772042ec888900da6a6b/ykANVIVEnhVZ1fdsEz7BQ.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.31620", "authors": [{"_id": "6ab9c761356575bf2ab7a854", "user": {"_id": "667230de876f9f27d6b097ea", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/667230de876f9f27d6b097ea/hhz4nfTUdAAMIPXw3A342.jpeg", "isPro": false, "fullname": "Hongyang Du", "user": "Hongyang-Du", "type": "user", "name": "Hongyang-Du"}, "name": "Hongyang Du", "status": "claimed_verified", "statusLastChangedAt": "2026-09-28T14:59:32.932Z", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a855", "name": "Yunfei Xie", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a856", "name": "Junjie Ye", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a857", "name": "Jiawei Yang", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a858", "name": "Xiaoyan Cong", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a859", "name": "Haodong Zhang", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85a", "name": "Yongchao Huang", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85b", "user": {"_id": "6530b49cb50285938b63d6a5", "avatarUrl": "/avatars/fc5e6b52693b35ae0948265686b56b05.svg", "isPro": false, "fullname": "Haiyu Wu", "user": "BooBooWu", "type": "user", "name": "BooBooWu"}, "name": "Haiyu Wu", "status": "claimed_verified", "statusLastChangedAt": "2026-09-28T08:45:05.268Z", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85c", "name": "Zongxia Li", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85d", "name": "Shihang Gui", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85e", "name": "Dawei Liu", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a85f", "name": "Runhao Li", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a860", "name": "Jingcheng Ni", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a861", "name": "Chen Wei", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a862", "name": "Randall Balestriero", "hidden": false}, {"_id": "6ab9c761356575bf2ab7a863", "name": "Yue Wang", "hidden": false}], "publishedAt": "2026-09-25T00:00:00.000Z", "submittedOnDailyAt": "2026-09-28T00:00:00.000Z", "title": "FuseReg: Regularizing Layer Fusion Mitigates the Reconstruction-Generation Gap in Representation Autoencoders", "submittedOnDailyBy": {"_id": "667230de876f9f27d6b097ea", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/667230de876f9f27d6b097ea/hhz4nfTUdAAMIPXw3A342.jpeg", "isPro": false, "fullname": "Hongyang Du", "user": "Hongyang-Du", "type": "user", "name": "Hongyang-Du"}, "summary": "Representation autoencoders (RAEs) reuse features from a pretrained visual encoder as reconstruction and diffusion latents, integrating strong visual representations into image generation. However, RAEs still need to decide which encoder layers form the shared latent space for the generator and pixel decoder. This choice involves a trade-off. Shallower layers tend to preserve fine pixel details better, while deeper layers tend to yield better generation metrics. A fixed heuristic layer fusion therefore couples two stages that benefit from different information. We introduce FuseReg, which replaces heuristic feature selection with training over random subsets of encoder layers. We theoretically analyze the underlying mechanism: subset sampling explicitly penalizes sensitivity to cross-layer disagreement. On ImageNet-256 with DINOv3-L, a single FuseReg decoder reconstructs from full, sparse, and single-layer fusions without retraining, achieving higher PSNR than decoders specialized to fixed fusions. This flexibility also benefits generation: decoder replacement alone reduces unguided gFID by 27% with an unchanged RAEv2 DiT-XL generator. The same regularization principle extends to diffusion training, with joint regularization of both stages reducing unguided gFID by 29% on DiT-Base. These results show that training downstream models for layer-fusion robustness narrows the reconstruction-generation gap without modifying the pretrained encoder.", "upvotes": 116, "discussionId": "6ab9c762356575bf2ab7a864", "projectPage": "https://hongyang-du.github.io/FuseReg/", "githubRepo": "https://github.com/Hongyang-Du/FuseReg", "githubRepoAddedBy": "user", "githubStars": 13, "organization": {"_id": "66eb6cd5d10fdbc179fa6a20", "name": "USC-PSI-Lab", "fullname": "USC Physical Superintelligence (PSI) Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6552aa185138c382d3228761/vXpouU0ojcyCalAB0bgde.png"}, "summary_zh": "<ul>\n    <li>\u8868\u793a\u81ea\u7f16\u7801\u5668\uff08RAEs\uff09\u5229\u7528\u9884\u8bad\u7ec3\u7684\u89c6\u89c9\u7f16\u7801\u5668\u7279\u5f81\u6765\u751f\u6210\u56fe\u50cf\u3002</li>\n    <li>\u9009\u62e9\u5171\u4eab\u6f5c\u5728\u7a7a\u95f4\u7684\u7f16\u7801\u5668\u5c42\u662f\u4e00\u4e2a\u6743\u8861\u95ee\u9898\uff1a\u6d45\u5c42\u4fdd\u7559\u7ec6\u8282\u597d\uff0c\u6df1\u5c42\u751f\u6210\u6548\u679c\u4f73\u3002</li>\n    <li>FuseReg \u901a\u8fc7\u968f\u673a\u9009\u62e9\u7f16\u7801\u5668\u5c42\u8fdb\u884c\u8bad\u7ec3\uff0c\u66ff\u4ee3\u4e86\u56fa\u5b9a\u7684\u7279\u5f81\u9009\u62e9\u65b9\u6cd5\u3002</li>\n    <li>FuseReg \u5728 ImageNet-256 \u4e0a\u8868\u73b0\u51fa\u6bd4\u56fa\u5b9a\u878d\u5408\u7684\u89e3\u7801\u5668\u66f4\u9ad8\u7684 PSNR \u503c\u3002</li>\n    <li>\u8fd9\u79cd\u65b9\u6cd5\u8fd8\u63d0\u9ad8\u4e86\u751f\u6210\u8d28\u91cf\uff0c\u51cf\u5c11\u4e86\u65e0\u6307\u5bfc\u751f\u6210\u7684 gFID \u503c\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Representation autoencoders (RAEs) use features from a pretrained visual encoder to improve image generation.</li>\n    <li>Choosing which layers of the encoder to use is important; shallower layers keep details while deeper layers improve overall quality.</li>\n    <li>FuseReg is a new method that trains over random subsets of encoder layers instead of using fixed choices, making it more flexible.</li>\n    <li>Using FuseReg, a single decoder can reconstruct images better than specialized decoders, improving image quality metrics.</li>\n    <li>This method also helps in image generation and diffusion training, significantly reducing certain quality metrics without changing the original encoder.</li>\n</ul>"}, "publishedAt": "2026-09-24T20:00:00.000Z", "title": "FuseReg: Regularizing Layer Fusion Mitigates the Reconstruction-Generation Gap in Representation Autoencoders", "summary": "Representation autoencoders (RAEs) reuse features from a pretrained visual encoder as reconstruction and diffusion latents, integrating strong visual representations into image generation. However, RAEs still need to decide which encoder layers form the shared latent space for the generator and pixel decoder. This choice involves a trade-off. Shallower layers tend to preserve fine pixel details better, while deeper layers tend to yield better generation metrics. A fixed heuristic layer fusion therefore couples two stages that benefit from different information. We introduce FuseReg, which replaces heuristic feature selection with training over random subsets of encoder layers. We theoretically analyze the underlying mechanism: subset sampling explicitly penalizes sensitivity to cross-layer disagreement. On ImageNet-256 with DINOv3-L, a single FuseReg decoder reconstructs from full, sparse, and single-layer fusions without retraining, achieving higher PSNR than decoders specialized to fixed fusions. This flexibility also benefits generation: decoder replacement alone reduces unguided gFID by 27% with an unchanged RAEv2 DiT-XL generator. The same regularization principle extends to diffusion training, with joint regularization of both stages reducing unguided gFID by 29% on DiT-Base. These results show that training downstream models for layer-fusion robustness narrows the reconstruction-generation gap without modifying the pretrained encoder.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.31620.png", "numComments": 3, "submittedBy": {"_id": "667230de876f9f27d6b097ea", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/667230de876f9f27d6b097ea/hhz4nfTUdAAMIPXw3A342.jpeg", "fullname": "Hongyang Du", "name": "Hongyang-Du", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "66eb6cd5d10fdbc179fa6a20", "name": "USC-PSI-Lab", "fullname": "USC Physical Superintelligence (PSI) Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6552aa185138c382d3228761/vXpouU0ojcyCalAB0bgde.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.19134", "authors": [{"_id": "6aab567a1d9cc4dec7962470", "name": "Hejia Geng", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962471", "name": "Zesen Huang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962472", "name": "Haoyang Li", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962473", "name": "Wenbin Li", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962474", "user": {"_id": "674d191fc406e58320e21dc0", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/674d191fc406e58320e21dc0/3WUBoDbpGxOu5-OJq0bxS.png", "isPro": false, "fullname": "Koutian Wu", "user": "ktwu01", "type": "user", "name": "ktwu01"}, "name": "Koutian Wu", "status": "claimed_verified", "statusLastChangedAt": "2026-09-18T00:45:04.765Z", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962475", "name": "Zihan Zhou", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962476", "name": "Yuanbo Pang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962477", "name": "Weihao Liu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962478", "name": "Zigong Xu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962479", "name": "Zhiping Li", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247a", "user": {"_id": "662768ede39da75ea99950a2", "avatarUrl": "/avatars/adee194925148d6a0753c064a49549c1.svg", "isPro": false, "fullname": "Zhang Zongzheng", "user": "Zzz0918", "type": "user", "name": "Zzz0918"}, "name": "Zongzheng Zhang", "status": "claimed_verified", "statusLastChangedAt": "2026-09-17T08:45:04.484Z", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247b", "name": "Chuanfei Dong", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247c", "name": "Jiankai Sun", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247d", "name": "Tianzhe Zheng", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247e", "name": "Fengyu Xie", "hidden": false}, {"_id": "6aab567a1d9cc4dec796247f", "name": "Yue Ma", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962480", "name": "Yueheng Shi", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962481", "name": "Tong Xie", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962482", "name": "Zonglin Di", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962483", "name": "Xianrong Liu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962484", "name": "Qucheng Gao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962485", "user": {"_id": "646fd64f9ba7aeaacb269cba", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/646fd64f9ba7aeaacb269cba/HJSlvkP5Crbi5CbOcFD2y.png", "isPro": false, "fullname": "Yimin Liu", "user": "yiminn", "type": "user", "name": "yiminn"}, "name": "Yimin Liu", "status": "claimed_verified", "statusLastChangedAt": "2026-09-17T08:45:04.493Z", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962486", "name": "Jiaming Pan", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962487", "name": "Sheng Huang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962488", "name": "Xiao-Han Ma", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962489", "name": "Lanqing Yuan", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248a", "name": "Zhenlin Zhu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248b", "name": "Ziang Liu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248c", "name": "Ziyang Xu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248d", "name": "Junkai Wang", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248e", "name": "Kangkai Liang", "hidden": false}, {"_id": "6aab567a1d9cc4dec796248f", "name": "Jiayi Xian", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962490", "name": "Zehong Zhao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962491", "name": "Liuwei Xu", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962492", "name": "Jingxu Xie", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962493", "name": "Peijin Zhang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962494", "name": "Qiang Gao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962495", "name": "Chengyi Xing", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962496", "name": "Zhe Zhao", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962497", "name": "Xi Wang", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962498", "name": "Yaopeng Xing", "hidden": false}, {"_id": "6aab567a1d9cc4dec7962499", "name": "Xing Meng", "hidden": false}, {"_id": "6aab567a1d9cc4dec796249a", "name": "Zhenfei Yin", "hidden": false}, {"_id": "6aab567a1d9cc4dec796249b", "name": "Yingcheng Wu", "hidden": false}, {"_id": "6aab567a1d9cc4dec796249c", "name": "Ling Yang", "hidden": false}], "publishedAt": "2026-09-16T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "ScienceIDE: Turning World's Scientific Codebase into Agent Learnable Environments", "submittedOnDailyBy": {"_id": "64fde4e252e82dd432b74ce9", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/-CQZbBP7FsPPyawYrsi4z.jpeg", "isPro": false, "fullname": "Ling Yang", "user": "Lingaaaaaaa", "type": "user", "name": "Lingaaaaaaa"}, "summary": "Scientific code repositories encode decades of human knowledge in executable models, methods, and tools. Yet fragmented toolchains, implicit domain conventions, and specialized correctness criteria make this knowledge difficult to convert into reliable learning experience-a challenge we call the scientific experience bottleneck. We introduce ScienceIDE, infrastructure for turning the world's scientific code into programmable environments for scientific agents. Guided by expert-defined scientific cases and acceptance criteria, agents transform repositories into executable environments that support task generation, execution, and scientific verification. These environments provide a shared foundation for supervised fine-tuning, reinforcement learning, and evaluation. Using verified interaction trajectories, we train PhAI-IDE-72B, PhAI-IDE-9B, and PhAI-IDE-4B. The model family shows gains in held-out scientific-code repair and across selected general-purpose benchmarks in code, reasoning, and knowledge, providing evidence of positive transfer from scientific experience to broader capabilities. ScienceIDE lays the foundation for an integrated workspace for agent learning and scientific practice, making humanity's scientific software a shared substrate for developing scientific intelligence. Code: https://github.com/aitofound/ScienceIDE", "upvotes": 71, "discussionId": "6aab567a1d9cc4dec796249d", "projectPage": "https://huggingface.co/collections/AItonomy/scienceide-model-series", "githubRepo": "https://github.com/aitofound/ScienceIDE", "githubRepoAddedBy": "user", "githubStars": 27, "organization": {"_id": "6aab7c097e5721f5e005ff0a", "name": "PhAILabs", "fullname": "PhAI Labs", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/5-hyYwAMko5JVJz5qWxEj.png"}, "summary_zh": "<ul>\n    <li>\u79d1\u5b66\u4ee3\u7801\u5e93\u5305\u542b\u4e86\u51e0\u5341\u5e74\u7684\u77e5\u8bc6\uff0c\u4f46\u7531\u4e8e\u5de5\u5177\u94fe\u5206\u6563\u548c\u5404\u79cd\u6807\u51c6\uff0c\u8f6c\u6362\u8fd9\u4e9b\u77e5\u8bc6\u4e3a\u53ef\u9760\u7684\u5b66\u4e60\u4f53\u9a8c\u5f88\u56f0\u96be\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86ScienceIDE\uff0c\u8fd9\u662f\u4e00\u79cd\u57fa\u7840\u8bbe\u65bd\uff0c\u53ef\u4ee5\u5c06\u79d1\u5b66\u4ee3\u7801\u8f6c\u53d8\u4e3a\u53ef\u7f16\u7a0b\u7684\u79d1\u5b66\u73af\u5883\u3002</li>\n    <li>\u8fd9\u4e9b\u73af\u5883\u901a\u8fc7\u4e13\u5bb6\u5b9a\u4e49\u7684\u79d1\u5b66\u6848\u4f8b\u548c\u6807\u51c6\uff0c\u652f\u6301\u4efb\u52a1\u751f\u6210\u3001\u6267\u884c\u548c\u79d1\u5b66\u9a8c\u8bc1\u3002</li>\n    <li>\u6211\u4eec\u8bad\u7ec3\u4e86\u591a\u4e2a\u6a21\u578b\uff08PhAI-IDE-72B\u3001PhAI-IDE-9B\u548cPhAI-IDE-4B\uff09\uff0c\u663e\u793a\u51fa\u5728\u79d1\u5b66\u4ee3\u7801\u4fee\u590d\u548c\u5176\u4ed6\u901a\u7528\u57fa\u51c6\u4e0a\u7684\u63d0\u5347\u3002</li>\n    <li>ScienceIDE\u4e3a\u4ee3\u7406\u5b66\u4e60\u548c\u79d1\u5b66\u5b9e\u8df5\u63d0\u4f9b\u4e86\u4e00\u4e2a\u96c6\u6210\u5de5\u4f5c\u7a7a\u95f4\uff0c\u4f7f\u4eba\u7c7b\u7684\u79d1\u5b66\u8f6f\u4ef6\u6210\u4e3a\u5f00\u53d1\u79d1\u5b66\u667a\u80fd\u7684\u5171\u540c\u57fa\u7840\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Scientific code repositories hold valuable knowledge but are hard to use because of different tools and rules.</li>\n    <li>ScienceIDE is a new system that helps convert scientific code into useful environments for learning and experimentation.</li>\n    <li>It uses expert guidance to create environments that help with tasks like training AI and verifying scientific work.</li>\n    <li>The system has been used to train AI models that show improvement in both repairing scientific code and general coding tasks.</li>\n    <li>ScienceIDE aims to create a collaborative space for advancing scientific knowledge and AI capabilities.</li>\n</ul>"}, "publishedAt": "2026-09-15T20:00:00.000Z", "title": "ScienceIDE: Turning World's Scientific Codebase into Agent Learnable Environments", "summary": "Scientific code repositories encode decades of human knowledge in executable models, methods, and tools. Yet fragmented toolchains, implicit domain conventions, and specialized correctness criteria make this knowledge difficult to convert into reliable learning experience-a challenge we call the scientific experience bottleneck. We introduce ScienceIDE, infrastructure for turning the world's scientific code into programmable environments for scientific agents. Guided by expert-defined scientific cases and acceptance criteria, agents transform repositories into executable environments that support task generation, execution, and scientific verification. These environments provide a shared foundation for supervised fine-tuning, reinforcement learning, and evaluation. Using verified interaction trajectories, we train PhAI-IDE-72B, PhAI-IDE-9B, and PhAI-IDE-4B. The model family shows gains in held-out scientific-code repair and across selected general-purpose benchmarks in code, reasoning, and knowledge, providing evidence of positive transfer from scientific experience to broader capabilities. ScienceIDE lays the foundation for an integrated workspace for agent learning and scientific practice, making humanity's scientific software a shared substrate for developing scientific intelligence. Code: https://github.com/aitofound/ScienceIDE", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.19134.png", "numComments": 3, "submittedBy": {"_id": "64fde4e252e82dd432b74ce9", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/-CQZbBP7FsPPyawYrsi4z.jpeg", "fullname": "Ling Yang", "name": "Lingaaaaaaa", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 18, "isUserFollowing": false}, "organization": {"_id": "6aab7c097e5721f5e005ff0a", "name": "PhAILabs", "fullname": "PhAI Labs", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64fde4e252e82dd432b74ce9/5-hyYwAMko5JVJz5qWxEj.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.06100", "authors": [{"_id": "6ac4b70a9eb4ee6bd77a9766", "user": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "isPro": true, "fullname": "Long", "user": "Quanyu001", "type": "user", "name": "Quanyu001"}, "name": "Quanyu Long", "status": "claimed_verified", "statusLastChangedAt": "2026-10-06T09:20:03.874Z", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9767", "user": {"_id": "64969bccf590e76c93938582", "avatarUrl": "/avatars/363598cba9e9496852e60144694b2f1c.svg", "isPro": false, "fullname": "shawncchen", "user": "chrisCCC", "type": "user", "name": "chrisCCC"}, "name": "Xiao Chen", "status": "claimed_verified", "statusLastChangedAt": "2026-10-07T08:07:49.844Z", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9768", "name": "Jianda Chen", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9769", "name": "Haozhen Zhang", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976a", "name": "Qisheng Hu", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976b", "name": "Jianzhu Bao", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976c", "name": "Wenya Wang", "hidden": false}], "publishedAt": "2026-10-05T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "From Traces to Agentic Worlds: Agentic Language World Models for Interactive Environment Simulation", "submittedOnDailyBy": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "isPro": true, "fullname": "Long", "user": "Quanyu001", "type": "user", "name": "Quanyu001"}, "summary": "Realistic environment replicas are increasingly valuable for training and evaluating LLM agents, yet the original systems may be inaccessible or impractical to reproduce. We explore agentic language world modeling: rather than rebuilding an executable environment, a world model agent serves as the environment for a task agent and supports faithful and stateful simulation. We instantiate this paradigm with Trace2Env, a learning-free framework for settings where the original system is unavailable but historical interaction traces remain accessible. Trace2Env reconstructs these traces into a reusable environment worldbook containing environment schemas, grounded evidence, and induced behavioral knowledge. At runtime, the world model agent actively consults the worldbook together with persistent episodic state to infer each action's observation and lasting state effects. Across nine environments, Trace2Env improves both next-observation fidelity and long-horizon interaction consistency over conventional prompt-based LWMs. In multi-turn interaction, task agent actions generated against Trace2Env remain valid more often when replayed in the real environment, indicating that its simulated dynamics better preserve the consequences of earlier actions across successive turns. These results establish agentic language world modeling as an alternative direction for building realistic environment replicas without reconstructing the original executable system.", "upvotes": 64, "discussionId": "6ac4b70a9eb4ee6bd77a976d", "projectPage": "https://quanyulong.net/trace2env/", "githubRepo": "https://github.com/ruyue0001/trace2env", "githubRepoAddedBy": "user", "githubStars": 17, "organization": {"_id": "6371470aafbe42caa5a76208", "name": "nanyang-technological-university-singapore", "fullname": "Nanyang Technological University Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/637146c5afbe42caa5a75e1b/sZyHSA1AQaAS4nrGan682.png"}, "summary_zh": "<ul>\n    <li>\u771f\u5b9e\u73af\u5883\u7684\u590d\u5236\u54c1\u5bf9\u8bad\u7ec3\u548c\u8bc4\u4f30\u5927\u578b\u8bed\u8a00\u6a21\u578b\uff08LLM\uff09\u4ee3\u7406\u8d8a\u6765\u8d8a\u91cd\u8981\uff0c\u4f46\u539f\u59cb\u7cfb\u7edf\u53ef\u80fd\u65e0\u6cd5\u8bbf\u95ee\u6216\u91cd\u73b0\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u65b9\u6cd5\uff0c\u4f7f\u7528\u4e16\u754c\u6a21\u578b\u4ee3\u7406\u6765\u6a21\u62df\u4efb\u52a1\u73af\u5883\uff0c\u800c\u4e0d\u662f\u91cd\u5efa\u53ef\u6267\u884c\u73af\u5883\u3002</li>\n    <li>Trace2Env\u662f\u4e00\u4e2a\u65e0\u5b66\u4e60\u7684\u6846\u67b6\uff0c\u53ef\u4ee5\u5728\u6ca1\u6709\u539f\u59cb\u7cfb\u7edf\u7684\u60c5\u51b5\u4e0b\uff0c\u4f7f\u7528\u5386\u53f2\u4ea4\u4e92\u6570\u636e\u91cd\u5efa\u73af\u5883\u3002</li>\n    <li>\u5b83\u751f\u6210\u4e00\u4e2a\u73af\u5883\u4e16\u754c\u4e66\uff0c\u5305\u542b\u73af\u5883\u67b6\u6784\u3001\u8bc1\u636e\u548c\u884c\u4e3a\u77e5\u8bc6\uff0c\u7528\u4e8e\u5b9e\u65f6\u63a8\u65ad\u884c\u52a8\u7684\u89c2\u5bdf\u548c\u72b6\u6001\u6548\u679c\u3002</li>\n    <li>\u5728\u4e5d\u4e2a\u73af\u5883\u4e2d\uff0cTrace2Env\u63d0\u9ad8\u4e86\u89c2\u5bdf\u51c6\u786e\u6027\u548c\u4ea4\u4e92\u4e00\u81f4\u6027\uff0c\u6a21\u62df\u52a8\u6001\u66f4\u597d\u5730\u4fdd\u7559\u4e86\u65e9\u671f\u884c\u52a8\u7684\u540e\u679c\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Realistic environment replicas are useful for training language model agents, but recreating original systems can be difficult or impossible.</li>\n    <li>The study introduces \"agentic language world modeling,\" where a world model agent acts as a simulated environment for a task agent.</li>\n    <li>Trace2Env is a framework that uses historical interaction data to create a reusable environment model, called a worldbook.</li>\n    <li>It improves the accuracy of next observations and maintains better consistency in longer interactions compared to traditional methods.</li>\n    <li>Task agent actions generated from Trace2Env are more likely to remain valid when tested in real environments, showing its effectiveness in simulating realistic dynamics.</li>\n</ul>"}, "publishedAt": "2026-10-04T20:00:00.000Z", "title": "From Traces to Agentic Worlds: Agentic Language World Models for Interactive Environment Simulation", "summary": "Realistic environment replicas are increasingly valuable for training and evaluating LLM agents, yet the original systems may be inaccessible or impractical to reproduce. We explore agentic language world modeling: rather than rebuilding an executable environment, a world model agent serves as the environment for a task agent and supports faithful and stateful simulation. We instantiate this paradigm with Trace2Env, a learning-free framework for settings where the original system is unavailable but historical interaction traces remain accessible. Trace2Env reconstructs these traces into a reusable environment worldbook containing environment schemas, grounded evidence, and induced behavioral knowledge. At runtime, the world model agent actively consults the worldbook together with persistent episodic state to infer each action's observation and lasting state effects. Across nine environments, Trace2Env improves both next-observation fidelity and long-horizon interaction consistency over conventional prompt-based LWMs. In multi-turn interaction, task agent actions generated against Trace2Env remain valid more often when replayed in the real environment, indicating that its simulated dynamics better preserve the consequences of earlier actions across successive turns. These results establish agentic language world modeling as an alternative direction for building realistic environment replicas without reconstructing the original executable system.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.06100.png", "numComments": 1, "submittedBy": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "fullname": "Long", "name": "Quanyu001", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6371470aafbe42caa5a76208", "name": "nanyang-technological-university-singapore", "fullname": "Nanyang Technological University Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/637146c5afbe42caa5a75e1b/sZyHSA1AQaAS4nrGan682.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2609.18708", "authors": [{"_id": "6aab88ba1d9cc4dec79625a4", "user": {"_id": "6785e04ce63a669874f166e9", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6785e04ce63a669874f166e9/xSUEAmRm-KadDNOYiOZew.jpeg", "isPro": false, "fullname": "dodojorid", "user": "yizhuoli", "type": "user", "name": "yizhuoli"}, "name": "Yizhuo Li", "status": "claimed_verified", "statusLastChangedAt": "2026-09-17T09:09:42.043Z", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a5", "name": "Jianhao Yan", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a6", "name": "Yun Luo", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a7", "name": "Zhi Wang", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a8", "name": "Futing Wang", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625a9", "name": "Rong-Xi Tan", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625aa", "name": "Kanghui Tian", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ab", "name": "Ganqu Cui", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ac", "name": "Ning Ding", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ad", "name": "Peilin Zhao", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625ae", "name": "Yafu Li", "hidden": false}, {"_id": "6aab88ba1d9cc4dec79625af", "name": "Yu Cheng", "hidden": false}], "publishedAt": "2026-09-16T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "Rethinking Critic Learning in PPO: Understanding and Mitigating Value Flattening", "submittedOnDailyBy": {"_id": "644915c5e87a77e872e61350", "avatarUrl": "/avatars/46ba7bdf04ad4c1b0ad79155010dc684.svg", "isPro": false, "fullname": "Luo", "user": "ramiroluo", "type": "user", "name": "ramiroluo"}, "summary": "In reinforcement learning for large language models, Proximal Policy Optimization (PPO) commonly uses a critic to estimate state values and reduce the variance of policy updates. However, we uncover a systematic failure mode in PPO critics, which we call Value Flattening: state values, estimated from multiple Monte Carlo continuations, change sharply across intermediate states while critic predictions remain comparatively flat. We further observe this phenomenon in a controlled FrozenLake environment and find that it becomes more pronounced as the state space grows. Our theoretical and empirical analyses relate Value Flattening to an implicit variance penalty in the critic loss and redundant updates from temporally correlated states with similar gradients. Motivated by these findings, we introduce SParse Proximal Policy Optimization (SP^3O), which applies the value loss to only a few well-separated states in each response to mitigate both effects. Experiments on Qwen3-Base show that SP^3O with only three states supervised per response can mitigate Value Flattening and consistently improve the learned policy across model sizes and evaluation suites. Together, our results identify Value Flattening as an important yet overlooked failure mode of critic learning in standard PPO and show that a simple sparse supervision strategy can mitigate it.", "upvotes": 60, "discussionId": "6aab88ba1d9cc4dec79625b0", "projectPage": "https://dodojordi.github.io/SP3O/", "githubRepo": "https://github.com/Dodojordi/SP3O", "githubRepoAddedBy": "user", "githubStars": 15, "organization": {"_id": "6a4fb75a1c66dbf208e7ddb6", "name": "Shanghai-AI-Laboratory", "fullname": "Shanghai AI Laboratory", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65cd955637be1841d0b75397/Rao_Kq6NMtTVfSqLUIR4k.webp"}, "summary_zh": "<ul>\n    <li>\u5728\u5f3a\u5316\u5b66\u4e60\u4e2d\uff0cPPO\u7b97\u6cd5\u4f7f\u7528\u8bc4\u4ef7\u5668\u6765\u4f30\u8ba1\u72b6\u6001\u503c\u5e76\u51cf\u5c11\u7b56\u7565\u66f4\u65b0\u7684\u65b9\u5dee\u3002</li>\n    <li>\u6211\u4eec\u53d1\u73b0PPO\u8bc4\u4ef7\u5668\u5b58\u5728\u4e00\u79cd\u7cfb\u7edf\u6027\u5931\u8d25\u6a21\u5f0f\uff0c\u79f0\u4e3a\u201c\u503c\u5e73\u5766\u5316\u201d\uff0c\u5373\u591a\u4e2a\u72b6\u6001\u7684\u4f30\u8ba1\u503c\u53d8\u5316\u5267\u70c8\uff0c\u4f46\u8bc4\u4ef7\u5668\u7684\u9884\u6d4b\u5374\u76f8\u5bf9\u5e73\u5766\u3002</li>\n    <li>\u5728\u63a7\u5236\u73af\u5883\u4e2d\uff08\u5982FrozenLake\uff09\uff0c\u968f\u7740\u72b6\u6001\u7a7a\u95f4\u7684\u589e\u5927\uff0c\u8fd9\u79cd\u503c\u5e73\u5766\u5316\u73b0\u8c61\u66f4\u52a0\u660e\u663e\u3002</li>\n    <li>\u4e3a\u4e86\u5e94\u5bf9\u8fd9\u4e00\u95ee\u9898\uff0c\u6211\u4eec\u63d0\u51fa\u4e86\u7a00\u758f\u8fd1\u7aef\u7b56\u7565\u4f18\u5316\uff08SP^3O\uff09\uff0c\u53ea\u5bf9\u5c11\u91cf\u5206\u79bb\u7684\u72b6\u6001\u5e94\u7528\u503c\u635f\u5931\uff0c\u4ece\u800c\u51cf\u8f7b\u4e86\u503c\u5e73\u5766\u5316\u7684\u5f71\u54cd\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0cSP^3O\u80fd\u6709\u6548\u51cf\u8f7b\u503c\u5e73\u5766\u5316\u5e76\u5728\u591a\u4e2a\u6a21\u578b\u548c\u8bc4\u4f30\u4efb\u52a1\u4e2d\u6301\u7eed\u6539\u5584\u5b66\u4e60\u7b56\u7565\u3002</li>\n</ul>", "summary_simple": "<ul>\n  <li>Proximal Policy Optimization (PPO) uses a critic to help improve learning in reinforcement learning for language models.</li>\n  <li>Researchers found a problem called Value Flattening, where estimated state values change a lot, but the critic's predictions do not.</li>\n  <li>This issue becomes worse as the number of states increases, and it is linked to how the critic's loss is calculated.</li>\n  <li>To address this, they created a new method called SParse Proximal Policy Optimization (SP^3O), which focuses on only a few important states during training.</li>\n  <li>Experiments showed that SP^3O helps reduce Value Flattening and improves the learning of the model's policy.</li>\n</ul>"}, "publishedAt": "2026-09-15T20:00:00.000Z", "title": "Rethinking Critic Learning in PPO: Understanding and Mitigating Value Flattening", "summary": "In reinforcement learning for large language models, Proximal Policy Optimization (PPO) commonly uses a critic to estimate state values and reduce the variance of policy updates. However, we uncover a systematic failure mode in PPO critics, which we call Value Flattening: state values, estimated from multiple Monte Carlo continuations, change sharply across intermediate states while critic predictions remain comparatively flat. We further observe this phenomenon in a controlled FrozenLake environment and find that it becomes more pronounced as the state space grows. Our theoretical and empirical analyses relate Value Flattening to an implicit variance penalty in the critic loss and redundant updates from temporally correlated states with similar gradients. Motivated by these findings, we introduce SParse Proximal Policy Optimization (SP^3O), which applies the value loss to only a few well-separated states in each response to mitigate both effects. Experiments on Qwen3-Base show that SP^3O with only three states supervised per response can mitigate Value Flattening and consistently improve the learned policy across model sizes and evaluation suites. Together, our results identify Value Flattening as an important yet overlooked failure mode of critic learning in standard PPO and show that a simple sparse supervision strategy can mitigate it.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.18708.png", "numComments": 2, "submittedBy": {"_id": "644915c5e87a77e872e61350", "avatarUrl": "/avatars/46ba7bdf04ad4c1b0ad79155010dc684.svg", "fullname": "Luo", "name": "ramiroluo", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "6a4fb75a1c66dbf208e7ddb6", "name": "Shanghai-AI-Laboratory", "fullname": "Shanghai AI Laboratory", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65cd955637be1841d0b75397/Rao_Kq6NMtTVfSqLUIR4k.webp"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10528", "authors": [{"_id": "6ac6fb044eb8005165aed391", "name": "Wei Huang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed392", "name": "Bohan Zhang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed393", "name": "Chenzhi Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed394", "name": "Isabella Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed395", "name": "Shuai Yang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed396", "name": "Weian Mao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed397", "name": "Luozhou Wang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed398", "name": "Yicheng Xiao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed399", "name": "Weifeng Lin", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39a", "name": "Qixin Hu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39b", "name": "Bryan Chu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39c", "name": "Sifei Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39d", "name": "Linxi Fan", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39e", "name": "Xiaojuan Qi", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39f", "name": "Song Han", "hidden": false}, {"_id": "6ac6fb044eb8005165aed3a0", "name": "Yukang Chen", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "submittedOnDailyBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "isPro": false, "fullname": "Wei Huang", "user": "AaronHuangWei", "type": "user", "name": "AaronHuangWei"}, "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "upvotes": 54, "discussionId": "6ac6fb044eb8005165aed3a1", "projectPage": "https://nvlabs.github.io/LongLive/Long-WAM/", "githubRepo": "https://github.com/NVlabs/LongLive", "githubRepoAddedBy": "user", "githubStars": 2662, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "summary_zh": "<ul>\n    <li>Long-WAM\u662f\u4e00\u79cd\u673a\u5668\u4eba\u63a7\u5236\u6a21\u578b\uff0c\u80fd\u591f\u5728\u5b9e\u65f6\u63a7\u5236\u7684\u9650\u5236\u4e0b\u4f7f\u7528\u66f4\u957f\u7684\u89c6\u89c9\u5386\u53f2\u6765\u63a8\u65ad\u52a8\u4f5c\u548c\u4efb\u52a1\u8fdb\u5c55\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\uff0c\u7ecf\u8fc7\u81ea\u56de\u5f52\u9884\u8bad\u7ec3\u7684\u89c6\u9891\u57fa\u7840\uff0c\u4f7f\u7528\u8f83\u957f\u7684\u5386\u53f2\u6570\u636e\u80fd\u663e\u8457\u63d0\u9ad8\u6210\u529f\u7387\u3002</li>\n    <li>\u5728RoboCasa GR-1\u4e0a\uff0c\u589e\u52a0\u4e0a\u4e0b\u6587\u65f6\u95f4\u4ece0\u79d2\u523019.2\u79d2\uff0c\u6210\u529f\u7387\u4ece63.3%\u63d0\u9ad8\u523078.7%\u3002</li>\n    <li>Long-WAM\u5728\u591a\u4e2a\u4efb\u52a1\u4e0a\u8868\u73b0\u6700\u597d\uff0c\u5305\u62ecLIBERO-Long\u3001RoboTwin 2.0\u548cDOMINO\u3002</li>\n    <li>\u8be5\u6a21\u578b\u80fd\u591f\u5728\u591a\u79cd\u786c\u4ef6\u4e0a\u5b9e\u65f6\u90e8\u7f72\uff0c\u5e76\u652f\u6301\u52a8\u6001\u548c\u957f\u671f\u64cd\u4f5c\uff0c\u598295%\u7684\u52a8\u6001\u676f\u5b50\u53e0\u653e\u6210\u529f\u7387\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Long-WAM is a new system for controlling robots in real-time by using historical visual data to improve task performance.</li>\n    <li>Having more visual history helps robots perform better, especially when the foundational video data is pre-trained effectively.</li>\n    <li>Tests showed that increasing the context history from 0 to 19.2 seconds improved success rates from 63.3% to 78.7% on the RoboCasa GR-1 robot.</li>\n    <li>Long-WAM achieved top results compared to other methods on various robotic tasks, demonstrating its effectiveness.</li>\n    <li>The system is designed for real-time use on advanced hardware and can handle complex tasks, such as dynamic cup stacking with a 95% success rate.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10528.png", "numComments": 1, "submittedBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "fullname": "Wei Huang", "name": "AaronHuangWei", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 19, "isUserFollowing": false}, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.04299", "authors": [{"_id": "6ac445589eb4ee6bd77a9345", "name": "Jinyuan Li", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9346", "name": "Chengsong Huang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9347", "name": "Langlin Huang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9348", "name": "Donghong Cai", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9349", "name": "Shiping Gao", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a934a", "name": "Yuyi Yang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a934b", "name": "Jiaxin Huang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/64fc20d899123d7698a30e61/jETbBtAg6-jnVU4RPRvZb.mp4"], "publishedAt": "2026-10-03T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Questioning the Questions: Sustaining Self-Evolution in Reasoning Models", "submittedOnDailyBy": {"_id": "64fc20d899123d7698a30e61", "avatarUrl": "/avatars/9231982cf70a0689f50accedf1004702.svg", "isPro": false, "fullname": "Jinyuan Li", "user": "jinyuan222", "type": "user", "name": "jinyuan222"}, "summary": "Self-evolving reasoning models learn from their own generated questions, yet repeated self-training can lead to performance collapse. In this paper, we investigate why performance deteriorates over successive rounds and how to sustain self-evolution. Our analysis identifies two recurring quality problems in self-generated questions: invalid questions and repeated variants of the same mathematical questions. First, invalid questions become more prevalent across rounds, and answer-consistency filtering further increases their proportion in training data. Second, existing question diversity controls based on lexical similarity can miss mathematically equivalent questions expressed in different ways, which leads to question diversity collapse in later training rounds. Building on these findings, we introduce R-Quest, which uses question validity and novelty feedback to guide self-evolution. We first train the solver to recognize and reject invalid questions, then use its judgments to guide questioner rewards and filter solver training data. To avoid question repetition, we use a frozen base model to compare sampled question pairs and provide novelty feedback. Empirically, our method consistently achieves the highest average performance on 12 benchmarks in mathematical reasoning, general-domain reasoning, and code generation across two model families. Additionally, R-Quest maintains stable performance gains over ten rounds of self-evolution, peaking in the final round and outperforming R-Zero by 17.32 points.", "upvotes": 52, "discussionId": "6ac445589eb4ee6bd77a934c", "projectPage": "https://jinyuanli0012.github.io/R-Quest/", "githubRepo": "https://github.com/JinYuanLi0012/R-Quest", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "670035f24055c4569f7dd024", "name": "HINT-lab", "fullname": "Huang's INTelligence lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64efbf39b3610349e84db417/tbNZtAX3vJeGo2Rag_7ZN.png"}, "summary_zh": "<ul>\n    <li>\u81ea\u6211\u8fdb\u5316\u7684\u63a8\u7406\u6a21\u578b\u901a\u8fc7\u751f\u6210\u95ee\u9898\u8fdb\u884c\u5b66\u4e60\uff0c\u4f46\u591a\u6b21\u81ea\u6211\u8bad\u7ec3\u53ef\u80fd\u5bfc\u81f4\u6027\u80fd\u4e0b\u964d\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\u81ea\u751f\u6210\u95ee\u9898\u7684\u8d28\u91cf\u95ee\u9898\uff0c\u5305\u62ec\u65e0\u6548\u95ee\u9898\u548c\u91cd\u590d\u7684\u6570\u5b66\u95ee\u9898\u3002</li>\n    <li>\u65e0\u6548\u95ee\u9898\u5728\u8bad\u7ec3\u8f6e\u6570\u4e2d\u53d8\u5f97\u66f4\u4e3a\u666e\u904d\uff0c\u800c\u73b0\u6709\u7684\u591a\u6837\u6027\u63a7\u5236\u65b9\u6cd5\u65e0\u6cd5\u6709\u6548\u8bc6\u522b\u4e0d\u540c\u8868\u8ff0\u7684\u7b49\u6548\u95ee\u9898\u3002</li>\n    <li>\u63d0\u51faR-Quest\u65b9\u6cd5\uff0c\u901a\u8fc7\u6709\u6548\u6027\u548c\u65b0\u9896\u6027\u53cd\u9988\u6765\u6307\u5bfc\u81ea\u6211\u8fdb\u5316\uff0c\u5e76\u63d0\u9ad8\u95ee\u9898\u7684\u8d28\u91cf\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cR-Quest\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u6700\u4f73\uff0c\u5e76\u5728\u5341\u8f6e\u81ea\u6211\u8fdb\u5316\u4e2d\u4fdd\u6301\u7a33\u5b9a\u7684\u6027\u80fd\u63d0\u5347\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Self-evolving reasoning models can improve by learning from their own questions, but repeated training can hurt their performance.</li>\n    <li>The study finds that two main problems occur: more invalid questions and too many similar questions in later training rounds.</li>\n    <li>Invalid questions become more common over time, and current methods don\u2019t effectively manage question diversity.</li>\n    <li>The authors introduce a method called R-Quest that helps improve question quality and variety by filtering out invalid and repetitive questions.</li>\n    <li>R-Quest shows strong performance across various tasks and maintains improvements over multiple training rounds.</li>\n</ul>"}, "publishedAt": "2026-10-02T20:00:00.000Z", "title": "Questioning the Questions: Sustaining Self-Evolution in Reasoning Models", "summary": "Self-evolving reasoning models learn from their own generated questions, yet repeated self-training can lead to performance collapse. In this paper, we investigate why performance deteriorates over successive rounds and how to sustain self-evolution. Our analysis identifies two recurring quality problems in self-generated questions: invalid questions and repeated variants of the same mathematical questions. First, invalid questions become more prevalent across rounds, and answer-consistency filtering further increases their proportion in training data. Second, existing question diversity controls based on lexical similarity can miss mathematically equivalent questions expressed in different ways, which leads to question diversity collapse in later training rounds. Building on these findings, we introduce R-Quest, which uses question validity and novelty feedback to guide self-evolution. We first train the solver to recognize and reject invalid questions, then use its judgments to guide questioner rewards and filter solver training data. To avoid question repetition, we use a frozen base model to compare sampled question pairs and provide novelty feedback. Empirically, our method consistently achieves the highest average performance on 12 benchmarks in mathematical reasoning, general-domain reasoning, and code generation across two model families. Additionally, R-Quest maintains stable performance gains over ten rounds of self-evolution, peaking in the final round and outperforming R-Zero by 17.32 points.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/64fc20d899123d7698a30e61/jETbBtAg6-jnVU4RPRvZb.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.04299.png", "numComments": 1, "submittedBy": {"_id": "64fc20d899123d7698a30e61", "avatarUrl": "/avatars/9231982cf70a0689f50accedf1004702.svg", "fullname": "Jinyuan Li", "name": "jinyuan222", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "670035f24055c4569f7dd024", "name": "HINT-lab", "fullname": "Huang's INTelligence lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64efbf39b3610349e84db417/tbNZtAX3vJeGo2Rag_7ZN.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10524", "authors": [{"_id": "6ac6fef64eb8005165aed3e0", "name": "Jiyoung Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e1", "name": "Paul Hyunbin Cho", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e2", "name": "Jisu Nam", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e3", "name": "Donghoon Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e4", "name": "Hyunsung Go", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e5", "name": "Yeonkyeong Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e6", "name": "Hansaem Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e7", "name": "Seungryong Kim", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "submittedOnDailyBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "isPro": true, "fullname": "jee0", "user": "chimaharicox", "type": "user", "name": "chimaharicox"}, "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "upvotes": 51, "discussionId": "6ac6fef64eb8005165aed3e8", "projectPage": "https://cvlab-kaist.github.io/GRACE/", "githubRepo": "https://github.com/cvlab-kaist/GRACE", "githubRepoAddedBy": "user", "githubStars": 12, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u9ad8\u5ea6\u538b\u7f29\u7684\u89c6\u9891\u81ea\u7f16\u7801\u5668\u53ef\u4ee5\u52a0\u901f\u89c6\u9891\u6269\u6563\u6a21\u578b\uff0c\u56e0\u4e3aDiffusion Transformer\uff08DiT\uff09\u4f7f\u7528\u7684token\u6570\u91cf\u66f4\u5c11\u3002</li>\n    <li>\u8bad\u7ec3\u8fd9\u6837\u7684\u81ea\u7f16\u7801\u5668\u6bd4\u8f83\u56f0\u96be\uff0c\u56e0\u4e3a\u66f4\u9ad8\u7684\u538b\u7f29\u7387\u4f1a\u964d\u4f4e\u91cd\u5efa\u8d28\u91cf\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86GRACE\u6846\u67b6\uff0c\u53ef\u4ee5\u5728\u538b\u7f29\u9884\u8bad\u7ec3\u7684\u89c6\u9891\u81ea\u7f16\u7801\u5668\u65f6\u4fdd\u6301\u4e0eDiT\u7684\u517c\u5bb9\u6027\u3002</li>\n    <li>GRACE\u901a\u8fc7\u4fdd\u6301\u51bb\u7ed3\u7684\u57fa\u7840\u6f5c\u5728\u8868\u793a\u548c\u5b66\u4e60\u6b8b\u5dee\u6f5c\u5728\u8868\u793a\u6765\u4f18\u5316\u81ea\u7f16\u7801\u5668\u7684\u751f\u6210\u80fd\u529b\u3002</li>\n    <li>GRACE\u4f7fWan2.1-I2V-14B\u7684token\u6570\u91cf\u51cf\u5c11\u4e868\u500d\uff0c\u5ef6\u8fdf\u964d\u4f4e\u4e8611.1\u500d\uff0c\u540c\u65f6\u5728VBench\u4e0a\u751f\u6210\u8d28\u91cf\u4e0e\u538b\u7f29\u524d\u76f8\u5339\u914d\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Highly compressed video autoencoders can speed up video diffusion models by reducing the number of tokens needed.</li>\n    <li>Training these autoencoders is difficult because higher compression can lower video quality and slow down the process.</li>\n    <li>To solve this, the authors introduced a method called GRACE that compresses a video autoencoder while maintaining its compatibility with an existing model.</li>\n    <li>GRACE uses a two-step approach: it keeps a basic encoded version and learns additional information to improve quality, ensuring the compressed data fits with the previous model.</li>\n    <li>This method significantly reduces processing time and improves efficiency without sacrificing the quality of video generation.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10524.png", "numComments": 1, "submittedBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "fullname": "jee0", "name": "chimaharicox", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2609.37200", "authors": [{"_id": "6abf0f835ff0ac8de3b84a22", "name": "Songlin Yang", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a23", "name": "Xiaotong Zhao", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a24", "name": "Jiacheng Zhang", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a25", "name": "Zhe Wang", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a26", "name": "Toyota Li", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a27", "name": "Eric Liu", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a28", "name": "Alan Zhao", "hidden": false}, {"_id": "6abf0f835ff0ac8de3b84a29", "name": "Anyi Rao", "hidden": false}], "publishedAt": "2026-09-29T00:00:00.000Z", "submittedOnDailyAt": "2026-10-02T00:00:00.000Z", "title": "Adaptive Reward Routing: Dynamic Multi-Reward Optimization for Joint Audio-Video Diffusion via Forward-Process RL", "submittedOnDailyBy": {"_id": "66f64956ad4fe83c91776459", "avatarUrl": "/avatars/2014de658ac12413754dcf70bc34333e.svg", "isPro": false, "fullname": "Eddie", "user": "EddieYang428", "type": "user", "name": "EddieYang428"}, "summary": "Multi-reward guided reinforcement learning (i.e., RL) offers a promising way to improve joint audio-video diffusion models along several complementary objectives, including modality-specific quality, cross-modal semantic alignment, and temporal synchronization. Its effectiveness, however, depends on two quantities that change during training: where reward-driven updates should act, and how competing rewards should be combined. Existing methods tend to rely on fixed routing and reward weights, failing to track evolving model functions. To address these limitations, we propose Adaptive Reward Routing to jointly adapt update locations and reward coordination during forward-process RL (i.e., DiffusionNFT) of joint audio-video diffusion models. Our method consists of two components. (i) Cross-Modal Influence-Guided Routing (Localizing Updates): We use bidirectional cross-attention responses as an efficient proxy for evolving cross-modal influence, dynamically reweighting token-aware losses and scaling gradients across cross-modal layers without additional model interventions. (ii) Preference-Preserving Modality-Aware Reweighting (Coordinating Rewards): We preserve predefined weights as preference priors and use branch-specific reward-gradient interactions as residual corrections after warm-up. This resolves evolving conflicts without letting dominant rewards suppress weak but essential objectives. Extensive experiments demonstrate consistent improvements in modality quality, semantic consistency, and audio-video synchronization over strong RL baselines. Ablations and mechanism analyses further validate the complementary benefits of adaptive update routing and reward coordination.", "upvotes": 49, "discussionId": "6abf0f835ff0ac8de3b84a2a", "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "summary_zh": "<ul>\n    <li>\u591a\u91cd\u5956\u52b1\u5f15\u5bfc\u7684\u5f3a\u5316\u5b66\u4e60\u53ef\u4ee5\u6539\u5584\u97f3\u9891\u89c6\u9891\u6269\u6563\u6a21\u578b\u7684\u591a\u4e2a\u76ee\u6807\uff0c\u5305\u62ec\u7279\u5b9a\u6a21\u5f0f\u7684\u8d28\u91cf\u548c\u8de8\u6a21\u5f0f\u7684\u8bed\u4e49\u5bf9\u9f50\u3002</li>\n    <li>\u73b0\u6709\u65b9\u6cd5\u4f9d\u8d56\u56fa\u5b9a\u7684\u66f4\u65b0\u4f4d\u7f6e\u548c\u5956\u52b1\u6743\u91cd\uff0c\u65e0\u6cd5\u9002\u5e94\u6a21\u578b\u529f\u80fd\u7684\u53d8\u5316\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u81ea\u9002\u5e94\u5956\u52b1\u8def\u7531\uff0c\u52a8\u6001\u8c03\u6574\u66f4\u65b0\u4f4d\u7f6e\u548c\u5956\u52b1\u534f\u8c03\uff0c\u63d0\u5347\u6a21\u578b\u7684\u8868\u73b0\u3002</li>\n    <li>\u65b9\u6cd5\u5305\u62ec\u4f7f\u7528\u53cc\u5411\u8de8\u6ce8\u610f\u529b\u54cd\u5e94\u6765\u5b9a\u4f4d\u66f4\u65b0\u548c\u4fdd\u7559\u9884\u5b9a\u4e49\u6743\u91cd\u4ee5\u534f\u8c03\u5956\u52b1\u3002</li>\n    <li>\u5b9e\u9a8c\u663e\u793a\uff0c\u8be5\u65b9\u6cd5\u5728\u8d28\u91cf\u3001\u4e00\u81f4\u6027\u548c\u540c\u6b65\u6027\u4e0a\u5747\u4f18\u4e8e\u4f20\u7edf\u7684\u5f3a\u5316\u5b66\u4e60\u57fa\u7ebf\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Multi-reward guided reinforcement learning helps improve joint audio-video models by focusing on quality, alignment, and synchronization.</li>\n    <li>Current methods struggle with fixed update locations and reward combinations that do not adapt during training.</li>\n    <li>The proposed Adaptive Reward Routing method adjusts both where updates happen and how rewards are coordinated during training.</li>\n    <li>It includes two main techniques: using cross-attention to guide updates and preserving certain reward weights while adjusting others.</li>\n    <li>Tests show that this approach leads to better quality, consistency, and synchronization in audio-video models compared to existing methods.</li>\n</ul>"}, "publishedAt": "2026-09-28T20:00:00.000Z", "title": "Adaptive Reward Routing: Dynamic Multi-Reward Optimization for Joint Audio-Video Diffusion via Forward-Process RL", "summary": "Multi-reward guided reinforcement learning (i.e., RL) offers a promising way to improve joint audio-video diffusion models along several complementary objectives, including modality-specific quality, cross-modal semantic alignment, and temporal synchronization. Its effectiveness, however, depends on two quantities that change during training: where reward-driven updates should act, and how competing rewards should be combined. Existing methods tend to rely on fixed routing and reward weights, failing to track evolving model functions. To address these limitations, we propose Adaptive Reward Routing to jointly adapt update locations and reward coordination during forward-process RL (i.e., DiffusionNFT) of joint audio-video diffusion models. Our method consists of two components. (i) Cross-Modal Influence-Guided Routing (Localizing Updates): We use bidirectional cross-attention responses as an efficient proxy for evolving cross-modal influence, dynamically reweighting token-aware losses and scaling gradients across cross-modal layers without additional model interventions. (ii) Preference-Preserving Modality-Aware Reweighting (Coordinating Rewards): We preserve predefined weights as preference priors and use branch-specific reward-gradient interactions as residual corrections after warm-up. This resolves evolving conflicts without letting dominant rewards suppress weak but essential objectives. Extensive experiments demonstrate consistent improvements in modality quality, semantic consistency, and audio-video synchronization over strong RL baselines. Ablations and mechanism analyses further validate the complementary benefits of adaptive update routing and reward coordination.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.37200.png", "numComments": 1, "submittedBy": {"_id": "66f64956ad4fe83c91776459", "avatarUrl": "/avatars/2014de658ac12413754dcf70bc34333e.svg", "fullname": "Eddie", "name": "EddieYang428", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2609.17708", "authors": [{"_id": "6aab84f51d9cc4dec796258e", "name": "Caiqi Zhang", "hidden": false}, {"_id": "6aab84f51d9cc4dec796258f", "name": "Xiaochen Zhu", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962590", "name": "Chengzu Li", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962591", "name": "Yulong Chen", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962592", "name": "Dharshan Kumaran", "hidden": false}, {"_id": "6aab84f51d9cc4dec7962593", "name": "Nigel Collier", "hidden": false}], "publishedAt": "2026-09-15T00:00:00.000Z", "submittedOnDailyAt": "2026-09-17T00:00:00.000Z", "title": "Confidence Comes from Experience: Experiential Confidence Estimation from Reasoning to Agents", "submittedOnDailyBy": {"_id": "63920dfac47e36ddeb8f1864", "avatarUrl": "/avatars/c36cbf7b084d62368312e5c9292e4260.svg", "isPro": false, "fullname": "Caiqi Zhang", "user": "caiqizh", "type": "user", "name": "caiqizh"}, "summary": "Reliable confidence estimation is increasingly central to the trustworthy deployment of language models: a calibrated estimate of the probability that an output is correct decides what to ship, what to escalate, and what to retry. Existing confidence estimators, however, share one design premise: they only read the current inference process, either by introspecting on it, scoring its token probabilities, or resampling it. We argue that the current inference is not a sufficient basis for confidence. We propose XConf (eXperiential Confidence): estimating confidence together with the model's accumulated experience. The experience is stored as a record of the model's own graded past episodes, each holding the task, the model's reflection, its stated confidence, the outcome, and a lesson written once the grade arrived. Given a new task, XConf's Recall stage retrieves past episodes on similar tasks met with a similar stated confidence, and reads off their historical success rate; its Reflect stage shows the model this record, has it name its recurring failure mode, and restate a confidence now informed by its own track records. Our estimator is format-general, requiring no logit access or weight updates, and costs only one answer generation. Across nine benchmarks spanning reasoning, coding, multimodal QA, and interactive agents, and four models from three families, XConf beats or matches ten-sample self-consistency in discrimination (AUROC) on 23 of 24 comparisons, with much lower calibration error (ECE), at a tenth of the generation cost. Used for selective prediction, abstaining on the 10% least-confident episodes raises the delivered success rate by up to 8.7 points on agent tasks. We therefore see experiential confidence estimation as a new paradigm for future general-purpose confidence estimation.", "upvotes": 49, "discussionId": "6aab84f61d9cc4dec7962594", "projectPage": "https://caiqizh.github.io/xconf/", "githubRepo": "https://github.com/caiqizh/xconf", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "65f9e02087d1c912d985eebf", "name": "CambUni", "fullname": "University of Cambridge", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/gdCou-0KoYsLPYqPrz6xn.png"}, "summary_zh": "<ul>\n    <li>\u53ef\u9760\u7684\u4fe1\u5fc3\u4f30\u8ba1\u5bf9\u8bed\u8a00\u6a21\u578b\u7684\u53ef\u9760\u90e8\u7f72\u8d8a\u6765\u8d8a\u91cd\u8981\u3002</li>\n    <li>\u73b0\u6709\u7684\u4fe1\u5fc3\u4f30\u8ba1\u65b9\u6cd5\u53ea\u5173\u6ce8\u5f53\u524d\u63a8\u7406\u8fc7\u7a0b\uff0c\u4e0d\u80fd\u5145\u5206\u53cd\u6620\u6a21\u578b\u7684\u4fe1\u5fc3\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86XConf\uff08\u7ecf\u9a8c\u4fe1\u5fc3\uff09\uff0c\u7ed3\u5408\u6a21\u578b\u7684\u5386\u53f2\u7ecf\u9a8c\u6765\u8bc4\u4f30\u4fe1\u5fc3\u3002</li>\n    <li>XConf\u901a\u8fc7\u56de\u5fc6\u76f8\u4f3c\u4efb\u52a1\u7684\u5386\u53f2\u8bb0\u5f55\uff0c\u5e2e\u52a9\u6a21\u578b\u53cd\u601d\u5e76\u8c03\u6574\u4fe1\u5fc3\u4f30\u8ba1\u3002</li>\n    <li>\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\uff0cXConf\u5728\u4fe1\u5fc3\u4f30\u8ba1\u4e0a\u8868\u73b0\u4f18\u4e8e\u4f20\u7edf\u65b9\u6cd5\uff0c\u5e76\u4e14\u751f\u6210\u6210\u672c\u66f4\u4f4e\u3002</li>\n</ul>", "summary_simple": "<ul>\n  <li>Confidence estimation is important for using language models effectively and deciding which outputs to trust.</li>\n  <li>Current methods only look at the model's immediate performance, which may not be enough for accurate confidence assessment.</li>\n  <li>XConf (eXperiential Confidence) uses the model's past experiences to improve confidence estimates by recalling similar past tasks and their outcomes.</li>\n  <li>XConf is flexible, doesn't require complex adjustments, and can produce better confidence estimates at a lower cost than existing methods.</li>\n  <li>Using XConf can significantly improve success rates in tasks by allowing the model to be more selective about its predictions.</li>\n</ul>"}, "publishedAt": "2026-09-14T20:00:00.000Z", "title": "Confidence Comes from Experience: Experiential Confidence Estimation from Reasoning to Agents", "summary": "Reliable confidence estimation is increasingly central to the trustworthy deployment of language models: a calibrated estimate of the probability that an output is correct decides what to ship, what to escalate, and what to retry. Existing confidence estimators, however, share one design premise: they only read the current inference process, either by introspecting on it, scoring its token probabilities, or resampling it. We argue that the current inference is not a sufficient basis for confidence. We propose XConf (eXperiential Confidence): estimating confidence together with the model's accumulated experience. The experience is stored as a record of the model's own graded past episodes, each holding the task, the model's reflection, its stated confidence, the outcome, and a lesson written once the grade arrived. Given a new task, XConf's Recall stage retrieves past episodes on similar tasks met with a similar stated confidence, and reads off their historical success rate; its Reflect stage shows the model this record, has it name its recurring failure mode, and restate a confidence now informed by its own track records. Our estimator is format-general, requiring no logit access or weight updates, and costs only one answer generation. Across nine benchmarks spanning reasoning, coding, multimodal QA, and interactive agents, and four models from three families, XConf beats or matches ten-sample self-consistency in discrimination (AUROC) on 23 of 24 comparisons, with much lower calibration error (ECE), at a tenth of the generation cost. Used for selective prediction, abstaining on the 10% least-confident episodes raises the delivered success rate by up to 8.7 points on agent tasks. We therefore see experiential confidence estimation as a new paradigm for future general-purpose confidence estimation.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2609.17708.png", "numComments": 2, "submittedBy": {"_id": "63920dfac47e36ddeb8f1864", "avatarUrl": "/avatars/c36cbf7b084d62368312e5c9292e4260.svg", "fullname": "Caiqi Zhang", "name": "caiqizh", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "65f9e02087d1c912d985eebf", "name": "CambUni", "fullname": "University of Cambridge", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/gdCou-0KoYsLPYqPrz6xn.png"}, "isAuthorParticipating": false}]
};
